For a square matrix $\mathbf{M}$ with singular value decomposition $\mathbf{M} = \mathbf{U \Sigma V}^{\top}$, we write $\mathrm{sgn}(\mathbf{M})$ to denote the \emph{matrix sign function} of $\mathbf{M}$, defined via
\begin{align}
    \mathrm{sgn}(\mathbf{M}) \coloneqq \mathbf{UV}^{\top}. \label{sgnfunction}
\end{align}

We write $\mathcal{M}_k(\mathcal{T})$ as the \emph{matricization} of $\mathcal{T}$ along its $k$'th mode, so that $\mathcal{M}_k(\mathcal{T})$ satisfies
\begin{align*}
    \big(\mathcal{M}_k(\mathcal{T}) \big)_{i_kj} = \mathcal{T}_{i_1i_2i_3}; \qquad j = 1 + \sum_{l=1,l\neq k}^{3} \bigg\{ (i_l-1) \prod_{m=1,m\neq k}^3 p_m \bigg\},
\end{align*}
where $p_k$ are the dimensions of the tensor.

The mode-one  product of a tensor $\mathcal{T}\in\mathbb{R}^{p_1 \times p_2 \times p_3}$ with a matrix ${\mathbf{U}}\in \mathbb{R}^{p_1 \times r_1}$ is denoted $\mathcal{T} \times_1 {\mathbf{U}}^{\top} \in \mathbb{R}^{r_1 \times p_2 \times p_3}$ as is defined by
\begin{align*}
    \big( \mathcal{T} \times_1 {\mathbf{U}}^{\top} \big)_{ji_2i_3} &= \sum_{i_1=1}^{p_k} \mathcal{T}_{i_1i_2i_3} {\mathbf{U}}_{i_1j},
\end{align*}
with other mode-wise products defined similarly.

We let $\lambda_{\min}(\mathcal{T})$ denote the smallest nonzero singular value along each  matricization of $\mathcal{T}$, and we let $\kappa$ denote the condition number defined via
\begin{align*}
    \kappa := \max_k \frac{\| \mathcal{M}_k(\mathcal{T})\|}{\lambda_{r_k}(\mathcal{M}_k(\mathcal{T}))}.
\end{align*}

The \emph{incoherence parameter} of $\mathcal{T}$ with Tucker decomposition $\mathcal{T} = \mathcal{C}\times_1 {\mathbf{U}}_1\times_2 {\mathbf{U}}_2 \times_3 {\mathbf{U}}_3$ is given by the smallest number $\mu_0$ such that
\begin{align*}
    \max_k \sqrt{\frac{p_k}{r_k}} \| {\mathbf{U}}_k \|_{2,\infty} \leq \mu_0.
\end{align*}

\caption{Higher-Order Orthogonal Iteration (\texttt{HOOI})}
\begin{algorithmic}[1]
	\State Input: $\mathcal{\widetilde{T}}\in \mathbb{R}^{p_1 \times p_2 \times p_3}$, Tucker rank $\boldsymbol{r} = (r_1, r_2,r_3)$, initialization $\mathbf{\widehat{U}}_2^{(0)}, \mathbf{\widehat{U}}_3^{(0)}$.  
	\Repeat
	\State Let $t = t+1$
	\For {$k=1,2,3$}
	\begin{equation*}
	\mathbf{\widehat{U}}_k^{(t)} = 
	{\rm SVD}_{r_k}\left(\mathcal{M}_k\left(\mathcal{\widehat{T}}\times_{k' < k} (\mathbf{\widehat{U}}_{k'}^{(t)})^\top \times_{k'>k} (\mathbf{\widehat{U}}_{k'}^{(t-1)})^\top\right)\right).
	\end{equation*}
	\EndFor
	\Until Convergence or the maximum number of iterations is reached.
	\State Set 
	\begin{align*}
	    \mathcal{\widehat T} &\coloneqq \mathcal{\widetilde T}  \times_1 \mathbf{\widehat{U}}_1^{(t_{\max})} \times_2 \mathbf{\widehat{U}}_2^{(t_{\max})} \times_3 \mathbf{\widehat{U}}_3^{(t_{\max})}
	\end{align*}
	\State Output: $\mathbf{\widehat{U}}_k^{(t_{\max})}$, estimated  tensor $\mathcal{\widehat T}$
\end{algorithmic}\label{al:tensor-power-iteration}

	\caption{Diagonal-Deletion Initialization}
	\begin{algorithmic}[1]
		\State Input: $\mathcal{\widehat{T}}\in \mathbb{R}^{p_1 \times p_2 \times p_3}$, Tucker rank $\boldsymbol{r} = (r_1, r_2,r_3)$.
		\For {$k=2,3$}
		\State Set $\mathbf{\widehat{U}}_k^{(0)}$ as the leading $r_k$ eigenvectors of the matrix $\mathbf{\widehat{G}}_k$, with
		\begin{align*}
		\mathbf{\widehat{G}}_k \coloneqq 
	 \Gamma\big(\mathcal{M}_k ( \mathcal{\widehat{T}}) \mathcal{M}_k(\mathcal{\widehat{T}})^{\top} \big), \qquad &\text{where $\Gamma(\cdot)$ is the \emph{hollowing operator} that sets} \\
  \qquad &\text{the diagonal of ``$\cdot$" to zero;}
		\end{align*}
		\EndFor
		\State Output: $\mathbf{\widehat{U}}_k^{(0)}$.
	\end{algorithmic}\label{al:dd}

\begin{align*}
		\mathbf{\widehat{G}}_k \coloneqq 
	 \Gamma\big(\mathcal{M}_k ( \mathcal{\widehat{T}}) \mathcal{M}_k(\mathcal{\widehat{T}})^{\top} \big), \qquad &\text{where $\Gamma(\cdot)$ is the \emph{hollowing operator} that sets} \\
  \qquad &\text{the diagonal of ``$\cdot$" to zero;}
		\end{align*}

We assume that we observe
\begin{align*}
    \widetilde{\mathcal{T}} = \mathcal{T} + \mathcal{Z},
\end{align*}
where $\mathcal{T}, \mathcal{Z} \in \mathbb{R}^{p_1\times p_2\times p_3}$ are order three tensors, $\mathcal{T}$ has Tucker rank $\boldsymbol{r} = (r_1,r_2,r_3)$ of the form
\begin{align*}
    \mathcal{T} = \mathcal{C} \times_1 {\mathbf{U}}_1 \times_2 {\mathbf{U}}_2 \times_3 {\mathbf{U}}_3;
\end{align*}
(see \cref{sec:notation}), and $\mathcal{Z}$ consists of independent, heteroskedastic noise.

Define the signal-strength parameter:
\begin{align*}
    \lambda &\coloneqq \lambda_{\min}(\mathcal{T});
\end{align*}
that is, $\lambda$ is the smallest nonzero singular value of each matricization of the signal tensor $\mathcal{T}$.

we define $\mathbf{W}_k^{(t)}$ as the orthogonal matrix satisfying
\begin{align*}
    \mathbf{W}_k^{(t)} &\coloneqq \mathop{\rm arg\min}_{\mathbf{WW}^{\top} = \mathbf{I}_{r_k}} \| \mathbf{\widehat{U}}_k^{(t)} - {\mathbf{U}}_k \mathbf{W} \|_F.

 \label{thm:eigenvectornormality_v1}
Suppose that $r \lesssim p^{1/2} $and $\lambda/\sigma \gtrsim p^{3/4} \sqrt{\log(p)}$, \textcolor{black}{and that $\lambda/\sigma \leq \exp(c p)$ for some small constant $c$}. Suppose that $\kappa,\mu_0 = O(1)$, and let $\mathbf{\widehat{U}}_k^{(t)}$ denote the estimated singular vectors from the output of \texttt{HOOI} (\cref{al:tensor-power-iteration}) with $t \asymp \textcolor{black}{\log( \frac{\lambda/\sigma}{C \sqrt{p\log(p)}})} $
iterations, initialized via \cref{al:dd}.  Suppose $\mathbf{T}_k = \mathcal{M}_k(\mathcal{T})$ has rank $r_k$ singular value decomposition ${\mathbf{U}}_k \mathbf{\Lambda}_k \mathbf{V}_k^{\top}$.  Denote $\mathbf{Z}_k = \mathcal{M}_k(\mathcal{Z})$.  Then there exists an event  $\mathcal{E}_{\mathrm{\cref{thm:eigenvectornormality_v1}}}$ with $\mathbb{P}(\mathcal{E}_{\mathrm{\cref{thm:eigenvectornormality_v1}}}) \geq 1 - O(p^{-9})$ such that on this event for each $k$ it holds that
\begin{align*}
    \mathbf{\widehat{U}}_k^{(t)} (\mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k &=\mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} + \mathbf{\Psi}^{(k)},
\end{align*}
where
\begin{align*}
    \| \mathbf{\Psi}^{(k)} \|_{2,\infty} \lesssim \frac{\sigma^2 \log(p) r \sqrt{p}}{\lambda^2} + \frac{\sigma r}{\lambda \sqrt{p}}.
\end{align*}

 It has been demonstrated in \cite{zhang_tensor_2018} that when $\lambda/\sigma \gtrsim p^{3/4}$, \texttt{HOOI} achieves the error rate
 \begin{align*}
     \| \mathbf{\widehat{U}}_k^{(t)}  - {\mathbf{U}}_k \mathbf{W}_k^{(t)} \|_F &\lesssim \frac{\sqrt{r_k p_k}}{\lambda/\sigma} =  O\bigg( \frac{\sqrt{p_k}}{\lambda/\sigma}\bigg)
 \end{align*}
 provided $r = O(1)$.   More recently, it was demonstrated in \cite{agterberg_estimating_2022} that when $\lambda/\sigma \gtrsim p^{3/4} \sqrt{\log(p)}$ that
 \begin{align*}
     \max_{1\leq m\leq p_k} \| \big(\mathbf{\widehat{U}}_k^{(t)}  - {\mathbf{U}}_k \mathbf{W}_k^{(t)} \big)_{m\cdot} \| &\lesssim \frac{\sqrt{r_k \log(p)}}{\lambda/\sigma} = \widetilde O\bigg( \frac{1}{\lambda/\sigma} \bigg)
 \end{align*}
 assuming that $\kappa,\mu_0, r = O(1)$. In contrast, \cref{thm:eigenvectornormality_v1} demonstrates that
 \begin{align*}
\max_{1\leq m\leq p_k}\bigg\| \bigg(     \mathbf{\widehat{U}}_k^{(t)}( \mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k - \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \bigg)_{m\cdot}\bigg\| &\lesssim \frac{\sigma^2 \log(p) r\sqrt{p}}{\lambda^2} + \frac{\sigma r }{\lambda \sqrt{p}}\\&= \widetilde o \bigg( \frac{1}{\lambda/\sigma} \bigg).
 \end{align*}
 Consequently, \cref{thm:eigenvectornormality_v1} demonstrates precisely how well the additional first-order correction term $\mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1}$ can be used to approximate the estimated singular vectors.

\label{remark:snr}
Such a leading-order expansion has also been developed for symmetric matrix denoising in  \cite{chen_spectral_2021} when both the row and column dimensions are of comparable size.  One natural point of comparison is the corresponding error estimates for HOSVD (higher-order singular value decomposition), or similar procedures.  In the tensor setting with $p_k \asymp p$, each matricization is of order $p \times p^2$, and the column dimension can be much larger than the row dimension.  \textcolor{black}{Therefore, when comparing asymptotic results for a $p \times p \times p$ tensor to asymptotic results for a $p_1 \times p_2$ matrix, the most natural point of comparison is to take $p_1 \asymp p$ and $p_2 \asymp p^2$.  In the subsequent discussion we will focus on matrices of dimension $p_1 \times p_2$, but to translate the results to tensors, we will consider a generic $p \times p \times p$ tensor, with $p_1 \asymp p$ and $p_2 \asymp p^2$.  }

In \cite{agterberg_entrywise_2022}, who study entrywise singular vector analyses of rectangular matrices \textcolor{black}{of dimension $p_1 \times p_2$, it was shown that when $\lambda/\sigma \gtrsim \sqrt{p_{\max} \log(p_{\max})}$ (which translates to the condition $\lambda/\sigma \gtrsim p \sqrt{\log(p)}$))}, that one has a leading-order expansion similar to the one presented in \cref{thm:eigenvectornormality_v1} (see their equation 3) for estimated singular vectors.  However, the SNR condition in \cite{agterberg_entrywise_2022} may be too stringent for tensors, particularly in the high-noise regime $\lambda/\sigma \asymp p^{3/4} {\rm polylog}(p)$. In \cite{yan_inference_2021}, it was shown that when $\lambda/\sigma \asymp  (p_1 p_2)^{3/4}  {\rm polylog}(p)$ \textcolor{black}{(which translates to the condition $\lambda/\sigma \gtrsim p^{3/4} {\rm polylog}(p)$)}, that one has the leading-order expansion
\begin{align*}
    \mathbf{\widehat{U}}_k^S \mathbf{W}_k - {\mathbf{U}}_k &= \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} + \Gamma( \mathbf{Z}_k \mathbf{Z}_k^{\top} ) {\mathbf{U}}_k \mathbf{\Lambda}_k^{-2} + \mathbf{\widetilde \Psi}^{(k)},
\end{align*}
where $\mathbf{\widetilde \Psi}^{(k)}$ is a residual term, $\mathbf{\widehat{U}}_k^S$ are estimates of the left singular vectors of the underlying low-rank matrix obtained via the \texttt{HeteroPCA} algorithm, and $\mathbf{Z}_k$ and $\mathbf{\Lambda}_k$ are the noise matrix and singular value matrix respectively. Observe that the term containing  $\Gamma(\mathbf{Z}_k \mathbf{Z}_k^{\top})$ is quadratic in the noise $\mathbf{Z}_k$--this additional quadratic term is dominant in the high-noise regime.    

Therefore, \cref{thm:eigenvectornormality_v1} demonstrates how \texttt{HOOI} uses the tensorial structure to effectively eliminate the additional (dominant) ``quadratic'' term in the regime $p \gtrsim \lambda/\sigma \gtrsim p^{3/4}$.
These results \textcolor{black}{(modulo logarithmic terms)} are summarized in Table \ref{tbl:eigenvectorcomparison}.

\label{thm:eigenvectornormality2_v1}
Instate the conditions of \cref{thm:eigenvectornormality_v1}.  
Let $\Sigma^{(m)}_k$ denote the diagonal matrix of dimension $p_{-k} \times p_{-k}$, where the diagonal entries consist of the variances of $\mathcal{Z}_{mbc}$ if $k = 1$, $\mathcal{Z}_{amc}$ if $k = 2$, and $\mathcal{Z}_{abm}$ if $k =3$.  Define
\begin{align*}
    \mathbf{\Gamma}^{(m)}_k &\coloneqq \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \Sigma^{(m)}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1}.
\end{align*}
 Let $\mathcal{A}$ denote the collection of convex sets in $\mathbb{R}^{r_k}$, and let $Z$ be an $r_k$-dimensional Gaussian random variable with the identity covariance matrix.  
  Then it holds that
\begin{align*}
    \sup_{A \in \mathcal{A}} \bigg| &\mathbb{P}\bigg\{ (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \bigg( \mathbf{\widehat{U}}_k^{(t)}(\mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k \bigg)_{m\cdot} \in A \bigg\} - \mathbb{P}\{ Z \in A \} \bigg| \\
    &\lesssim  \frac{\sigma \log(p) r^{3/2} \sqrt{p}}{\lambda} + \frac{r^{3/2}}{\sqrt{p}}.
\end{align*}

\caption{Confidence Regions for $({\mathbf{U}}_k)_{m\cdot}$}
\begin{algorithmic}[1]
	\State Input:  Singular vector estimate $\mathbf{\widehat{U}}_k$ and tensor estimate $\mathcal{\widehat T}$ from \cref{al:tensor-power-iteration}, coverage level $1 - \alpha$  

		\State Let $\mathbf{\widehat V}_k$ and $\mathbf{\widehat \Lambda}_k$ denote the $r_k$ right singular vectors and singular values of the matrix
	\begin{align*}
	    \mathcal{M}_k\big(  \mathcal{\widetilde T} \big) \bigg( \big(\mathbf{\widehat{U}}_{k+1} \mathbf{\widehat{U}}_{k+1}^{\top} \big) \otimes \big(\mathbf{\widehat{U}}_{k+2} \mathbf{\widehat{U}}_{k+2}^{\top} \big) \bigg).
	\end{align*}
\State Define $\mathcal{\widehat Z} = \mathcal{\widetilde T} - \mathcal{\widehat T}$, and set $\widehat \Sigma^{(m)}_k$ as the diagonal matrix of entries defined via:
	\begin{align*}
	    \bigg(\widehat \Sigma^{(m)}_1 \bigg)_{(a-1)p_3 + b} = 		    \mathcal{\widehat Z}^2_{mab};\qquad
	     \bigg(\widehat \Sigma^{(m)}_2 \bigg)_{(b-1)p_1 + a} &= 		    \mathcal{\widehat Z}^2_{amb}; \qquad 
	        \bigg(\widehat \Sigma^{(m)}_3 \bigg)_{(a-1)p_2 + b} = 		    \mathcal{\widehat Z}^2_{amb}.
	\end{align*}
	\State Define
	\begin{align*}
	    \mathbf{\widehat \Gamma}_k^{(m)} \coloneqq \mathbf{\widehat \Lambda}_k^{-1} \mathbf{\widehat V}_k^{\top} \widehat \Sigma^{(m)}_k \mathbf{\widehat V}_k \mathbf{\widehat \Lambda}_k^{-1};
	\end{align*}
	\State Compute the $1 - \alpha$ quantile $\tau_{\alpha}$ of $\chi^2_{r_k}$ random variable, and construct the ball $\mathcal{B}_{1-\alpha} \coloneqq \{z: \|z\|^2 \leq \tau_{\alpha}\}$
	\State Output the confidence region
	\begin{align*}
	   \mathrm{C.R.}_{k,m}^{\alpha}(\mathbf{\widehat{U}}_k) &\coloneqq \mathbf{\widehat{U}}_k + \big(  \mathbf{\widehat \Gamma}_k^{(m)}  \big)^{1/2} \mathcal{B}_{1-\alpha} = \{ \mathbf{\widehat{U}}_k + \big(  \mathbf{\widehat \Gamma}_k^{(m)}  \big)^{1/2} z: z \in  \mathcal{B}_{1-\alpha} \}
	\end{align*}
	\end{algorithmic}\label{al:ci_eigenvector}

\begin{align*}
		    \bigg(\widehat \Sigma^{(m)}_1 \bigg)_{(a-1)p_3 + b} = 		    \mathcal{\widehat Z}^2_{mab};\qquad
		     \bigg(\widehat \Sigma^{(m)}_2 \bigg)_{(b-1)p_1 + a} &= 		    \mathcal{\widehat Z}^2_{amb}; \qquad 
		        \bigg(\widehat \Sigma^{(m)}_3 \bigg)_{(a-1)p_2 + b} = 		    \mathcal{\widehat Z}^2_{amb}.
		\end{align*}

\label{thm:civalidity2_v1}  Instate the conditions of \cref{thm:eigenvectornormality_v1}.  Suppose also that 
 \begin{align}
     r^{3/2}\sqrt{\log(p)} \lesssim p^{1/4}, \label{technicalcondition}
 \end{align}
 In addition, assume that 
 \begin{align*}
     \lambda/\sigma \gg \log^2(p) r^2 \sqrt{p}.
 \end{align*}
Let $\mathrm{C.R.}_{k,m}^{\alpha}(\mathbf{\widehat{U}}_k)$ denote the output of \cref{al:ci_eigenvector}.  Then it holds that
 \begin{align*}
   \mathbb{P}\bigg\{ \bigg( {\mathbf{U}}_k \mathbf{W}_k^{(t)}\bigg)_{m\cdot}  \in  \mathrm{C.R.}_{k,m}^{\alpha}(\mathbf{\widehat{U}}_k) \bigg\} = 1- \alpha  - o(1).
 \end{align*}

\label{thm:efficiencyloadings}
Suppose that $\mathcal{Z}$ consists of independent Gaussians with variance lower bounded by $\sigma_{\min}^2$, and suppose that $\kappa^2 \mu_0 \sqrt{\frac{r}{p}} \ll 1$.  Then if $( \mathbf{\widetilde {\mathbf{U}}}_k)_{m\cdot}$ is any unbiased estimator for $({\mathbf{U}}_k)_{m\cdot}$, it holds that
\begin{align*}
    \mathrm{Var}\big( (\mathbf{\widetilde {\mathbf{U}}}_k)_{m\cdot} \big) \succcurlyeq \sigma_{\min}^2 (1- o(1)) \mathbf{\Lambda}_k^{-2},
\end{align*}
where $A \succcurlyeq B$ refers to the positive semidefinite ordering.

Define the parameter space
 \begin{align*}
     \Theta( \lambda,&\kappa,\mu_0,\sigma,\sigma_{\min}) \\
     := \bigg\{ &\mathcal{T} \in \mathbb{R}^{p_1 \times p_2 \times p_3}: \mathcal{T} = \mathcal{S} \times_1 \mathbf{U}_1 \times_2 {\mathbf{U}}_2 \times_3 {\mathbf{U}}_3;\  \mathcal{S} \in \mathbb{R}^{r_1 \times r_2 \times r_3}; \\
  &\mathbf{U}_k \in \mathbb{R}^{p_k \times r_k}, {\mathbf{U}}_k^{\top} {\mathbf{U}}_k = \mathbf{I}_{r_k}; \| {\mathbf{U}}_k \|_{2,\infty} \leq \mu_0 \sqrt{\frac{r_k}{p_k}}; \\
  &\lambda \leq \lambda_{\min}(\mathcal{S}) \leq \lambda_{\max}(\mathcal{S}) \leq \kappa \lambda; \ \lambda/\sigma \geq C_0 \kappa r_{\max} \sqrt{p_{\max}}; \\
  &\sigma_{\min} \leq  \sigma_{ijk} \leq \sigma; \ \kappa \leq p_{\min}^{1/4}; \ r_{\max} \leq p_{\min}^{1/2} \bigg\}. \addtocounter{equation}{1}\tag{\theequation} \label{parameterspace}
 \end{align*}

\begin{align*}
     \Theta( \lambda,&\kappa,\mu_0,\sigma,\sigma_{\min}) \\
     := \bigg\{ &\mathcal{T} \in \mathbb{R}^{p_1 \times p_2 \times p_3}: \mathcal{T} = \mathcal{S} \times_1 \mathbf{U}_1 \times_2 {\mathbf{U}}_2 \times_3 {\mathbf{U}}_3;\  \mathcal{S} \in \mathbb{R}^{r_1 \times r_2 \times r_3}; \\
  &\mathbf{U}_k \in \mathbb{R}^{p_k \times r_k}, {\mathbf{U}}_k^{\top} {\mathbf{U}}_k = \mathbf{I}_{r_k}; \| {\mathbf{U}}_k \|_{2,\infty} \leq \mu_0 \sqrt{\frac{r_k}{p_k}}; \\
  &\lambda \leq \lambda_{\min}(\mathcal{S}) \leq \lambda_{\max}(\mathcal{S}) \leq \kappa \lambda; \ \lambda/\sigma \geq C_0 \kappa r_{\max} \sqrt{p_{\max}}; \\
  &\sigma_{\min} \leq  \sigma_{ijk} \leq \sigma; \ \kappa \leq p_{\min}^{1/4}; \ r_{\max} \leq p_{\min}^{1/2} \bigg\}. \addtocounter{equation}{1}\tag{\theequation} \label{parameterspace}
 \end{align*}

\label{thm:efficiency_order}
    Let $\xi \in \mathbb{R}^{r_k}$ be any deterministic vector satisfying $\max_{j\neq k} \frac{|\xi_j|}{|\xi_k|} \leq c_0$ for some fixed constant $c_0$, and suppose that  $\alpha$ satisfies $ 0 < \alpha < 1/2$. Then there is some constant $c > 0$ such that
    \begin{align*}
        \inf_{\mathrm{C.I.}_{k,m}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) \in \mathcal{I}_{\alpha}(\Theta,\xi)} \sup_{\mathcal{T} \in \Theta} \mathbb{E}_{\mathcal{T}} L\big( \mathrm{C.I.}_{k,m}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) \big) &\geq c \|\xi\|_{\infty} \frac{\sigma_{\min}}{\lambda_{r_k}}.
    \end{align*}

 \label{thm:asymptoticnormalityentries_v1}  Instate the conditions of \cref{thm:eigenvectornormality_v1}, and suppose further that
\begin{align*}
  r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
 Let $\Sigma^{(m)}_1 \in \mathbb{R}^{p_2 p_3 \times p_2 p_3}$ be the diagonal matrix whose $(a-1)p_3 + b$'th entry is the variance of the random variable $\mathcal{Z}_{mab}$, and let $\Sigma^{(m)}_2$ and $\Sigma^{(m)}_3$ be defined similarly.  Assume that
\begin{align*}
   \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2& + \|e_{(k-1)p_1 + i} \mathbf{V}_2  \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3\|^2 \\
   &\gg \max\bigg\{\frac{ r^4 \log(p)}{p^{3}} ,\frac{\sigma^2 r^{4} \log^2(p)}{\lambda^2 p}\bigg\}.
  \end{align*}
Define
\begin{align*}
    s^2_{ijk} &\coloneqq  \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} \big(\Sigma^{(i)}_1\big)^{1/2} \|^2 + \|e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \mathbf{V}_2^{\top}\big(\Sigma^{(j)}_2\big)^{1/2} \|^2\\
    &\quad + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3\mathbf{V}_3^{\top} \big( \Sigma^{(k)}_3 \big)^{1/2}\|^2.
\end{align*}
Let $Z$ denote a standard Gaussian random variable and let $\Phi$ denote its cumulative distribution function. Then it holds that
\begin{align*}
    \sup_{t\in\mathbb{R}} \bigg| \mathbb{P}\bigg\{ \frac{ \mathcal{\widehat T}_{ijk} - \mathcal{T}_{ijk}}{s_{ijk}} \leq t \bigg\} - \Phi(t) \bigg| &= o(1).  
\end{align*}

\begin{align*}
   \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2& + \|e_{(k-1)p_1 + i} \mathbf{V}_2  \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3\|^2 \\
   &\gg \max\bigg\{\frac{ r^4 \log(p)}{p^{3}} ,\frac{\sigma^2 r^{4} \log^2(p)}{\lambda^2 p}\bigg\}.
  \end{align*}

\begin{align*}
    s^2_{ijk} &\coloneqq  \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} \big(\Sigma^{(i)}_1\big)^{1/2} \|^2 + \|e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \mathbf{V}_2^{\top}\big(\Sigma^{(j)}_2\big)^{1/2} \|^2\\
    &\quad + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3\mathbf{V}_3^{\top} \big( \Sigma^{(k)}_3 \big)^{1/2}\|^2.
\end{align*}

\cref{thm:asymptoticnormalityentries_v1} can be compared to several results on entrywise distributional guarantees for low-rank matrices, such as Theorem 4.10 of \cite{chen_spectral_2021} or Theorem 6 of \cite{yan_inference_2021}. 
Informally, the proof of \cref{thm:asymptoticnormalityentries_v1} shows that we have the approximate asymptotic expansion
\begin{align*}
    \mathcal{T}_{ijk} - \mathcal{\widehat T}_{ijk} &\approx e_{i}^{\top} \mathbf{Z}_{1} \mathbf{V}_{1} \mathbf{V}_{1}^{\top} e_{(j-1) p_{3}+k}+e_{j}^{\top} \mathbf{Z}_{2} \mathbf{V}_{2} \mathbf{V}_{2}^{\top} e_{(k-1) p_{1}+i}+e_{k}^{\top} \mathbf{Z}_{3} \mathbf{V}_{3} \mathbf{V}_{3}^{\top} e_{(i-1) p_{2}+j}.
\end{align*}
Moreover, the asymptotic variance $s^2_{ijk}$ is simply the variance of each of the three leading-order terms, ignoring cross-terms.  While each of the three terms is not entirely uncorrelated (since they contain repetitions of elements of $\mathcal{Z}$), we show that this correlation is negligible due to the incoherence of singular vectors.  

On the other hand, by slightly modifying the results in, for example, \cite{chen_spectral_2021} or \cite{yan_inference_2021}, one can show that for a generic low-rank matrix $\mathbf{M = U \Lambda V^{\top}}$ of dimension $p_1 \times p_2$, with $p_1 \asymp p_2$,  one has the approximate first-order decomposition 
\begin{align*}
    \mathbf{M}_{ij} - \mathbf{\widehat M}_{ij} &\approx e_i^{\top} \mathbf{Z} \mathbf{V} \mathbf{V}^{\top} e_j + e_j^{\top} \mathbf{Z}^{\top} {\mathbf{U}} {\mathbf{U}}^{\top} e_i,
\end{align*}
where $\mathbf{\widehat M}$ is the truncated rank $r$ SVD of the observed matrix $\mathbf{M + Z}$, for $\mathbf{Z}$ consisting of independent noise.    Hence, in contrast to the matrix case, the tensor case results in \emph{three} (as opposed to two) leading-order perturbations, each of which is linear in the noise tensor $\mathcal{Z}$, which shows how the tensorial structure manifests in the asymptotics.

\begin{align*}
    \mathcal{T}_{ijk} - \mathcal{\widehat T}_{ijk} &\approx e_{i}^{\top} \mathbf{Z}_{1} \mathbf{V}_{1} \mathbf{V}_{1}^{\top} e_{(j-1) p_{3}+k}+e_{j}^{\top} \mathbf{Z}_{2} \mathbf{V}_{2} \mathbf{V}_{2}^{\top} e_{(k-1) p_{1}+i}+e_{k}^{\top} \mathbf{Z}_{3} \mathbf{V}_{3} \mathbf{V}_{3}^{\top} e_{(i-1) p_{2}+j}.
\end{align*}

 In addition to the signal-strength conditions from \cref{thm:eigenvectornormality_v1}, \cref{thm:asymptoticnormalityentries_v1} also requires a lower bound on the magnitude of the appropriate rows of the matrices $\mathbf{V}_k$. This condition implies a lower bound condition on the variance $s^2_{ijk}$ of the form
\begin{align*}
    s_{ijk} \gg \max\bigg\{ \frac{\sigma r^{3/2} \sqrt{\log(p)}}{p^{3/2}}, \frac{\sigma^2 r^2 \log(p)}{\lambda \sqrt{p}} \bigg\}.
\end{align*}
Ignoring factors of $r$ amounts to requiring that 
\begin{align*}
     s_{ijk} \gg \max\bigg\{ \frac{\sigma\sqrt{\log(p)}}{p^{3/2}}, \frac{\sigma^2 \log(p)}{\lambda \sqrt{p}} \bigg\}.
\end{align*}
A similar condition is required in the matrix setting in Theorem 4.10 of \cite{chen_spectral_2021} and Theorem 7 of \cite{yan_inference_2021}. Informally, this condition is required so that there is enough signal within that corresponding entry of the underlying tensor. In the more challenging regime $\lambda/\sigma \asymp p^{3/4}{\rm polylog}(p)$, this yields the condition
\begin{align*}
    s_{ijk} \gg \frac{\sigma}{p^{5/4} {\rm polylog}(p)}.
\end{align*}
Note that $s_{ijk}$ is of order $\sigma$ times the size of the maximum of the corresponding rows of $\mathbf{V}_k$.  Since $\| \mathbf{V}_k \|_{2,\infty} \lesssim  \frac{\sqrt{r}}{p}$ when $\mu_0 = O(1)$, we see that the corresponding rows are allowed to be as much as a factor of $p^{1/4} {\rm polylog}(p)$ smaller than the maximum row norm, which covers a wide range of possible values.  This regime is much broader than what is permitted in the matrix setting (e.g., Theorem 4.10 of \cite{chen_spectral_2021}).

