\label{cor:maxnormbound_v1}
Instate the conditions of \cref{thm:eigenvectornormality_v1}, and suppose that
\begin{align*}
     r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
Then the following bound holds with probability at least $1 - O(p^{-6})$:
\begin{align*}
    \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} &\lesssim \frac{\sigma \sqrt{r\log(p)}  }{p}  
    + \frac{\sigma^2  r^3 \log(p)}{\lambda \sqrt{p}}. 

\end{align*}
Consequently, when following condition holds:
\begin{align*}

   \lambda/\sigma \gtrsim   r^{5/2} \sqrt{p\log(p)},
\end{align*}
the bound above reduces to
\begin{align*}
     \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} &\lesssim \frac{ \sigma \sqrt{r\log(p)}}{p}.
\end{align*}

We say the signal tensor $\mathcal{T}$ is a \emph{tensor mixed-membership blockmodel} \citep{agterberg_estimating_2022} if
\begin{align*}
    \mathcal{T} = \mathcal{S} \times_1 \mathbf{\Pi}_1 \times_2 \mathbf{\Pi}_2 \times_3 \mathbf{\Pi}_3,
\end{align*}
where $\mathcal{S} \in \mathbb{R}^{r_1 \times r_2 \times r_3}$ is a \emph{mean tensor} and $\mathbf{\Pi}_k$ are \emph{mixed-membership matrices} satisfying
\begin{align*}
    \mathbf{\Pi}_k \in [0,1]^{p_k \times r_k}; \qquad \sum_{l=1}^{r_k} \big( \mathbf{\Pi}_k \big)_{i_k l} = 1  \text{ for all } 1 \leq i_k \leq p_k.

\begin{align*}
    \mathbf{\Pi}_k \in [0,1]^{p_k \times r_k}; \qquad \sum_{l=1}^{r_k} \big( \mathbf{\Pi}_k \big)_{i_k l} = 1  \text{ for all } 1 \leq i_k \leq p_k.
\end{align*}

Define
\begin{align*}
    \widehat T_{i_k i_k'} \coloneqq \big((\mathbf{\widehat{U}}_k)_{i_k\cdot} - (\mathbf{\widehat{U}}_k)_{i_k'\cdot} \big)^{\top} \bigg( \mathbf{\widehat \Gamma}_k^{(i_k)} + \mathbf{\widehat \Gamma}_k^{(i_k')} \bigg)^{-1} \big((\mathbf{\widehat{U}}_k)_{i_k\cdot} - (\mathbf{\widehat{U}}_k)_{i_k' \cdot} \big),
\end{align*}
where $\mathbf{\widehat{U}}_k$ is as in the previous section and $\mathbf{\widehat \Gamma}_k^{(i_k)}$ and $\mathbf{\widehat \Gamma}_k^{(i_k')}$ are the plug-in estimators from \cref{al:ci_eigenvector} (for the $i_k$'th and $i_k'$'th row of the singular vector estimates for mode $k$ respectively).

It is straightforward to check that
\begin{align*}
    \| (\mathbf{\Pi}_k)_{i_k\cdot} - (\mathbf{\Pi}_k)_{i_k'\cdot} \| = \sqrt{2},
\end{align*}
and, hence it holds that
\begin{align*}
    \frac{\lambda_{\min}(\mathcal{S}) p}{\sigma}  \| (\mathbf{\Pi}_k)_{i_k\cdot} - (\mathbf{\Pi}_k)_{i_k'\cdot} \| &\geq  p^{1/4}\sqrt{\log(p)},
\end{align*}
which diverges.

Our result can also be compared to Theorem 1 of \cite{fan_simple_2022}, where they prove (under a Bernoulli noise model), that their test statistic exhibits similar convergence in distribution (a similar result was obtained in \cite{du_hypothesis_2022}). Informally, their results demonstrate that 
\begin{align*}
    \sqrt{p}  \times  \mathrm{SNR} \times \| \mathbf{\Pi}_{i\cdot} - \mathbf{\Pi}_{j\cdot} \| \to \infty
\end{align*}
in order to achieve power converging to one, where their result holds for testing the $i$'th and $j$'th rows for a $p\times p$ symmetric matrix of the form $\mathbf{\Pi} \mathbf{B} \mathbf{\Pi}^{\top}$, and $\mathrm{SNR}$ denotes a measurement of the signal-to-noise ratio.  In contrast, our results demonstrate that
\begin{align*}
    p \times \mathrm{SNR} \times \| \big(\mathbf{\Pi}_k\big)_{i_k} - \big(\mathbf{\Pi}_k\big)_{i_k'} \| \to \infty
\end{align*}
is required 
in order to achieve power converging to one.  Therefore our result yields an improvement of order $\sqrt{p}$ in the local power of our test statistic.

