\end{align*}

define $\mathbf{\widetilde{U}}_k^{(S,j-m)}$ as the leading $r_k$ eigenvectors of the matrix
\begin{align*}
    \Gamma\big( \mathbf{T}_k \mathbf{T}_k^{\top} + \mathbf{Z}_k^{j-m} \mathbf{T}_k^{\top} + \mathbf{T}_k (\mathbf{Z}_k^{j-m})^{\top} + \mathbf{Z}_k^{j-m} (\mathbf{Z}_k^{j-m})^{\top} \big).

For a given iteration $t$, we set
\begin{align*}
    \mathbf{\widetilde{U}}_k^{(t,j-m)} = \begin{cases}
    \mathrm{SVD}_{r_1}\big( \mathbf{T}_1 + \mathbf{Z}_1^{j-m} \mathcal{P}_{\mathbf{\widetilde{U}}_{2}^{(t-1,j-m)} \otimes \mathbf{\widetilde{U}}_{3}^{(t-1,j-m)}} \big)& k = 1; \\
    \mathrm{SVD}_{r_2}\big( \mathbf{T}_2 + \mathbf{Z}_2^{j-m} \mathcal{P}_{\mathbf{\widetilde{U}}_{1}^{(t,j-m)} \otimes \mathbf{\widetilde{U}}_{3}^{(t-1,j-m)}} \big)& k =2; \\\mathrm{SVD}_{r_3}\big( \mathbf{T}_3 + \mathbf{Z}_3^{j-m} \mathcal{P}_{\mathbf{\widetilde{U}}_{1}^{(t,j-m)} \otimes \mathbf{\widetilde{U}}_{2}^{(t,j-m)}} \big)& k = 3. \end{cases}
\end{align*}

We also define the terms
 \begin{align*}
     \mathbf{L}_k^{(t)} &\coloneqq {\mathbf{U}}_{k\perp} {\mathbf{U}}_{k\perp}^{\top} \mathbf{Z}_k \mathcal{\widehat P}_k^{t} \mathbf{T}_k^{\top} \mathbf{\widehat{U}}_k^{(t)} \big( \mathbf{\widehat \Lambda}_k^{(t)}\big)^{-2}; \\
     \mathbf{Q}_k^{(t)} &\coloneqq {\mathbf{U}}_{k\perp} {\mathbf{U}}_{k\perp}^{\top} \mathbf{Z}_k \mathcal{\widehat P}_k^{t} \mathbf{Z}_k^{\top} \mathbf{\widehat{U}}_k^{(t)} \big( \mathbf{\widehat \Lambda}_k^{(t)}\big)^{-2},
 \end{align*}
 representing the \emph{linear error} and \emph{quadratic error} respectively.

 \label{sinthetaloo14}
In the setting of \cref{thm:twoinfty}, on the event $\mathcal{E}_{\mathrm{main}}^{t_0-1,k}$ it holds that for each $1 \leq j \leq 3$ and $1 \leq k \leq 3$ that
\begin{align*}
    \| \sin\Theta(\mathbf{\widehat{U}}_j^{(t)},\mathbf{\widetilde{U}}_j^{(t,k-m)}) \| \lesssim \frac{\kappa \sqrt{p_k \log(p)}}{\lambda} \mu_0 \sqrt{\frac{r_k}{p_j}}.
\end{align*}

The proof of Theorem 2 of \cite{agterberg_estimating_2022} shows that on the event $\mathcal{E}_{\mathrm{main}}^{t_0-1,k}$, for all $t \leq t_{\max} \asymp  C \log \bigg( \frac{\lambda}{C \kappa \sqrt{p\log(p)}} \bigg)$, one has the bound
\begin{align*}
    \| \sin\Theta(\mathbf{\widehat{U}}_j^{(t)}, \mathbf{\widetilde{U}}_j^{(t,k-m)}) \| \leq \frac{C_0 \kappa \sqrt{p_k\log(p)}}{\lambda} \mu_0 \sqrt{\frac{r_k}{p_j}} + \frac{1}{2^t} \mu_0 \sqrt{\frac{r_k}{p_j}}.
\end{align*}
For the choice of $t = C \log \bigg( \frac{\lambda}{C \kappa \sqrt{p\log(p)}} \bigg)$, it holds that
\begin{align*}
    \frac{1}{2^t} \leq \frac{C_0 \kappa \sqrt{p_k\log(p)}}{\lambda},
\end{align*}
which completes the proof, with the implicit constant $2 C_0$.

\label{lem:eigengaps}
Let $\mathbf{\Lambda}_k$ denote the diagonal matrix of leading $r_k$ nonzero singular values of $\mathbf{T}_k$, and let $\mathbf{\widehat \Lambda}_k^{(t)}$ denote the leading $r$ singular values of $(\mathbf{T}_k + \mathbf{Z}_k\big) \mathcal{\widehat P}_k^{(t)}.$ Under the conditions of \cref{thm:twoinfty}, tor all $t \geq 2$, on the event $\mathcal{E}_{{\mathrm{Good}}}$ it holds that
\begin{align*}
    \| \big(\mathbf{\widehat \Lambda}_k^{(t)} \big)^{-1} \| &\leq  \frac{2}{\lambda}.
\end{align*}

Without loss of generality, we prove the result for $k = 1$.  First, observe that on the event $\mathcal{E}_{\mathrm{Good}}$, it holds that under the assumptions $\lambda \geq C_0 \kappa p^{3/4} \sqrt{\log(p)}$ and $r \lesssim p^{1/2}$ that
    \begin{align*}
        \| \mathbf{Z}_1 \mathcal{\widehat P}_k^{(t)} \| \lesssim \sqrt{pr} \leq \lambda/8.
    \end{align*}
    As a result, letting $\mathbf{\widetilde \Lambda}_1^{(t)}$ denote the singular values of the matrix $\mathbf{T}_1 \mathcal{\widehat P}_1^{(t)}$, Weyl's inequality implies
    \begin{align*}
        \| \mathbf{\widetilde \Lambda}_1^{(t)} - \mathbf{\widehat \Lambda}_1^{(t)} \| \leq \frac{\lambda}{8}.
    \end{align*}
Furthermore, since by definition $\mathbf{T}_1 = \mathbf{T}_1 \mathcal{P}_{\mathbf{U}_{2} \otimes {\mathbf{U}}_{3}}$, we have that
\begin{align*}
  \lambda_{r_1} \bigg( \mathbf{T}_1 \mathcal{\widehat {P}}_1^{(t)} \bigg)  &=  \lambda_{r_1} \bigg(  \mathbf{T}_1\mathcal{P}_{\mathbf{U}_{2} \otimes {\mathbf{U}}_{3}} \mathcal{\widehat P}_1^{(t)} \bigg) \\
  &\geq \lambda_{r_1}\bigg(  \mathbf{T}_1 {\mathbf{U}}_{2} \otimes {\mathbf{U}}_{2} \bigg) \lambda_{\min} \bigg( \big( {\mathbf{U}}_{2} \otimes {\mathbf{U}}_{3} \big)^{\top}  \big( \mathbf{\widehat{U}}_{3}^{(t-1)} \otimes \mathbf{\widehat{U}}_{3}^{(t-1)} \big)  \bigg) \\
  &= \lambda_{r_1} \bigg( \mathbf{T}_1 \bigg) \lambda_{\min} \big( {\mathbf{U}}_2^{\top} \mathbf{\widehat{U}}_2^{(t)} \big) \lambda_{\min} \big( {\mathbf{U}}_3^{\top} \mathbf{\widehat{U}}_3^{(t)} \big).
\end{align*}
Next, by Lemma 1 of \cite{cai_rate-optimal_2018} it holds that
\begin{align*}
    \| \sin\Theta({\mathbf{U}}_2, \mathbf{\widehat{U}}_2^{(t)})\|^2 &= 1 - \lambda_{\min}\big( {\mathbf{U}}_2^{\top} \mathbf{\widehat{U}}_2^{(t)} \big)^2
\end{align*}
which implies that
\begin{align*}
    \lambda_{\min}\big( {\mathbf{U}}_2^{\top} \mathbf{\widehat{U}}_2^{(t)} \big) &= \sqrt{1 - \|\sin\Theta({\mathbf{U}}_2,\mathbf{\widehat{U}}_2^{(t)})\|^2} \geq \sqrt{1 - \frac{15}{64}} \geq \frac{7}{8},
\end{align*}
where we have used the fact that by \eqref{sinthetaegood}, on the event $\mathcal{E}_{\mathrm{Good}}$ one has
\begin{align*}
    \|\sin\Theta({\mathbf{U}}_2,\mathbf{\widehat{U}}_2^{(t)})\| \lesssim \frac{\delta_{\mathrm{L}}}{\lambda} \leq \frac{3}{8} \leq \sqrt{\frac{15}{64}}
\end{align*}
since $\lambda \gg \delta_{\mathrm{L}} = C_0 \kappa \sqrt{p\log(p)}$ by assumption.  By a similar argument, it holds that $\lambda_{\min}\big({\mathbf{U}}_3^{\top} \mathbf{\widehat{U}}_3^{(t)} \big) \geq \frac{7}{8}$.  
Therefore, this demonstrates that
\begin{align*}
    \lambda_{r_1} \bigg( \mathbf{T}_1 \mathcal{\widehat P}_1^{(t)} \bigg) \geq \lambda_{r_1} \bigg( \mathbf{T}_1 \bigg) \frac{49}{64} \geq \lambda_{r_1} \bigg( \mathbf{T}_1 \bigg) \frac{3}{4}.
\end{align*}
Consequently, combining these bounds, we see that
\begin{align*}
 \lambda_{r_1}\big( \mathbf{\widehat \Lambda}_1^{(t)} \big) &\geq \lambda_{r_1}\big(\mathbf{T}_1 \mathcal{\widehat P}_1^{(t)} \big) - \|  \mathbf{\widetilde \Lambda}_1^{(t)} - \mathbf{\widehat \Lambda}_1^{(t)} \| \geq \frac{5}{8} \lambda.
\end{align*}
As a result, one has that $\|(\mathbf{\widehat \Lambda}_1^{(t)})^{-1}\| \leq \frac{2}{\lambda}$ as required.

