    \bigg\| \mathbf{\Lambda}_k^2 {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k - {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k (\mathbf{\widehat{\Lambda}}_k^{(t)})^{2} \bigg\| &\lesssim \lambda_1 \sqrt{pr}.
\end{align*}

\begin{align*}
    \| {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k^{(t)} - \mathbf{W}_k^{(t)} \| &= \| \mathbf{W}_1 \mathbf{\Sigma} \mathbf{W}_2^{\top} - \mathbf{W}_1 \mathbf{W}_2^{\top} \| = \| \mathbf{\Sigma} - \mathbf{I} \| \\
    &= \max_{1\leq i \leq r} 1 - \cos\theta_i \leq \max_{1 \leq i\leq r} 1 - \cos^2 \theta_i = \max_{1\leq i \leq r} \sin^2\theta_i = \| \sin\Theta(\mathbf{\widehat{U}}_k^{(t)}, {\mathbf{U}}_k) \|^2.\addtocounter{equation}{1}\tag{\theequation} \label{sintheta14}
\end{align*}

 By \cref{thm:eigenvectornormality}, it holds that
\begin{align*}
    e_m^{\top} \bigg(\mathbf{\widehat{U}}_k^{(t)} (\mathbf{W}_k^{(t)} )^{\top} - {\mathbf{U}}_k\bigg) &= e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} + O\bigg( \frac{\sigma^2 \kappa^2 \mu_0^2 \log(p) r \sqrt{p}}{\lambda^2} + \frac{\mu_0 r \kappa \sigma}{\lambda \sqrt{p}}\bigg).
\end{align*}
It is straightforward to verify that the covariance of the vector $e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1}$ is given by 
\begin{align*}
    \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \Sigma^{(m)}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} = \mathbf{\Gamma}^{(m)}_k.
\end{align*}
It is also straightforward to note that 
\begin{align*}
    \lambda_{\min} \bigg( \mathbf{\Gamma}^{(m)}_k \bigg) &= \min_{x \in \mathbb{R}^{r_k}: \|x \| = 1} \| (\Sigma^{(m)}_k)^{1/2} \mathbf{V}_k \mathbf{\Lambda}_k^{-1} x \|^2 \\
    &\geq \sigma_{\min}^2 \| \mathbf{V}_k \mathbf{\Lambda}_k^{-1} x \|^2 \\
    &\geq \frac{\sigma_{\min}^2 }{\lambda^2}.
\end{align*}
Hence $\mathbf{\Gamma}^{(m)}_k$ is invertible, and its inverse has maximum eigenvalue at most $\lambda^2/\sigma_{\min}^2 \lesssim \lambda^2 \sigma^2$ by Assumption \ref{ass:noise}.  Therefore, we have that
\begin{align*}
    e_m^{\top} \bigg(& \mathbf{\widehat{U}}_k^{(t)} (\mathbf{W}_k^{(t)}) - {\mathbf{U}}_k \bigg) \big( \mathbf{\Gamma}^{(m)}_k \big)^{-1/2} \\
    &= e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big( \mathbf{\Gamma}^{(m)}_k \big)^{-1/2} + O\bigg( \frac{\sigma^2 \kappa^2 \mu_0^2 \log(p) r\sqrt{p}}{\lambda^2} \| (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \| \bigg) \\ 
    &\quad + O\bigg(  \frac{\sigma\mu_0 r \kappa}{\lambda \sqrt{p}}  \| (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \| \bigg) \\
    &= e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big( \mathbf{\Gamma}^{(m)}_k \big)^{-1/2} + O\bigg( \frac{\sigma \kappa^3 \mu_0^2 \log(p) r\sqrt{p}}{\lambda} + \frac{\mu_0 r \kappa}{\sqrt{p}} \bigg).
\end{align*}
We will apply Corollary 2.2 of \cite{shao_berryesseen_2022}, with (in their notation)
\begin{align*}
    \xi_l &= (\mathbf{Z}_k)_{ml} \bigg( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big( \mathbf{\Gamma}^{(m)}_k \big)^{-1/2} \bigg)_{l\cdot}; \\
    \Delta^{(l)} = \Delta &= C \bigg(\frac{\sigma \kappa^3 \mu_0^2 \log(p) r\sqrt{p}}{\lambda} + \frac{\mu_0 r \kappa}{\sqrt{p}}\bigg).
\end{align*}
By Corollary 2.2 of \cite{shao_berryesseen_2022}, it holds that
\begin{align*}
    \sup_{A \in \mathcal{A}} | &\mathbb{P}\bigg\{ e_m^{\top} \bigg( \mathbf{\widehat{U}}_k^{(t)} (\mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k \bigg) (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \in A \bigg\} - \mathbb{P} \{ Z \in A \} | \\
    &\lesssim r^{1/2} \sum_{l=1}^{p_{-k}} \mathbb{E} \| (\mathbf{Z}_k)_{ml} (\mathbf{V}_k \mathbf{\Lambda}_k^{-1} \mathbf{\Gamma}^{(m)}_k)^{-1/2}  )_{l\cdot}\|^3 \\
    &\quad + \bigg( \frac{\sigma\kappa^3 \mu_0^2 \log(p) r \sqrt{p}}{\lambda} + \frac{\mu_0 r \kappa}{\sqrt{p}} \bigg) \mathbb{E} \| e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1}(\mathbf{\Gamma}^{(m)}_k)^{-1/2} \| + O(p^{-9}),
\end{align*}
where $\mathcal{A}$ is the collection of convex sets in $\mathbb{R}^r$ and $Z$ is an $r$-dimensional Gaussian random vector with identity covariance. To bound the first term, observe that by subgaussianity (Proposition 2.5.2 of  \cite{vershynin_high-dimensional_2018}),
\begin{align*}
    \sum_{l=1}^{p_{-k}} &\mathbb{E} \| (\mathbf{Z}_k)_{ml} (\mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} )_{l\cdot}\|^3 \\
    &\lesssim \sigma^3 \sum_{l=1}^{p_{-k}} \| (\mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} )_{l\cdot}\|^3  \\
    &\lesssim \sigma^3 \max_{l} \| (\mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} )_{l\cdot}) \| \sum_{l=1}^{p_{-k}}  \| (\mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} )_{l\cdot}\|^2 \\
    &\lesssim \sigma^3 \| \mathbf{V}_k \|_{2,\infty} \frac{\| (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \|}{\lambda} \| \mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \|^2_F \\
    &\lesssim \sigma^3 \mu_0 \frac{\sqrt{r}}{p} \frac{\lambda/\sigma_{\min}}{\lambda} \| \mathbf{V}_k \|_F^2 \| \mathbf{\Lambda}_k^{-1} \|^2 \| \mathbf{\Gamma}^{(m)}_k)^{-1/2} \|^2 \\
    &\lesssim \sigma^3 \mu_0 \frac{\sqrt{r}}{p} \frac{1}{\sigma_{\min}} r \frac{\lambda^2/\sigma_{\min}^2}{\lambda^2} \\
    &\lesssim \frac{\sigma^3}{\sigma_{\min}^3} \frac{\mu_0 r^{3/2}}{p} \\
    &\lesssim \mu_0 \frac{r^{3/2}}{p},
\end{align*}
where we have used the fact that $\|\mathbf{V}_k\|^2_F = r$ and that $\sigma/\sigma_{\min} = O(1)$.  In addition, we note that
\begin{align*}
    \mathbb{E} \| e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \| &\lesssim \sqrt{r},
\end{align*}
since the vector $e_m^{\top}\mathbf{Z}_k\mathbf{V}_k \mathbf{\Lambda}_k^{-1} (\mathbf{\Gamma}^{(m)}_k)^{-1/2} $ is isotropic and subgaussian.  Therefore,
\begin{align*}
     \sup_{A \in \mathcal{A}} | &\mathbb{P}\bigg\{ e_m^{\top} \bigg( \mathbf{\widehat{U}}_k^{(t)} (\mathbf{W}_k^{(t)})^{\top} - {\mathbf{U}}_k \bigg) (\mathbf{\Gamma}^{(m)}_k)^{-1/2} \in A \bigg\} - \mathbb{P} \{ Z \in A \} | \\
    &\lesssim r^{1/2} \sum_{l=1}^{p_{-k}} \mathbb{E} \| (\mathbf{Z}_k)_{ml} (\mathbf{V}_k \mathbf{\Lambda}_k^{-1} \mathbf{\Gamma}^{(m)}_k)^{-1/2}  )_{l\cdot}\|^3 \\
    &\quad + \bigg( \frac{\sigma\kappa^3 \mu_0^2 \log(p) r \sqrt{p}}{\lambda} + \frac{\mu_0 r \kappa }{ \sqrt{p}}\bigg)\mathbb{E} \| e_m^{\top} \mathbf{Z}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1}(\mathbf{\Gamma}^{(m)}_k)^{-1/2} \| + O(p^{-9}) \\
    &\lesssim \mu_0 \frac{r^2}{p} + \frac{\sigma\kappa^3 \mu_0^2 \log(p) r^{3/2} \sqrt{p}}{\lambda}  + \frac{\mu_0 r^{3/2} \kappa }{ \sqrt{p}} + O(p^{-9}) \\
    &\lesssim \mu_0 \frac{r^2}{p} + \frac{\sigma\kappa^3 \mu_0^2 \log(p) r^{3/2} \sqrt{p}}{\lambda}  + \frac{\mu_0 r^{3/2} \kappa }{ \sqrt{p}}.
\end{align*}
This completes the proof.

