    \mathrm{Var}\bigg( &e_i^{\top} \mathbf{Z}_1 \mathbf{V}_1 \mathbf{V}_1^{\top} e_{(j-1)p_3 + k}\bigg) + \mathrm{Var}\bigg( e_j^{\top} \mathbf{Z}_2 \mathbf{V}_2 \mathbf{V}_2^{\top} e_{(k-1)p_1 + i} \bigg)  \\
    &\quad + \mathrm{Var}\bigg( e_k^{\top} \mathbf{Z}_3 \mathbf{V}_3 \mathbf{V}_3^{\top} e_{(i-1)p_2 + j} \bigg) \\
    &= \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} \big(\Sigma^{(i)}_1\big)^{1/2} \|^2 + \|e_{(k-1)p_1 + i} \mathbf{V}_2 \mathbf{V}_2^{\top} \big(\Sigma^{(j)}_2\big)^{1/2} \|^2 \\
    &\quad + \| e_{(i-1)p_2 + j} \mathbf{V}_3 \mathbf{V}_3^{\top} \big( \Sigma^{(k)}_3\big)^{1/2} \|^2 \\
    &= s_{ijk}^2.
\end{align*}
Therefore,
\begin{align*}
    \mathrm{Var}(\xi_{ijk}) &= s_{ijk}^2 + O\bigg( \frac{\sigma^2\mu_0^2 r}{p} \bigg(  \|e_{(j-1)p_3 + k} ^{\top} \mathbf{V}_1 \|^2 + \|e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3 \|^2 \bigg) \bigg), \\
    &= s^2_{ijk} + o( s^2_{ijk}),
\end{align*}
where the final inequality holds since 
\begin{align*}
    s^2_{ijk} &= \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} \big(\Sigma^{(i)}_1\big)^{1/2} \|^2 + \|e_{(k-1)p_1 + i} \mathbf{V}_2 \mathbf{V}_2^{\top} \big(\Sigma^{(j)}_2\big)^{1/2} \|^2 \\
    &\quad + \| e_{(i-1)p_2 + j} \mathbf{V}_3 \mathbf{V}_3^{\top} \big(\Sigma^{(k)}_3\big)^{1/2} \|^2  \\
    &\geq \sigma_{\min}^2 \bigg( \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1  \|^2 + \|e_{(k-1)p_1 + i} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3 \|^2 \bigg) \\
    &\gg \frac{\sigma^2\mu_0^2 r}{p} \bigg(  \|e_{(j-1)p_3 + k} ^{\top} \mathbf{V}_1 \|^2 + \|e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3 \|^2 \bigg) \bigg),
\end{align*}
since $\sigma/\sigma_{\min} = O(1)$ and $\mu_0^2 r \lesssim \sqrt{p}$.  Consequently, 
\begin{align}
    \frac{\mathrm{Var}(\xi_{ijk})}{s^2_{ijk}} &= 1 + O\bigg( \frac{\mu_0^2 r}{p} \bigg) \label{eq:taylor1}
\end{align}
which will be useful later on.






\item 
\textbf{Step 2: Third Moment Calculation}: 
In order to apply the Berry-Esseen Theorem, we will a bound on the third absolute moment of the sum of the independent random variables in question.  To avoid complicated notation, let $(b,c)$ be the index of the first matricization corresponding to its $(i,b,c)$ entry, and similarly for $(a,c)$ and $(a,b)$ (with second and third matricization and $j$ and $k$ replaced respectively).  We can then write
\begin{align*}
    \xi_{ijk} &= \sum_{b=1}^{p_2} \sum_{c=1}^{p_3} \mathcal{Z}_{ibc}\bigg[ (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k}  + \mathbb{I}_{\{b=j\}} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i} \\
    &\quad + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg] \\
    &\quad + \sum_{a\neq i, a=1}^{p_1} \sum_{c=1}^{p_3} \mathcal{Z}_{ajc} \bigg[ \big(\mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i} + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg] \\
    &\quad + \sum_{a\neq i, a=1}^{p_1} \sum_{b\neq j, b=1}^{p_2} \mathcal{Z}_{abk} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2+j},
\end{align*}
which, when written in this form, is precisely a sum of independent random variables. There are $O(p^2)$ many terms in this sum.  We will need to bound
\begin{align}
    \sum_{b=1}^{p_2}& \sum_{c=1}^{p_3}\mathbb{E} \bigg| \mathcal{Z}_{ibc}\bigg[ (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k}  + \mathbb{I}_{\{b=j\}} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i} \\
    &\quad + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg]\bigg|^3 \nonumber \\
    &\quad + \sum_{a\neq i, a=1}^{p_1} \sum_{c=1}^{p_3} \mathbb{E} \bigg| \mathcal{Z}_{ajc} \bigg[ \big(\mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i} + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg]\bigg|^3 \nonumber \\
    &\quad + \sum_{a\neq i, a=1}^{p_1} \sum_{b\neq j, b=1}^{p_2} \mathbb{E} \bigg| \mathcal{Z}_{abk} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2+j} \bigg|^3. \label{eq:toboundthirdmoment}
\end{align}
By subgaussianity (e.g., \cite{vershynin_high-dimensional_2018}, Proposition 2.5.2), it holds that
\begin{align*}
    \mathbb{E} \bigg|& \mathcal{Z}_{ibc}\bigg[ (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k}  + \mathbb{I}_{\{b=j\}} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i} \\
    &\quad + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg]\bigg|^3 \\
    &\leq \bigg| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k}  + \mathbb{I}_{\{b=j\}} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i}  \\
    &\quad + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg|^3 \mathbb{E} | \mathcal{Z}_{ibc}|^3 \\
    &\leq C \sigma^3 \bigg| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k}  + \mathbb{I}_{\{b=j\}} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i}  \\
    &\quad + \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg|^3 \\
    &\leq C' \sigma^3 \bigg( \bigg| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k} \bigg|^3 +  \bigg| \mathbb{I}_{\{b=j\}} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i}  \bigg|^3  \\
    &\quad +  \bigg| \mathbb{I}_{\{c = k \}} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2 + j} \bigg|^3 \bigg) 

\end{align*}
Substituting this bound into \cref{eq:toboundthirdmoment} and rearranging yields the upper bound
\begin{align}
    C' &\sigma^3 \Bigg[ \sum_{b,c} \big| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k} \big|^3 + \sum_{a,c} \big|\big(\mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i}\big|^3 \nonumber \\
    &\quad + \sum_{a,b} \big|\big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2+j} \big|^3 \Bigg] \nonumber \\
    &\leq C' \sigma^3 \bigg[ \max_{b,c} \big| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k} \big| \sum_{b,c} \big| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{(b,c),(j-1)p_3 + k} \big|^2 \nonumber \\
    &\qquad + \max_{a,c}  \big|\big(\mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i}\big| \sum_{a,c} \big|\big(\mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{(a,c),(k-1)p_1 + i}\big|^2 \nonumber \\
    &\qquad + \max_{a,b} \big|\big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2+j} \big| \sum_{a,b} \big|\big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{(a,b),(i-1)p_2+j} \big|^2 \Bigg]  \nonumber \\
    &\lesssim \sigma^3 \frac{\mu_0^2 r}{p^2} \bigg( \| \mathbf{V}_1 \mathbf{V}_1^{\top} e_{(j-1)p_3 + k} \|^2 + \| \mathbf{V}_2 \mathbf{V}_2^{\top} e_{(k-1)p_1 + i} \|^2 + \| \mathbf{V}_3 \mathbf{V}_3^{\top} e_{(i-1)p_2 + j} \|^2 \bigg) \label{eq:todivide}
\end{align}
In addition, we note that from the previous step it holds that
\begin{align*}
    \mathrm{Var}(\xi_{ijk}) &= s_{ijk}^2 + C \frac{\sigma^2 \mu_0^2 r}{p} \bigg( \left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1}\right\|^{2}+\left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2}\right\|^{2}+\left\|e_{(i-1) p_{2}+j} \mathbf{V}_{3}\right\|^{2} \bigg).
\end{align*}
This implies that there is some constant $c > 0$ such that
\begin{align*}
    \mathrm{{\rm var}}(\xi_{ijk})^{3/2} &\geq c s_{ijk}^{3}.
\end{align*}
Moreover,
\begin{align*}
    s_{ijk}^3 \geq \sigma_{\min}^3 \bigg( \left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1}\right\|^{2}+\left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2}\right\|^{2}+\left\|e_{(i-1) p_{2}+j} \mathbf{V}_{3}\right\|^{2} \bigg)^{3/2}.
\end{align*}
Therefore, dividing \eqref{eq:todivide} by the $\mathrm{Var}(\xi_{ijk})^{3/2}$ yields that
\begin{align*}
    &\frac{1}{\mathrm{Var}(\xi_{ijk})^{3/2}} \sigma^3 \frac{\mu_0^2 r}{p^2} \bigg( \| \mathbf{V}_1 \mathbf{V}_1^{\top} e_{(j-1)p_3 + k} \|^2 + \| \mathbf{V}_2 \mathbf{V}_2^{\top} e_{(k-1)p_1 + i} \|^2 + \| \mathbf{V}_3 \mathbf{V}_3^{\top} e_{(i-1)p_2 + j} \|^2 \bigg) \\
    &\lesssim \frac{1}{cs_{ijk}^3} \sigma^3 \frac{\mu_0^2 r}{p^2} \bigg( \| \mathbf{V}_1 \mathbf{V}_1^{\top} e_{(j-1)p_3 + k} \|^2 + \| \mathbf{V}_2 \mathbf{V}_2^{\top} e_{(k-1)p_1 + i} \|^2 + \| \mathbf{V}_3 \mathbf{V}_3^{\top} e_{(i-1)p_2 + j} \|^2 \bigg)  \\
    &\lesssim \frac{\mu_0^2 r}{p^2} \frac{\sigma^3}{\sigma_{\min}^3} \ \bigg( \left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1}\right\|^{2}+\left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2}\right\|^{2}+\left\|e_{(i-1) p_{2}+j} \mathbf{V}_{3}\right\|^{2} \bigg)^{-1/2} \\
    &\lesssim \frac{\mu_0^2 r}{p^2} \bigg( \left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1}\right\|^{2}+\left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2}\right\|^{2}+\left\|e_{(i-1) p_{2}+j} \mathbf{V}_{3}\right\|^{2} \bigg)^{-1/2} \\
    &\lesssim \frac{\mu_0^2 r }{p^2} \frac{p^{3/2}}{\kappa \mu_0^3 r^{3/2} \sqrt{\log(p)}} \\
    &\lesssim \frac{1}{\sqrt{p\log(p)}},
\end{align*}
where we have used the condition 
\begin{align*}
     \bigg( \left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1}\right\|^{2}+\left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2}\right\|^{2}+\left\|e_{(i-1) p_{2}+j} \mathbf{V}_{3}\right\|^{2} \bigg)^{1/2} \gg \frac{\kappa \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}}.
\end{align*}
\item 
\textbf{Step 3: Putting It All Together}: 
By the Berry-Esseen Theorem, for any $t \in \mathbb{R}$, it holds that
\begin{align*}
   \Bigg| \mathbb{P}\bigg\{ \frac{\xi_{ijk}}{s_{ijk}} \leq t \bigg\} - \Phi(t) \Bigg| &=  \Bigg| \mathbb{P}\bigg\{ \frac{\xi_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \leq t \frac{s_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \bigg\} - \Phi(t) \bigg| \\
    &\leq  \bigg| \mathbb{P}\bigg\{ \frac{\xi_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \leq t \frac{s_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \bigg\} - \Phi\bigg( t \frac{s_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \bigg) \bigg| \\
    &\quad + \bigg| \Phi(t) - \Phi\bigg( t \frac{s_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \bigg) \bigg| \\
    &\leq \frac{C}{\sqrt{p\log(p)}}  + \bigg| \Phi(t) - \Phi\bigg( t \frac{s_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \bigg) \bigg|.
    \end{align*}
    Note that 
    \begin{align*}
        \sup_{t\in \mathbb{R}} \bigg| \Phi(t) - \ \Phi\bigg( t \frac{s_{ijk}}{\sqrt{\mathrm{Var}(\xi_{ijk})}} \bigg) \bigg| &\leq \sup_{ \mathcal{A} \ \mathrm{ measurable}} \bigg| \mathbb{P}\bigg( Z \in \mathcal{A} \bigg) - \mathbb{P}\bigg( \frac{\sqrt{\mathrm{Var}(\xi_{ijk})}}{s_{ijk}} Z' \in \mathcal{A} \bigg) \bigg| \\
        &= D_{TV} \bigg( Z, \frac{\sqrt{\mathrm{Var}(\xi_{ijk})}}{s_{ijk}} Z' \bigg)
    \end{align*}
    where $Z$ and $Z'$ are independent standard Gaussians and $D_{TV}$ is the total variation distance.  By Theorem 1.3 of \cite{devroye_total_2022}, it holds that
    \begin{align*}
        D_{TV} \bigg( Z, \frac{\sqrt{\mathrm{Var}(\xi_{ijk})}}{s_{ijk}} Z' \bigg) &\leq \frac{2}{3} \bigg(1 - \frac{\mathrm{Var}(\xi_{ijk})}{s^2_{ijk}} \bigg) \\
        &= O( \mu_0^2 \frac{r}{p}),
    \end{align*}
    where we have used \eqref{eq:taylor1}.  Therefore,
    \begin{align*}
        \sup_{t\in \mathbb{R}}\bigg| \mathbb{P}\bigg\{ \frac{\xi_{ijk}}{s_{ijk}} \leq t \bigg\} - \Phi(t) \bigg| &\leq \frac{C_1}{\sqrt{p\log(p)}} + \frac{C_2 \mu_0^2 r}{p}.
    \end{align*}
This completes the proof.
