\label{lem:gammacloseness}
Instate the conditions of \cref{thm:civalidity2}, and define $\mathbf{\widehat \Gamma}^{(m)}_k$ as in \cref{al:ci_eigenvector}.  Then with probability at least $1 - O(p^{-6})$ it holds that
\begin{align*}

 \| \mathbf{\widehat W}_k&\big(\mathbf{\widehat \Gamma}^{(m)}_k \big)^{1/2}\mathbf{\widehat W}_k^{\top} -\big(\mathbf{\Gamma}^{(m)}_k \big)^{1/2} \| \\
 &\lesssim \frac{\sigma}{\lambda} \bigg( \frac{\sigma r \sqrt{p}\log(p) + \sigma \kappa^2 \sqrt{rp} \log^{3/2}(p)}{\lambda} + \frac{\kappa \mu_0 \sqrt{r} \log(p)}{p} + \frac{\mu_0 r^{3/2} \sqrt{\log(p)}}{p} \bigg),
 \end{align*}
 where $\mathbf{\widehat W}_k = \mathrm{sgn}({\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k)$.

We will model the argument in the proof of Theorem 4.11 of \cite{chen_spectral_2021}, where we will argue that $\widehat s^2_{ijk} - s_{ijk}^2$ is sufficiently small.  We first introduce an auxiliary term
\begin{align*}
    \widetilde s^2_{ijk} &\coloneqq \sum_{a} \big( \mathbf{Z}_1 \big)_{ia}^2 \big(\mathbf{V}_1 \mathbf{V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 +\sum_{b} \big( \mathbf{Z}_2 \big)^2_{jb} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{b,(k-1)p_1 + i}^2  \\
    &\quad + \sum_c \big( \mathbf{Z}_3 \big)^2_{kc} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{c,(i-1)p_2 + j}^2.
\end{align*}
We will compare both $\widehat s^2_{ijk}$ and $s_{ijk}^2$ to $\widetilde s^2_{ijk}$.
\begin{itemize}
    \item \textbf{Step 1: Showing $\widehat s^2_{ijk} \approx \widetilde s^2_{ijk}$:} 
Observe that
\begin{align*}
  | \widehat s^2_{ijk} - \widetilde s^2_{ijk} | &\leq \bigg|  \sum_{a} \big( \mathbf{Z}_1 \big)_{ia}^2 \big(\mathbf{V}_1 \mathbf{V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 -\big( \mathbf{\widehat Z}_1 \big)_{ia}^2 \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 \bigg| \\
  &\quad + \bigg| \sum_{b} \big( \mathbf{Z}_2 \big)^2_{jb} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{b,(k-1)p_1 + i}^2 -  \big( \mathbf{\widehat Z}_2 \big)^2_{jb} \big( \mathbf{\widehat V}_2 \mathbf{\widehat V}_2^{\top} \big)_{b,(k-1)p_1 + i}^2 \bigg|\\
  &\quad +\bigg|  \sum_c \big( \mathbf{Z}_3 \big)^2_{kc} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{c,(i-1)p_2 + j}^2 - \big( \mathbf{\widehat Z}_3 \big)^2_{kc} \big( \mathbf{\widehat V}_3 \mathbf{\widehat V}_3^{\top} \big)_{c,(i-1)p_2 + j}^2 \bigg|.
\end{align*}
We will focus on the first term, since the other terms will follow by symmetry.  Note that
\begin{align}
    \bigg| \sum_{a} & \big( \mathbf{Z}_1 \big)_{ia}^2 \big(\mathbf{V}_1 \mathbf{V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 -\big( \mathbf{\widehat Z}_1 \big)_{ia}^2 \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 \bigg| \nonumber\\
    &\leq \sum_{a} \big| (\mathbf{\widehat Z}_1)_{ia}^2 - (\mathbf{Z}_1)_{ia}^2 \big| \big( \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3 + k}^2 \\
    &\quad + \sum_a (\mathbf{Z}_1 )_{ia}^2 \bigg| \big(\mathbf{V}_1 \mathbf{V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} - \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} \bigg| \nonumber\\
    &\leq \max_{a} | (\mathbf{\widehat Z}_1)_{ia}^2 - (\mathbf{Z}_1)_{ia}^2 | \sum_a \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3 + k}^2 \nonumber\\
    &\quad + \max_a | (\mathbf{Z}_1 )_{ia}^2 | p^2 \max_{a} \bigg| \big(\mathbf{V}_1 \mathbf{V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} - \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} \bigg|\nonumber \\
    &\leq \bigg( \| \mathbf{\widehat Z}_1 \|_{\max} + \| \mathbf{Z}_1 \|_{\max} \bigg) \| \mathbf{\widehat Z}_1 - \mathbf{Z}_1 \|_{\max} \| \mathbf{\widehat V}_1 \|_{2,\infty}^2 \nonumber\\
    &\quad + p^2 \| \mathbf{Z}_1 \|_{\max}^2 \bigg( \| \mathbf{V}_1 \mathbf{V}_1^{\top} \|_{\max} + \| \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} \bigg) \| \mathbf{V}_1 \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max}. \label{v1v2closeness}
\end{align}
It is straightforward to  note that with probability at least $1 - O(p^{-9})$ that
\begin{align*}
    \| \mathbf{Z}_1 \|_{\max} &= \max_{a,b,c} | \mathcal{Z}_{abc} | \\
    &\lesssim \sigma \sqrt{\log(p)}.
\end{align*}
In addition, it holds that
\begin{align*}
    \| \mathbf{V}_1 \mathbf{V}_1^{\top} \|_{\max} &= \max_{i,j} | e_i^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} e_j | \\
    &\leq \| \mathbf{V}_1 \|_{2,\infty}^2 \\
    &\leq \mu_0^2 \frac{r}{p^2}.
\end{align*}
Similarly,
\begin{align*}
    \| \mathbf{\widehat V}_1 \mathbf{\widehat V}_1 \|_{\max} &\leq \| \mathbf{\widehat V}_1 \|_{2,\infty}^2 \\
    &\leq \bigg( \| \mathbf{\widehat V}_1 - \mathbf{V}_1 \mathbf{W}_{\mathbf{V}_1} \|_{2,\infty} + \mu_0 \frac{\sqrt{r}}{p} \bigg)^2.
\end{align*}
We  note that by \cref{lem:Vmatrixcloseness}, it holds that
\begin{align*}
  \| \mathbf{\widehat V}_1 - \mathbf{V}_1 \mathbf{W}_{\mathbf{V}_1} \|_{2,\infty} &\lesssim \frac{ \kappa^2 \mu_0 r \sqrt{p\log(p)}}{\lambda} \mu_0 \frac{\sqrt{r}}{p} \\
  &\leq \mu_0 \frac{\sqrt{r}}{p}
\end{align*}
provided that 
\begin{align}
    \lambda/\sigma \gtrsim \kappa^2 \mu_0 r \sqrt{p\log(p)}. \label{snrcondition}
\end{align}
Note that we require that
\begin{align*}
    \kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
In addition, \cref{thm:twoinfty} requires that $\lambda/\sigma \gtrsim \kappa p^{3/4} \sqrt{\log(p)}$.  Therefore, together these imply that
\begin{align*}
    \lambda/\sigma &\gtrsim \kappa p^{1/4} \sqrt{p\log(p)} \\
    &\gtrsim \kappa^3 r^{3/2} \mu_0^2 \log(p) \sqrt{p} \\
    &\gg \kappa^2 \mu_0 r \sqrt{p\log(p)},
\end{align*}
so that \cref{snrcondition} holds. Therefore,
\begin{align*}
    \| \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} &\lesssim \mu_0^2 \frac{r}{p^2}.
\end{align*}
Therefore, the bound in \eqref{v1v2closeness} reduces to
\begin{align}
     \bigg( \| \mathbf{\widehat Z}_1 \|_{\max} + \sigma \sqrt{\log(p)} \bigg) \| \mathbf{\widehat Z}_1 - \mathbf{Z}_1 \|_{\max} \mu_0^2 \frac{r}{p^2} + \sigma^2 \log(p) \mu_0^2 r  \| \mathbf{V}_1 \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max}.  \label{v1v2bd2}
\end{align}
We now note that
\begin{align*}
    \| \mathbf{\widehat Z}_1 - \mathbf{Z}_1 \|_{\max} &= \| \mathcal{\widehat Z} - \mathcal{Z} \|_{\max} \\
    &= \| \mathcal{T + Z - \widehat T - Z} \|_{\max} \\
    &= \| \mathcal{T - \widehat T} \|_{\max} \\

    &\lesssim  \frac{\mu_0\sigma \kappa  \sqrt{r\log(p)}  }{p} +  \frac{\sigma^2 \mu_0^4 \kappa^3 r^3 \log(p)}{\lambda \sqrt{p}}, 

\end{align*}
which holds with probability at least $1 - O(p^{-6})$, which holds by \cref{cor:maxnormbound}. As a byproduct, we also obtain that
\begin{align*}
    \| \mathbf{\widehat Z}_1 \|_{\max} &\leq \| \mathbf{\widehat Z}_1 - \mathbf{Z}_1 \|_{\max} + \sigma \sqrt{\log(p)} \\
    &\lesssim \sigma\sqrt{\log(p)}
\end{align*}
provided that
\begin{align*}
    \lambda/\sigma \gtrsim \mu_0^2 \kappa^3 r^2 \sqrt{\log(p)},
\end{align*}
which is guaranteed by the conditions in \cref{thm:twoinfty} as well as the assumption $\kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}$.  Finally, by \cref{lem:Vmatrixcloseness}, it holds that
