    \| \mathbf{V}_1 \mathbf{V}_1^{\top} -\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} &\leq \| \mathbf{V}_1 \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 (\mathbf{W}_{\mathbf{V}_1}^{\top}) \mathbf{V}_1^{\top} \|_{\max} + \| \mathbf{\widehat V}_1 (\mathbf{W}_{\mathbf{V}_1}^{\top}) \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} \\
    &\leq \| \mathbf{V}_1 \|_{2,\infty} \| \mathbf{V}_1 - \mathbf{\widehat V}_1 \mathbf{W}_{\mathbf{V}_1}^{\top} \|_{2,\infty} + \| \mathbf{\widehat V}_1 \|_{2,\infty} \| \mathbf{V}_1 \mathbf{W}_{\mathbf{V}_1} - \mathbf{\widehat V}_1 \|_{2,\infty} \\
    &\lesssim \mu_0 \frac{\sqrt{r}}{p} \frac{\kappa^2 \sigma \mu_0^2 r^{3/2} \sqrt{\log(p)}}{\lambda \sqrt{p}} \\
    &\lesssim \frac{ \sigma \mu_0^3 \kappa^2 r^2 \sqrt{\log(p)}}{\lambda p^{3/2}}.
\end{align*}
Therefore, plugging in these estimates to \eqref{v1v2bd2}, we see that with probability at least $1 - O(p^{-6})$,
\begin{align}
    | \widehat s^2_{ijk} - \widetilde s_{ijk}^2 | &\lesssim  \sigma \sqrt{\log(p)} \bigg( \frac{\mu_0 \sigma \kappa \sqrt{r\log(p)}}{p} + \frac{\sigma^2 \mu_0^4 \kappa^3 r^3 \log(p)}{\lambda \sqrt{p}} \bigg) \mu_0^2 \frac{r}{p^2} \nonumber \\
    &\quad + \sigma^2 \log(p) \mu_0^2 r \frac{\sigma \mu_0^3 \kappa^2 r^2 \sqrt{\log(p)}}{\lambda p^{3/2}} \nonumber \\
    &\lesssim \frac{\sigma^2 \kappa \mu_0^2 r^{3/2} \log(p)}{p^3} + \frac{\sigma^3 \mu_0^6 \kappa^3 r^4 \log^{3/2}(p)}{\lambda p^{5/2}} \nonumber \\
    &\quad + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}} \nonumber \\
    &\lesssim \frac{\sigma^2 \kappa \mu_0^3 r^{3/2} \log(p)}{p^3} + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}}.\label{vhatvtildebound}
\end{align}

\item 
\textbf{Step 2: Showing $\widetilde s^2_{ijk} \approx s^2_{ijk}$}: 
Note that the term $\widetilde s^2_{ijk}$ is a sum of independent subexponential random variables, so we will apply Bernstein's inequality to it.  In order to avoid additional cross-term covariance factors, we will apply it to each of the three separate terms. 

Define
\begin{align*}
    (s^{(i)})^2 &= \left\|e_{(j-1) p_{3}+k}^{\top} \mathbf{V}_{1} \mathbf{V}_{1}^{\top} \big(\Sigma^{(i)}_1\big)^{1/2}\right\|^{2}; \\
    (s^{(j)})^2  &\coloneqq \left\|e_{(k-1) p_{1}+i}^{\top} \mathbf{V}_{2} \mathbf{V}_{2}^{\top} \big(\Sigma^{(j)}_2\big)^{1/2}\right\|^{2}; \\
    (s^{(k)})^2 &\coloneqq \left\|e_{(i-1)p_{2}+j}^{\top} \mathbf{V}_{3} \mathbf{V}_{3}^{\top} \big(\Sigma^{(k)}_3\big)^{1/2}\right\|^{2},
\end{align*}
so that $s^2_{ijk} = (s^{(i)})^2 + (s^{(j)})^2 + (s^{(k)})^2.$ Define $(\widetilde s^{(i)})^2, (\widetilde s^{(j)})^2,$ and $(\widetilde s^{(k)})^2$ similarly.  Then
\begin{align*}
    \mathbb{P}\bigg\{ |\widetilde s^2_{ijk} - s^2_{ijk} | \geq t \bigg\} &\leq 3 \max_{c \in ijk} \mathbb{P}\bigg\{ | (s^{(c)})^2 - (\widetilde s^{(c)})^2| \geq t/3 \bigg\}.
\end{align*}
Without loss of generality, we focus on the first term; i.e., $s^{(i)}$.  Observe that
\begin{align*}
    \mathbb{E} (\widetilde s^{(i)})^2 = (s^{(i)})^2,
\end{align*}
so that the difference $(\widetilde s^{(i)})^2 - (s^{(i)})^2$ term is a sum of mean-zero random variables.  In order to apply Bernstein's inequality (Theorem 2.8.1 in \cite{vershynin_high-dimensional_2018}), we need to bound:
\begin{align*}
A_1 &\coloneqq \sum_{a} \| (( \mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} ) (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 \|_{\psi_1}^2; \\
A_2 &\coloneqq \max_{l}\| (( \mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} ) (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k} ^2\|_{\psi_1}.
\end{align*}
However,
\begin{align*}
    \sum_{a} \|& (( \mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} ) (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 \|_{\psi_1}^2   \\
     &= \sum_{a}(\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^4 \| (\mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} \|_{\psi_1}^2 \\
    &\leq \sigma^4 \max_{a}  (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 \sum_{a} (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 \\
    &\leq \sigma^4 \| \mathbf{V}_1 \|_{2,\infty}^2 \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 \| (\mathbf{V}_1 \mathbf{V}_1^{\top})_{\cdot,(j-1)p_3 + k } \|^2 \\
    &\leq C \sigma^4 \frac{ \mu_0^2 r}{p^2} \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^4,
    \end{align*}
and
\begin{align*}
    \max_{a}\|& (( \mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} ) (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 \|_{\psi_1}   \\
     &\leq \max_{a} | (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 | \|(\mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} \|_{\psi_1} \\
    &\leq \sigma^2 \| \mathbf{V}_1 \|_{2,\infty}^2 \| \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2  \\
    &\leq C\sigma^2 \mu_0^2 \frac{r}{p^2} \|  e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2.
\end{align*}
Therefore, by Bernstein's inequality, 
\begin{align*}
    \mathbb{P}\bigg\{ &| (\widetilde s^{(i)})^2 - (s^{(i)})^2 | \geq C t \bigg\} \\
    &\leq 2 \exp \bigg\{ -c \min\bigg( \frac{t^2}{\sigma^4 \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^4 \frac{\mu_0^2  r}{p^2} }, \frac{t }{ \sigma^2 \frac{\mu_0^2 r}{p^2} \|  e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2   } \bigg) \bigg\}.
\end{align*}
Taking
\begin{align*}
    t &= C\sigma^2 \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 \mu_0 \frac{\sqrt{r\log(p)}}{p},
\end{align*}
yields that
\begin{align*}
     \mathbb{P}\bigg\{ | (\widetilde s^{(i)})^2 - (s^{(i)})^2 | &\geq C\sigma^2 \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 \mu_0 \frac{\sqrt{r\log(p)}}{p} \bigg\} \\
     &\leq 2 \exp \bigg\{ -c \min\bigg( C^2\log(p) , C\frac{p\sqrt{\log(p)}}{\mu_0 \sqrt{r}} \bigg) \bigg\} \\
     &\leq Cp^{-20},
\end{align*}
since $\mu_0^2 r \lesssim \sqrt{p}$.  Consequently, by symmetry and the union bound, we obtain with this same probability that
\begin{align*}
    | \widetilde s_{ijk}^2 - s_{ijk}^2 | &\lesssim \sigma^2 \mu_0 \frac{\sqrt{r\log(p)}}{p} \bigg(  \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 + \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2 \bigg) \\
    &\ll s^2_{ijk},
\end{align*}
since $s^2_{ijk}$ satisfies the lower bound
\begin{align*}
    s^2_{ijk} \geq \sigma_{\min}^2 \bigg( \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 + \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2 \bigg),
\end{align*}
and $\sigma/\sigma_{\min} = O(1)$ by assumption.  
\item \textbf{Step 3: Combining These Bounds}: 
Combining steps 1 and 2, we see that with probability at least $1 - O(p^{-6})$ that
\begin{align*}
