under the assumption that
\begin{align*}
    s^2_{ijk} \gg \max\bigg\{  \frac{\sigma^{2} \kappa \mu_{0}^{3} r^{3 / 2} \log (p)}{p^{3}},\frac{\sigma^{3} \mu_{0}^{5} r^{3} \kappa^{2} \log ^{3 / 2}(p)}{\lambda p^{3 / 2}} \bigg\}. \addtocounter{equation}{1}\tag{\theequation} \label{3202023}
\end{align*}
The second term is guaranteed by the assumption in \cref{thm:civalidity}.  For the first term, recall that the assumption in \cref{thm:asymptoticnormalityentries} implies that
\begin{align*}
    s_{ijk}^2 &\gg \frac{\sigma^2 \kappa^4 \mu_0^6 r^4 \log(p)}{p^3},
\end{align*}
so that the assumption in \eqref{3202023} is met.  

 From this expansion, it holds that
\begin{align*}
    \widehat s_{ijk} &= s_{ijk}(1 + o(1))
\end{align*}
with probability at least $1 - O(p^{-6})$.  Therefore, by \cref{thm:asymptoticnormalityentries}, we have that 
\begin{align*}
    \bigg| \mathbb{P}\bigg\{ &\mathcal{T}_{ijk} \in \mathrm{C.I.}_{\alpha}( \mathcal{\widehat T}_{ijk} ) \bigg\} - (1 - \alpha) \bigg| \\
    &= \bigg| \mathbb{P}\bigg\{ | \mathcal{\widehat T}_{ijk} - \mathcal{T}_{ijk} | \leq z_{\alpha/2} \sqrt{\widehat s^2_{ijk}} \bigg\} - (1 - \alpha ) \bigg| \\
    &\leq \bigg| \mathbb{P}\bigg\{ |\mathcal{\widehat T}_{ijk} - \mathcal{T}_{ijk} | \leq z_{\alpha/2} s_{ijk} (1 + o(1)) \bigg\} - (1-\alpha) \bigg| + o(1) \\
    &\leq \bigg| \Phi\big( (1+o(1)\big) z_{\alpha/2} - \Phi\big(-(1+o(1))z_{\alpha/2} \big) - (1-\alpha) \bigg| + o(1) \\
    &\leq \bigg| \Phi(z_{\alpha/2}) - \Phi(-z_{\alpha/2}) - (1-\alpha) \bigg| + 2 \bigg| \Phi\big(  (1+ o(1))z_{\alpha/2} \big) - \Phi(z_{\alpha/2}) \bigg| + o(1) \\
    &\leq o(1),
\end{align*}
which follows by the Lipschitz continuity of $\Phi$.  This completes the proof.
\end{itemize}

\begin{align*}
  | \widehat s^2_{ijk} - \widetilde s^2_{ijk} | &\leq \bigg|  \sum_{a} \big( \mathbf{Z}_1 \big)_{ia}^2 \big(\mathbf{V}_1 \mathbf{V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 -\big( \mathbf{\widehat Z}_1 \big)_{ia}^2 \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 \bigg| \\
  &\quad + \bigg| \sum_{b} \big( \mathbf{Z}_2 \big)^2_{jb} \big( \mathbf{V}_2 \mathbf{V}_2^{\top} \big)_{b,(k-1)p_1 + i}^2 -  \big( \mathbf{\widehat Z}_2 \big)^2_{jb} \big( \mathbf{\widehat V}_2 \mathbf{\widehat V}_2^{\top} \big)_{b,(k-1)p_1 + i}^2 \bigg|\\
  &\quad +\bigg|  \sum_c \big( \mathbf{Z}_3 \big)^2_{kc} \big( \mathbf{V}_3 \mathbf{V}_3^{\top} \big)_{c,(i-1)p_2 + j}^2 - \big( \mathbf{\widehat Z}_3 \big)^2_{kc} \big( \mathbf{\widehat V}_3 \mathbf{\widehat V}_3^{\top} \big)_{c,(i-1)p_2 + j}^2 \bigg|.
\end{align*}

\begin{align}
    \bigg| \sum_{a} & \big( \mathbf{Z}_1 \big)_{ia}^2 \big(\mathbf{V}_1 \mathbf{V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 -\big( \mathbf{\widehat Z}_1 \big)_{ia}^2 \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3+k}^2 \bigg| \nonumber\\
    &\leq \sum_{a} \big| (\mathbf{\widehat Z}_1)_{ia}^2 - (\mathbf{Z}_1)_{ia}^2 \big| \big( \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3 + k}^2 \\
    &\quad + \sum_a (\mathbf{Z}_1 )_{ia}^2 \bigg| \big(\mathbf{V}_1 \mathbf{V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} - \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} \bigg| \nonumber\\
    &\leq \max_{a} | (\mathbf{\widehat Z}_1)_{ia}^2 - (\mathbf{Z}_1)_{ia}^2 | \sum_a \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \big)_{a,(j-1)p_3 + k}^2 \nonumber\\
    &\quad + \max_a | (\mathbf{Z}_1 )_{ia}^2 | p^2 \max_{a} \bigg| \big(\mathbf{V}_1 \mathbf{V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} - \big(\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top}\big)^2_{a,(j-1)p_3 + k} \bigg|\nonumber \\
    &\leq \bigg( \| \mathbf{\widehat Z}_1 \|_{\max} + \| \mathbf{Z}_1 \|_{\max} \bigg) \| \mathbf{\widehat Z}_1 - \mathbf{Z}_1 \|_{\max} \| \mathbf{\widehat V}_1 \|_{2,\infty}^2 \nonumber\\
    &\quad + p^2 \| \mathbf{Z}_1 \|_{\max}^2 \bigg( \| \mathbf{V}_1 \mathbf{V}_1^{\top} \|_{\max} + \| \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} \bigg) \| \mathbf{V}_1 \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max}. \label{v1v2closeness}
\end{align}

\begin{align*}
    \| \mathbf{\widehat Z}_1 - \mathbf{Z}_1 \|_{\max} &= \| \mathcal{\widehat Z} - \mathcal{Z} \|_{\max} \\
    &= \| \mathcal{T + Z - \widehat T - Z} \|_{\max} \\
    &= \| \mathcal{T - \widehat T} \|_{\max} \\

    &\lesssim  \frac{\mu_0\sigma \kappa  \sqrt{r\log(p)}  }{p} +  \frac{\sigma^2 \mu_0^4 \kappa^3 r^3 \log(p)}{\lambda \sqrt{p}}, 

\end{align*}

\begin{align*}
    \| \mathbf{V}_1 \mathbf{V}_1^{\top} -\mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} &\leq \| \mathbf{V}_1 \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 (\mathbf{W}_{\mathbf{V}_1}^{\top}) \mathbf{V}_1^{\top} \|_{\max} + \| \mathbf{\widehat V}_1 (\mathbf{W}_{\mathbf{V}_1}^{\top}) \mathbf{V}_1^{\top} - \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \|_{\max} \\
    &\leq \| \mathbf{V}_1 \|_{2,\infty} \| \mathbf{V}_1 - \mathbf{\widehat V}_1 \mathbf{W}_{\mathbf{V}_1}^{\top} \|_{2,\infty} + \| \mathbf{\widehat V}_1 \|_{2,\infty} \| \mathbf{V}_1 \mathbf{W}_{\mathbf{V}_1} - \mathbf{\widehat V}_1 \|_{2,\infty} \\
    &\lesssim \mu_0 \frac{\sqrt{r}}{p} \frac{\kappa^2 \sigma \mu_0^2 r^{3/2} \sqrt{\log(p)}}{\lambda \sqrt{p}} \\
    &\lesssim \frac{ \sigma \mu_0^3 \kappa^2 r^2 \sqrt{\log(p)}}{\lambda p^{3/2}}.
\end{align*}

\begin{align}
    | \widehat s^2_{ijk} - \widetilde s_{ijk}^2 | &\lesssim  \sigma \sqrt{\log(p)} \bigg( \frac{\mu_0 \sigma \kappa \sqrt{r\log(p)}}{p} + \frac{\sigma^2 \mu_0^4 \kappa^3 r^3 \log(p)}{\lambda \sqrt{p}} \bigg) \mu_0^2 \frac{r}{p^2} \nonumber \\
    &\quad + \sigma^2 \log(p) \mu_0^2 r \frac{\sigma \mu_0^3 \kappa^2 r^2 \sqrt{\log(p)}}{\lambda p^{3/2}} \nonumber \\
    &\lesssim \frac{\sigma^2 \kappa \mu_0^2 r^{3/2} \log(p)}{p^3} + \frac{\sigma^3 \mu_0^6 \kappa^3 r^4 \log^{3/2}(p)}{\lambda p^{5/2}} \nonumber \\
    &\quad + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}} \nonumber \\
    &\lesssim \frac{\sigma^2 \kappa \mu_0^3 r^{3/2} \log(p)}{p^3} + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}}.\label{vhatvtildebound}
\end{align}

\begin{align*}
    \mathbb{P}\bigg\{ |\widetilde s^2_{ijk} - s^2_{ijk} | \geq t \bigg\} &\leq 3 \max_{c \in ijk} \mathbb{P}\bigg\{ | (s^{(c)})^2 - (\widetilde s^{(c)})^2| \geq t/3 \bigg\}.
\end{align*}

\begin{align*}
    \max_{a}\|& (( \mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} ) (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 \|_{\psi_1}   \\
     &\leq \max_{a} | (\mathbf{V}_1 \mathbf{V}_1^{\top})_{a,(j-1)p_3 + k}^2 | \|(\mathbf{Z}_1)_{ia}^2 - \sigma^2_{ia} \|_{\psi_1} \\
    &\leq \sigma^2 \| \mathbf{V}_1 \|_{2,\infty}^2 \| \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2  \\
    &\leq C\sigma^2 \mu_0^2 \frac{r}{p^2} \|  e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2.
\end{align*}

\begin{align*}
    \mathbb{P}\bigg\{ &| (\widetilde s^{(i)})^2 - (s^{(i)})^2 | \geq C t \bigg\} \\
    &\leq 2 \exp \bigg\{ -c \min\bigg( \frac{t^2}{\sigma^4 \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^4 \frac{\mu_0^2  r}{p^2} }, \frac{t }{ \sigma^2 \frac{\mu_0^2 r}{p^2} \|  e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2   } \bigg) \bigg\}.
\end{align*}

\begin{align*}
     \mathbb{P}\bigg\{ | (\widetilde s^{(i)})^2 - (s^{(i)})^2 | &\geq C\sigma^2 \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 \mu_0 \frac{\sqrt{r\log(p)}}{p} \bigg\} \\
     &\leq 2 \exp \bigg\{ -c \min\bigg( C^2\log(p) , C\frac{p\sqrt{\log(p)}}{\mu_0 \sqrt{r}} \bigg) \bigg\} \\
     &\leq Cp^{-20},
\end{align*}

\begin{align*}
    | \widetilde s_{ijk}^2 - s_{ijk}^2 | &\lesssim \sigma^2 \mu_0 \frac{\sqrt{r\log(p)}}{p} \bigg(  \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 + \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2 \bigg) \\
    &\ll s^2_{ijk},
\end{align*}

\begin{align*}
    s^2_{ijk} \geq \sigma_{\min}^2 \bigg( \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 + \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2 \bigg),
\end{align*}

\begin{align*}
    |s^2_{ijk} - \widehat s^2_{ijk} | &\lesssim \sigma^2 \mu_0 \frac{\sqrt{r\log(p)}}{p} \bigg( \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 + \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2 \bigg) \\
    &\quad + \frac{\sigma^2 \kappa \mu_0^3 r^{3/2} \log(p)}{p^3} + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}},
\end{align*}

Without loss of generality, we consider $k = 1$, and recall we assume $t$ is such that $t = t_0 +1$, where $t_0$ is such that \cref{thm:twoinfty} holds.  We note that $\mathbf{\widehat V}_1$ is the right orthonormal matrix in the truncated SVD of the matrix
\begin{align*}
    \bigg(\mathbf{T}_1 + \mathbf{Z}_1 \bigg) \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg).
\end{align*}
Note that
\begin{align*}
    \mathbf{E}^{\top} &\coloneqq \mathbf{T}_1 - \bigg( \mathbf{T}_1  + \mathbf{Z}_1 \bigg) \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg) \\
    &= \mathbf{T}_1 - \mathbf{T}_1 \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg) \\
    &\quad - \mathbf{Z}_1 \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg) \\
    &= \mathbf{T}_1 \bigg( \mathcal{P}_{{\mathbf{U}}_2} \otimes \mathcal{P}_{{\mathbf{U}}_3}  - \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg) \bigg) \\
    &\quad - \mathbf{Z}_1 \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg).
\end{align*}
Taking norms, it holds that
\begin{align}
    \| \mathbf{E} \| &\leq \| \mathbf{T}_1 \| \bigg\| \mathcal{P}_{{\mathbf{U}}_2} \otimes \mathcal{P}_{{\mathbf{U}}_3}  - \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg) \bigg\| \nonumber \\
    &\quad + \|  \mathbf{Z}_1 \bigg( \mathbf{\widehat{U}}_2^{(t-1)} \big( \mathbf{\widehat{U}}_2^{(t-1)} \big)^{\top} \otimes  \mathbf{\widehat{U}}_3^{(t-1)} \big( \mathbf{\widehat{U}}_3^{(t-1)} \big)^{\top} \bigg) \| \nonumber \\
    &\leq 2 \lambda_1 \max \bigg\{ \| \sin\Theta( \mathbf{\widehat{U}}_2^{(t-1)}, {\mathbf{U}}_2 ) \|, \| \sin\Theta(\mathbf{\widehat{U}}_3^{(t-1)},{\mathbf{U}}_3 ) \| \bigg\} \nonumber \\
    &\quad + C \sigma \sqrt{pr} \nonumber \\
    &\lesssim  \kappa^2  \sigma \sqrt{p\log(p)} + \sigma \sqrt{pr} \label{Ebound}  \\
    &\ll \lambda, \nonumber
\end{align}
which holds with probability at least $1 - O(p^{-9})$ \textcolor{black}{by \eqref{sinthetaegood}}.  Here we have used the fact that $t_0 + 1 \leq t \leq t_{\max}$, as well as the bounds on the term $\|\mathbf{Z}_1 \big( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)} (\mathbf{\widehat{U}}_3^{(t-1)})^{\top} \| \leq C \sigma \sqrt{pr}$, which holds on the event $\mathcal{E}_{\mathrm{Good}}$ (defined in \cref{sec:notation2}).  Therefore, by the Davis-Kahan Theorem, it holds that
\begin{align*}
    \| \sin\Theta\big( \mathbf{\widehat V}_1 ,\mathbf{V}_1 \big) \| &\lesssim \frac{\kappa^2 \sigma \sqrt{p\log(p)} + \sigma \sqrt{pr}}{\lambda},
\end{align*}
with probability at least $1 - O(p^{-9})$. The same argument goes through for the other modes as well. 

We now consider the $\ell_{2,\infty}$ error for $\mathbf{\widehat V}_1$.  We will apply Theorem 3.7 of \cite{cape_two--infinity_2019}, (with $\mathbf{X}$ therein defined as $\mathbf{T}_1^{\top}$ and ${\mathbf{U}}$ and $\mathbf{V}$ switched from their notation) to see that 
\begin{align}
    \| \mathbf{\widehat V}_1 - \mathbf{V}_1 \mathbf{W}_{\mathbf{V}_1} \|_{2,\infty} &\leq 2 \bigg( \frac{ \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty}}{\lambda} \bigg)  \nonumber\\
    &\quad + 2 \bigg( \frac{ \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} ( \mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top}) \|_{2,\infty}}{\lambda} \bigg) \| \sin\Theta(\mathbf{\widehat{U}}_1^{(t)}, {\mathbf{U}}_1 ) \|  \nonumber\\
    &\quad + 2 \bigg( \frac{  \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{T}_1^{\top} ( \mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top}) \|_{2,\infty}}{\lambda} \bigg) \| \sin\Theta( \mathbf{\widehat{U}}_1^{(t)}, {\mathbf{U}}_1 ) \| \nonumber\\
    &\quad + \| \sin\Theta( \mathbf{\widehat V}_1, \mathbf{V}_1 ) \|^2 \| \mathbf{V}_1 \|_{2,\infty} \nonumber\\
    &\leq 2 \bigg( \frac{ \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty}}{\lambda} \bigg)  \nonumber\\
    &\quad + 2 \bigg( \frac{ \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} ( \mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top}) \|_{2,\infty}}{\lambda} \bigg) \| \sin\Theta(\mathbf{\widehat{U}}_1^{(t)}, {\mathbf{U}}_1 ) \|  \nonumber\\
    &\quad + \| \sin\Theta( \mathbf{\widehat V}_1, \mathbf{V}_1 ) \|^2 \| \mathbf{V}_1 \|_{2,\infty}, \\
    &\coloneqq (I) + (II) + (III),
    \label{eq:v1twoinfty}
\end{align}
where we have used the fact that $(\mathbf{I}- \mathbf{V}_1 \mathbf{V}_1^{\top}) \mathbf{T}_1^{\top} = 0$.  Therefore, it suffices to bound each of the other three terms above.  
\begin{itemize}
    \item 
\textbf{The term $(I)$}: We note that numerator satisfies
\begin{align*}
    &\| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
    &= \|  ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \bigg[ \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)} (\mathbf{\widehat{U}}_3^{(t-1)})^{\top} \big(  \mathbf{T}_1^{\top} + \mathbf{Z}_1^{\top} \big) - \mathbf{T}_1^{\top} \bigg] {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
    &\leq \|  ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} )  \bigg( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top} - {\mathbf{U}}_2 {\mathbf{U}}_2\otimes {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \bigg) \mathbf{T}_1^{\top}  {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
    &\quad + \|  ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} )\bigg(\mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}\bigg) \mathbf{Z}_1^{\top}  {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
    &\leq \|    \bigg( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}- {\mathbf{U}}_2 {\mathbf{U}}_2\otimes {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \bigg) \mathbf{T}_1^{\top}   \|_{2,\infty} \\
    &\quad +\|  \mathbf{V}_1 \mathbf{V}_1^{\top} \bigg( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top} - {\mathbf{U}}_2 {\mathbf{U}}_2\otimes {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \bigg) \mathbf{T}_1^{\top}  \|_{2,\infty} \\
    &\quad + \|   \bigg(\mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}\bigg) \mathbf{Z}_1^{\top}  {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
     &\quad + \|   \mathbf{V}_1 \mathbf{V}_1^{\top} \bigg( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}\bigg) \mathbf{Z}_1^{\top} {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
     &\leq \|  \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}- {\mathbf{U}}_2 {\mathbf{U}}_2\otimes {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \|_{2,\infty} \lambda_1 \\
     &\quad + \| \mathbf{V}_1 \|_{2,\infty} \| \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}- {\mathbf{U}}_2 {\mathbf{U}}_2\otimes {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \| \lambda_1 \\
     &\quad + \| \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}\|_{2,\infty} \| \bigg( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top} \bigg) \mathbf{Z}_1^{\top} \| \\
     &\quad + \| \mathbf{V}_1 \|_{2,\infty} \| \bigg( \mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top} \bigg) \mathbf{Z}_1^{\top} \|,
\end{align*}
where the final inequality is due to the fact that $\mathbf{\widehat{U}}_2^{(t-1)} (\mathbf{\widehat{U}}_2^{(t-1)})^{\top} \otimes \mathbf{\widehat{U}}_3^{(t-1)}( \mathbf{\widehat{U}}_3^{(t-1)})^{\top}$ is an orthogonal projection matrix  and hence equals its square. 
From the proof of \cref{lem:zentrywiselemma}, under the condition $\kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}$, \cref{cor:asymptoticnormality_projection} implies that with probability at least $1 - O(p^{-9})$,
\begin{align*}
    \max_k \| \mathbf{\widehat{U}}_k \mathbf{\widehat{U}}_k^{\top} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} \|_{2,\infty} \lesssim \frac{\sigma \mu_0 \sqrt{r\log(p)}}{\lambda}.
\end{align*}
Therefore,
\begin{align*}
    \| \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2^{\top} \otimes \mathbf{\widehat{U}}_3\mathbf{\widehat{U}}_3^{\top} - {\mathbf{U}}_2 {\mathbf{U}}_2^{\top} \otimes {\mathbf{U}}_3{\mathbf{U}}_3^{\top} \|_{2,\infty} &\leq \| \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2^{\top} \otimes \big( \mathbf{\widehat{U}}_3 \mathbf{\widehat{U}}_3^{\top} - {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \big) \|_{2,\infty} \\
    &\quad + \| \big( \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2 - {\mathbf{U}}_2 {\mathbf{U}}_2^{\top} \big) \otimes {\mathbf{U}}_3 {\mathbf{U}}_3^{\top} \|_{2,\infty} \\
    &\lesssim \mu_0 \sqrt{\frac{r}{p}} \frac{\sigma \mu_0 \sqrt{r\log(p)}}{\lambda} \\
    &\lesssim \frac{ \sigma \mu_0^2 r \sqrt{\log(p)}}{\lambda \sqrt{p}}.
\end{align*}
In addition, with this same probability, \textcolor{black}{by \eqref{sinthetaegood}} it holds that
\begin{align*}
    \max_k \| \mathbf{\widehat{U}}_k \mathbf{\widehat{U}}_k^{\top} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} \| &\lesssim \max_k \|\sin\Theta(\mathbf{\widehat{U}}_k,{\mathbf{U}}_k) \| \lesssim \frac{\kappa \sqrt{p\log(p)}}{\lambda/\sigma}.
\end{align*}
Plugging in all these bounds yields
\begin{align*}
      \| ( \mathbf{I} - &\mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} \\
      &\lesssim \lambda_1 \frac{ \sigma \mu_0^2 r \sqrt{\log(p)}}{\lambda \sqrt{p}} + \lambda_1 \mu_0 \frac{\sqrt{r}}{p} \frac{\kappa \sigma \sqrt{p\log(p)}}{\lambda} \\
      &\quad + \bigg(\| \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2^{\top} \otimes \mathbf{\widehat{U}}_3 \mathbf{\widehat{U}}_3^{\top} \|_{2,\infty} + \| \mathbf{V}_1 \|_{2,\infty} \bigg) \| \bigg( \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2^{\top} \otimes \mathbf{\widehat{U}}_3 \mathbf{\widehat{U}}_3^{\top} \bigg) \mathbf{Z}_1^{\top} \| \\
      &\lesssim \lambda_1 \frac{ \sigma \mu_0^2 r \sqrt{\log(p)}}{\lambda \sqrt{p}} + \lambda_1 \mu_0 \frac{\sqrt{r}}{p} \frac{\kappa \sigma \sqrt{p\log(p)}}{\lambda} \\
      &\quad + \mu_0^2 \frac{r}{p} \| \bigg( \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2^{\top} \otimes \mathbf{\widehat{U}}_3 \mathbf{\widehat{U}}_3^{\top} \bigg) \mathbf{Z}_1^{\top} \|.
\end{align*}
On the event $\mathcal{E}_{\mathrm{Good}}$, it holds that
\begin{align*}
     \| \mathbf{Z}_1 \bigg( \mathbf{\widehat{U}}_2 \mathbf{\widehat{U}}_2^{\top} \otimes \mathbf{\widehat{U}}_3 \mathbf{\widehat{U}}_3^{\top} \bigg) \| &\lesssim \sigma\sqrt{pr};
     \end{align*}
Therefore, with probability at least $1 - O(p^{-9})$,
\begin{align}
    &\frac{ \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \|_{2,\infty} }{\lambda} \nonumber \\
    &\lesssim  \frac{1}{\lambda} \bigg\{ \lambda_1 \frac{ \sigma \mu_0^2 r \sqrt{\log(p)}}{\lambda \sqrt{p}} + \lambda_1 \mu_0 \frac{\sqrt{r}}{p} \frac{\kappa \sigma \sqrt{p\log(p)}}{\lambda}  + \mu_0^2 \frac{r}{p} \sigma \sqrt{pr} \bigg\}\nonumber \\
     &\lesssim \frac{\kappa \sigma \mu_0^2 r \sqrt{\log(p)}  + \kappa^2 \sigma \mu_0 \sqrt{r\log(p)} + \sigma \mu_0^2 r^{3/2}}{\lambda\sqrt{p}  } \nonumber \\
     &\lesssim \frac{\kappa^2 \sigma \mu_0^2 r^{3/2} \sqrt{\log(p)}}{\lambda \sqrt{p}}\label{v1bd1}
     \end{align}
\item  \textbf{The Term $(II)$:} We note that the numerator of the second term in \eqref{eq:v1twoinfty} is of the form
\begin{align*}
    \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E}( \mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top}) \|_{2,\infty} &\leq   \| ( \mathbf{I} - \mathbf{V}_1 \mathbf{V}_1^{\top} ) \mathbf{E} \|.
\end{align*}
By repeating the argument above, this term satisfies the same upper bound as $(I)$ as the  $\sin\Theta$ distance is upper bounded by one. 
\item \textbf{The Term $(III)$:} The only remaining term is the term
\begin{align*}
    \| \sin\Theta( \mathbf{\widehat V}_1 , \mathbf{V}_1 ) \|^2 \|\mathbf{V}_1 \|_{2,\infty} &\lesssim \mu_0 \frac{\sqrt{r}}{p} \frac{ \| \mathbf{E} \|^2}{\lambda^2}
\end{align*}
by the Davis-Kahan Theorem.  We have already showed in \eqref{Ebound} that
\begin{align*}
    \| \mathbf{E} \| &\lesssim \sigma \sqrt{pr} +  \kappa^2 \sigma \sqrt{p\log(p)}.
\end{align*}
Therefore,
\begin{align*}
   \mu_0 \frac{\sqrt{r}}{p} \frac{ \| \mathbf{E} \|^2}{\lambda^2} &\lesssim \mu_0 \frac{\sqrt{r}}{p}  \frac{ \big( \sigma \sqrt{pr} +  \kappa^2 \sigma \sqrt{p\log(p)} \big)^2}{\lambda^2} \\
    &\lesssim \mu_0 \frac{\sqrt{r}}{p}  \frac{\sigma^2 pr + \kappa^4 \sigma^2 p\log(p) + \sigma^2 \kappa^2 p \sqrt{r\log(p)}}{\lambda^2} \\
    &\lesssim \frac{\mu_0 \sigma^2 \sqrt{r} \big( r + \kappa^4 \log(p) + \kappa^2 \sqrt{r\log(p)}\big)}{\lambda^2} \\
    &\lesssim \frac{\mu_0 \sigma^2 r^{3/2} \kappa^4 \log(p)}{\lambda^2}.
\end{align*}
This bound is smaller than the bound in \eqref{v1bd1} as long as
\begin{align*}
    \lambda/\sigma \gtrsim \frac{\kappa^2}{\mu_0} \sqrt{p\log(p)}.
\end{align*}
Recall that we assume that $\lambda/\sigma \gtrsim \kappa p^{3/4} \sqrt{\log(p)}$ and that $\kappa \lesssim p^{1/4}$.  Therefore, \eqref{v1bd1} dominates this upper bound.
\end{itemize}
Putting these bounds together, with probability at least $1 - O(p^{-9})$ it holds that
\begin{align*}
    \| \mathbf{\widehat V}_1 - \mathbf{V}_1 \mathbf{W}_{\mathbf{V}_1} \|_{2,\infty} &\lesssim \frac{\kappa^2 \sigma \mu_0^2 r^{3/2} \sqrt{\log(p)}}{\lambda \sqrt{p}},
\end{align*}
which proves the second assertion.

Next, we show that
\begin{align*}
     \| \mathbf{W}_{\mathbf{V}_k}^{\top} \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \| &\lesssim \frac{1}{\lambda} \bigg( \frac{\sigma \sqrt{pr} + \kappa^2 \sigma \sqrt{p\log(p)}}{\lambda} \bigg)
\end{align*}
with probability at least $1 - O(p^{-9})$.  
Since $\mathbf{\widehat{\Lambda}}_k$ are the leading $r_k$ singular values of the matrix 
\begin{align*}
  \big( \mathbf{T}_k + \mathbf{Z}_k \big) \big( \mathbf{\widehat{U}}_{k+1}\mathbf{\widehat{U}}_{k+1}^{\top} \otimes \mathbf{\widehat{U}}_{k+2} \mathbf{\widehat{U}}_{k+2}^{\top} \big),
\end{align*}
then it holds that
\begin{align*}
(\mathbf{\widehat{\Lambda}}_k)_{r_k} &\geq (\mathbf{\Lambda}_k)_{r_k}  - 2 \| \mathbf{E}_k \| \\
&\gtrsim (\mathbf{\Lambda}_k)_{r_k},
\end{align*}
where $\mathbf{E}_k$ is as in the previous part of the lemma (where above we suppressed the dependence of $\mathbf{E}_k$ on $k$). Hence $\| \mathbf{\widehat{\Lambda}}_k^{-1} \| \lesssim \lambda^{-1}$, which will be useful in the sequel. 

Observe that
\begin{align*}
    \| \mathbf{W}_{\mathbf{V}_k}^{\top} \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \| &\leq \| \mathbf{\Lambda}_k^{-1} ( \mathbf{\widehat W}_k - {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k ) \| + \| \mathbf{\Lambda}_k^{-1} {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k - \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \| \\
    &\quad + \|\big( \mathbf{W}_{\mathbf{V}_k}- \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \big)\mathbf{\widehat{\Lambda}}_k^{-1} \| \\
    &\lesssim \frac{\| \mathbf{\widehat W}_k - {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k \| + \|\mathbf{W}_{\mathbf{V}_k}- \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \| }{\lambda} \\
    &\quad + \| \mathbf{\Lambda}_k^{-1}\big( {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k \mathbf{\widehat{\Lambda}}_k - \mathbf{\Lambda}_k \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \big) \mathbf{\widehat{\Lambda}}_k^{-1} \| \\
    &\lesssim \frac{\| \mathbf{\widehat W}_k - {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k \| + \|\mathbf{W}_{\mathbf{V}_k}- \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \| }{\lambda} \\
    &\quad + \frac{ \| {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k \mathbf{\widehat{\Lambda}}_k - \mathbf{\Lambda}_k \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \|}{\lambda^2}.
\end{align*}
Note that since $\mathbf{\widehat W}_k = \mathrm{sgn}({\mathbf{U}}_k,\mathbf{\widehat{U}}_k)$, it holds on the event $\mathcal{E}_{\mathrm{Good}}$ \textcolor{black}{by \cref{sinthetaegood} and the same argument as \eqref{sintheta14}} that
\begin{align*}
    \| \mathbf{\widehat W}_k - {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k \| &\lesssim \| \sin\Theta(\mathbf{\widehat{U}}_k,{\mathbf{U}}_k) \|^2 \\
    &\lesssim \bigg( \frac{\kappa \sigma \sqrt{p\log(p)}}{\lambda} \bigg)^2;
\end{align*}
and similarly that
\begin{align*}
    \| \mathbf{W}_{\mathbf{V}_k} - \mathbf{V}_k^{\top}\mathbf{\widehat V}_k \| &\leq \| \sin\Theta(\mathbf{V}_k ,\mathbf{\widehat V}_k ) \|^2 \\
    &\lesssim \bigg( \frac{\kappa^2 \sigma \sqrt{p\log(p)} + \sigma \sqrt{pr}}{\lambda} \bigg)^2,
\end{align*}
which holds with probability at least $1 - O(p^{-9})$ by the previous part of this proof.  For the remaining term, we note that by the eigenvector eigenvalue equation, it holds that $\mathbf{\widehat{U}}_k \mathbf{\widehat{\Lambda}}_k = (\mathbf{T}_k + \mathbf{E}_k) \mathbf{\widehat V}_k$, and hence that
\begin{align*}
    \| {\mathbf{U}}_k^{\top} \mathbf{\widehat{U}}_k \mathbf{\widehat{\Lambda}}_k - \mathbf{\Lambda}_k \mathbf{V}_k^{\top} \mathbf{\widehat V}_k \| &= \| {\mathbf{U}}_k^{\top} \big( \mathbf{T}_k + \mathbf{E}_k \big) \mathbf{\widehat V}_k - {\mathbf{U}}_k^{\top} \mathbf{T}_k \mathbf{\widehat V}_k \| \\
    &= \| {\mathbf{U}}_k^{\top} \mathbf{E}_k \mathbf{\widehat V}_k \| \\
    &\leq \| \mathbf{E}_k \| \\
    &\lesssim \sigma \sqrt{pr} + \kappa^2 \sigma \sqrt{p\log(p)},
\end{align*}
where the final inequality holds with probability at least $1 - O(p^{-9})$ by \eqref{Ebound}.  Putting these all together shows that
\begin{align*}
    \| \mathbf{W}_{\mathbf{V}_k}^{\top} \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \| &\lesssim \frac{1}{\lambda} \bigg( \frac{\kappa^2 \sigma \sqrt{p\log(p)} + \sigma \sqrt{pr}}{\lambda} \bigg)^2 + \frac{\sigma \sqrt{pr} + \kappa^2 \sigma \sqrt{p\log(p)}}{\lambda^2} \\
    &\lesssim \frac{1}{\lambda} \bigg( \frac{\sigma \sqrt{pr} + \kappa^2 \sigma \sqrt{p\log(p)}}{\lambda} \bigg),
\end{align*}
which completes the proof.

First we will show that
\begin{align*}
        \| \mathbf{\widehat W}_k &\mathbf{\widehat \Gamma}^{(m)}_k \mathbf{\widehat W}_k^{\top} - \mathbf{\Gamma}^{(m)}_k \|\\
        &\lesssim \frac{\sigma^2}{\lambda^2} \bigg( \frac{\sigma r \sqrt{p}\log(p) + \sigma \kappa^2 \sqrt{rp} \log^{3/2}(p)}{\lambda} + \frac{\kappa \mu_0 \sqrt{r} \log(p)}{p} + \frac{\mu_0 r^{3/2} \sqrt{\log(p)}}{p} \bigg)
\end{align*}
with probability at least $1 - O(p^{-6})$. Define $\widetilde \Sigma^{(m)}_k$ as the diagonal matrix whose diagonal entries are the squared entries of $e_m^{\top} \mathbf{Z}_k$.  We will proceed in steps. First, we note that
\begin{align*}
   \bigg\|  \mathbf{\widehat W}_k\mathbf{\widehat \Gamma}^{(m)}_k  \mathbf{\widehat W}_k^{\top} - \mathbf{\Gamma}^{(m)}_k  \bigg\| &= \bigg\|   \mathbf{\widehat W}_k\mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat V}_k^{\top} \widehat \Sigma^{(m)}_k \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} - \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \Sigma^{(m)}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \bigg\| \\
   &\leq\bigg\|   \mathbf{\widehat W}_k\mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat V}_k^{\top} \widehat \Sigma^{(m)}_k \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} - \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top}  \widetilde \Sigma^{(m)}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \bigg\| \\
   &\quad + \bigg\|   \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top}\bigg( \widetilde \Sigma^{(m)}_k - \Sigma^{(m)}_k \bigg)\mathbf{V}_k \mathbf{\Lambda}_k^{-1} \bigg\| \\
   &\leq \bigg\| \bigg( \mathbf{\widehat W}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat V}_k^{\top} - \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \bigg) \widehat \Sigma^{(m)}_k \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \bigg\| \\
   &\quad + \bigg\| \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \bigg( \widetilde \Sigma^{(m)}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} - \widehat \Sigma^{(m)}_k \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \bigg) \bigg\| \\
   &\quad + \bigg\|   \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top}\bigg( \widetilde \Sigma^{(m)}_k - \Sigma^{(m)}_k \bigg)\mathbf{V}_k \mathbf{\Lambda}_k^{-1} \bigg\| \\
   &\coloneqq \alpha_1 + \alpha_2 + \alpha_3.
\end{align*}
In the subsequent steps, we bound $\alpha_1$, $\alpha_2$, and $\alpha_3$, but first we obtain several preliminary bounds.
\begin{itemize}
    \item \textbf{Step 1: Initial Bounds:} First, it holds that
\begin{align*}
\| \widehat \Sigma^{(m)}_k - \widetilde \Sigma^{(m)}_k \| &= \max_{l} |  \big(\mathbf{\widehat Z}_k\big)_{ml}^2 - \big(\mathbf{ Z}_k\big)_{ml}^2  | \\
    &\leq \bigg( \| \mathcal{\widehat Z} \|_{\max} + \| \mathcal{Z} \|_{\max} \bigg) \| \mathcal{\widehat Z} - \mathcal{Z} \|_{\max}.
\end{align*}
By \cref{cor:maxnormbound}, with probability at least $1 - O(p^{-6})$ it holds that
\begin{align*}
    \| \mathcal{\widehat Z - Z} \|_{\max} &= \| \mathcal{\widehat T - T} \|_{\max} \\
    &\lesssim \frac{\sigma \kappa \mu_{0} \sqrt{r \log (p)}}{p}+\frac{\sigma^{2} \mu_{0}^{4} \kappa^{3} r^{3} \log (p)}{\lambda \sqrt{p}}.
\end{align*}
Since $\kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}$, and $\lambda/\sigma \gtrsim \kappa p^{3/4} \sqrt{\log(p)}$, it also holds that
\begin{align*}
    \| \mathcal{\widehat Z} \|_{\max} &\leq \| \mathcal{\widehat Z - Z} \|_{\max} + \| \mathcal{Z} \|_{\max} \\
    &\lesssim \sigma \sqrt{\log(p)}
\end{align*}
with probability at least $1 - O(p^{-6})$.  Therefore, with this same probability,
\begin{align}
    \| \widehat \Sigma^{(m)}_k - \widetilde \Sigma^{(m)}_k \| &\lesssim \bigg( \| \mathcal{\widehat Z} \|_{\max} + \| \mathcal{Z} \|_{\max} \bigg) \| \mathcal{\widehat Z} - \mathcal{Z} \|_{\max} \nonumber \\
    &\lesssim \sigma \sqrt{\log(p)} \| \mathcal{\widehat T - T} \|_{\max} \nonumber \\
    &\lesssim \sigma \sqrt{\log(p)} \bigg(\frac{\sigma \kappa \mu_{0} \sqrt{r \log (p)}}{p}+\frac{\sigma^{2} \mu_{0}^{4} \kappa^{3} r^{3} \log (p)}{\lambda \sqrt{p}}\bigg) \nonumber \\
    &\asymp \frac{\sigma^2 \kappa \mu_0 \sqrt{r} \log(p)}{p} + \frac{\sigma^3 \mu_0^4 \kappa^3 r^3 \log^{3/2}(p)}{\lambda \sqrt{p}}. \label{sigmahatminussigmatilde}
\end{align}
This argument reveals that with probability at least $1 - O(p^{-6})$,
\begin{align}
    \| \widehat \Sigma^{(m)}_k \| &\leq \| \widehat \Sigma^{(m)}_k - \widetilde \Sigma^{(m)}_k \| + \| \widetilde \Sigma^{(m)}_k \| \nonumber \\
    &\lesssim \frac{\sigma^2 \kappa \mu_0 \sqrt{r} \log(p)}{p} + \frac{\sigma^3 \mu_0^4 \kappa^3 r^3 \log^{3/2}(p)}{\lambda \sqrt{p}} + \max_{l} | (\mathbf{Z}_k)_{ml}^2 | \nonumber \\
    &\lesssim \frac{\sigma^2 \kappa \mu_0 \sqrt{r} \log(p)}{p} + \frac{\sigma^3 \mu_0^4 \kappa^3 r^3 \log^{3/2}(p)}{\lambda \sqrt{p}} + \sigma^2 \log(p) \nonumber \\
    &\asymp \sigma^2 \log(p), \label{sigmahatbound}
\end{align}
where the penultimate line is due to the fact that with probability at least $1- O(p^{-6})$, \begin{align*}
    \max_l | \big(\mathbf{Z}_k\big)_{ml}^2 | &\leq \sigma^2 + \max_l | \big(\mathbf{Z}_k\big)_{ml}^2 - \sigma^2_{ml} | \\
    &\lesssim \sigma^2 \log(p),
\end{align*}
together with the assumption that $\kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}$ and $\lambda/\sigma \gtrsim \kappa p^{3/4} \sqrt{\log(p)}$, so that the first two terms are less than $\sigma^2 \log(p)$.

 In addition, by \cref{lem:Vmatrixcloseness} (whose statement does not depend on this lemma), it holds that
\begin{align}
    \| \mathbf{W}_{\mathbf{V}_k}^{\top}  \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \| &\lesssim  \frac{1}{\lambda} \bigg( \frac{\sigma \sqrt{pr} + \kappa^2 \sigma \sqrt{p\log(p)}}{\lambda} \bigg) \label{approxcommute1}
\end{align}
with probability $1 - O(p^{-9})$.  In addition,
\begin{align}
    \| \mathbf{\widehat V}_k \mathbf{W}_{\mathbf{V}_k}^{\top} - \mathbf{V}_k \| &= \| \mathbf{\widehat V}_k  - \mathbf{V}_k \mathbf{W}_{\mathbf{V}_k}\|  \nonumber \\
    &\leq  \| \mathbf{\widehat V}_k  - \mathbf{V}_k \mathbf{W}_{\mathbf{V}_k}\|_F\nonumber  \\
    &= \| \sin\Theta(\mathbf{V}_k ,\mathbf{\widehat V}_k ) \|_F \nonumber \\
    &\leq\sqrt{r} \| \sin\Theta(\mathbf{V}_k ,\mathbf{\widehat V}_k ) \| \nonumber \\
    &\lesssim \sqrt{r} \frac{\sigma \sqrt{pr} + \kappa^2 \sigma \sqrt{p\log(p)}}{\lambda} \nonumber \\
    &\lesssim \frac{\sigma r \sqrt{p} + \kappa^2 \sigma \sqrt{rp\log(p)}}{\lambda}. \label{vsintheta}
\end{align}
Finally, by \eqref{approxcommute1} and \eqref{vsintheta}, we have that
\begin{align}
     \| \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} - \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \| &\leq  \| \mathbf{\widehat V}_k \big( \mathbf{W}_{\mathbf{V}_k}^{\top} \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat{\Lambda}}_k^{-1}  \mathbf{\widehat W}_k^{\top} \big) \| + \| \big(\mathbf{V}_k - \mathbf{\widehat V}_k \mathbf{W}_{\mathbf{V}_k}^{\top} \big) \mathbf{\Lambda}_k^{-1}  \|  \nonumber \\
     &\lesssim  \frac{\sigma r \sqrt{p} + \kappa^2 \sigma \sqrt{rp\log(p)}}{\lambda^2} \label{vhatminusv2}.
\end{align}
\item \textbf{Step 2: Bounding $\alpha_1$:} We have that
\begin{align}
    \alpha_1 &\coloneqq \bigg\| \bigg( \mathbf{\widehat W}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat V}_k^{\top} - \mathbf{\Lambda}_k^{-1} \mathbf{V}_k^{\top} \bigg) \widehat \Sigma^{(m)} \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \bigg\| \nonumber \\
    &\lesssim   \frac{\sigma^2 \log(p)}{\lambda} \| \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} - \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \|   \label{sigmahatboundused1} \\



    &\lesssim \frac{\sigma^2 \log(p)}{\lambda} \bigg(  \frac{\sigma r \sqrt{p} + \kappa^2 \sigma \sqrt{rp\log(p)}}{\lambda^2} \bigg) \label{vhatminusv3} \\
    &\asymp \frac{\sigma^3 r \sqrt{p} \log(p) + \sigma^3 \kappa^2 \sqrt{rp} \log^{3/2}(p)}{\lambda^3} \label{alpha1bound}
\end{align}
where \eqref{sigmahatboundused1} holds by \eqref{sigmahatminussigmatilde} and \eqref{vhatminusv3} follows from \eqref{vhatminusv2}.  This bound holds with probability at least $1 - O(p^{-6})$. 
\item \textbf{Step 3: Bounding $\alpha_2$:} Note that
\begin{align}
    \alpha_2 &\coloneqq \left\|\mathbf{\Lambda}_{k}^{-1} \mathbf{V}_{k}^{\top}\left(\widetilde{\Sigma}^{(m)}_k \mathbf{V}_{k} \mathbf{\Lambda}_{k}^{-1}-\widehat{\Sigma}^{(m)}_k \widehat{\mathbf{V}}_{k} \widehat{\Lambda}_{k}^{-1} \widehat{\mathbf{W}}_{k}^{\top}\right)\right\| \nonumber \\
    &\leq \frac{1}{\lambda} \bigg\| \widetilde \Sigma^{(m)}_k \mathbf{V}_k \mathbf{\Lambda}_k^{-1} - \widehat \Sigma^{(m)}_k \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \bigg\| \nonumber \\
    &\leq \frac{1}{\lambda} \bigg(  \frac{ \| \widetilde \Sigma^{(m)}_k - \widehat \Sigma^{(m)}_k\|}{\lambda} + \| \widehat \Sigma^{(m)}_k \| \| \mathbf{V}_k \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \| \bigg) \nonumber \\
    &\lesssim  \frac{1}{\lambda^2} \bigg( \frac{\sigma^{2} \kappa \mu_{0} \sqrt{r} \log (p)}{p}+\frac{\sigma^{3} \mu_{0}^{4} \kappa^{3} r^{3} \log ^{3 / 2}(p)}{\lambda \sqrt{p}} \bigg) \label{zhatminusz} \\
    &\quad + \frac{\sigma^2 \log(p)}{\lambda} \|  \mathbf{V}_k \mathbf{\Lambda}_k^{-1} - \mathbf{\widehat V}_k \mathbf{\widehat{\Lambda}}_k^{-1} \mathbf{\widehat W}_k^{\top} \| \label{zhatminusz2} \\
    &\lesssim  \frac{1}{\lambda^2} \bigg( \frac{\sigma^{2} \kappa \mu_{0} \sqrt{r} \log (p)}{p}+\frac{\sigma^{3} \mu_{0}^{4} \kappa^{3} r^{3} \log ^{3 / 2}(p)}{\lambda \sqrt{p}} \bigg) \nonumber \\
    &\quad + \frac{\sigma^2 \log(p)}{\lambda} \bigg( \frac{\sigma r \sqrt{p}+\kappa^{2} \sigma \sqrt{r p \log (p)}}{\lambda^{2}}\bigg) \label{vhatminusv4} \\
    &\asymp \frac{\sigma^3 r \sqrt{p} \log(p) + \sigma^3 \kappa^2 \sqrt{rp} \log^{3/2}(p)}{\lambda^3} + \frac{\sigma^2 \kappa \mu_0 \sqrt{r} \log(p)}{\lambda^2 p} \label{alpha2bound}
\end{align}
where \eqref{zhatminusz} follows from \eqref{sigmahatminussigmatilde},  \eqref{zhatminusz2} follows from \eqref{sigmahatbound}, and \eqref{vhatminusv4} follows from \eqref{vhatminusv2}. We note that \eqref{alpha2bound} follows since
\begin{align*}
    \frac{\sigma^3 \mu_0^4 \kappa^3 r^3 \log^{3/2}(p)}{\lambda^3 \sqrt{p}} \lesssim \frac{\sigma^3 \kappa^2 \sqrt{rp} \log^{3/2}(p)}{\lambda^3},
\end{align*}
which holds on the assumption $\kappa^2 \mu_0^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}$. 
\item 
\textbf{Step 4: Bounding $\alpha_3$:} Finally, we note that
\begin{align*}
    \| \mathbf{V}_k^{\top} \mathbf{\Lambda}_k^{-1} \bigg( \widetilde \Sigma^{(m)}_k - \Sigma^{(m)}_k \bigg) \mathbf{\Lambda}_k^{-1} \mathbf{V}_k \| &\leq r  \| \mathbf{V}_k^{\top} \mathbf{\Lambda}_k^{-1} \bigg( \widetilde \Sigma^{(m)}_k - \Sigma^{(m)}_k \bigg) \mathbf{\Lambda}_k^{-1} \mathbf{V}_k \|_{\max}.
\end{align*}
We now note that the $i_1,i_2$ entry of the above matrix can be written as
\begin{align*}
    \sum_{j_1,j_2} &\big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big)_{j_1 i_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_2 i_2} \bigg( \widetilde \Sigma^{(m)}_k - \Sigma^{(m)}_k \bigg)_{j_1 j_2}\\
    &= \sum_{j_1}\big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big)_{j_1 i_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_1 i_2} \bigg( \widetilde \Sigma^{(m)}_k - \Sigma^{(m)}_k \bigg)_{j_1 j_1} \\
    &= \sum_{j_1}\big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big)_{j_1 i_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_1 i_2} \bigg(\big( \mathbf{Z}_k\big)_{mj_1}^2 - \mathbb{E} \big( \mathbf{Z}_k\big)_{mj_1}^2 \bigg) \\
    &\coloneqq \eta_{i_1i_2}.
\end{align*}
This is a sum of $p_{-k}$ independent subexponential random variables, so we will apply Bernstein's inequality (Theorem 2.8.1 of \cite{vershynin_high-dimensional_2018}).  We note that
\begin{align*}
    \sum_{j_1} \bigg\| \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} &\big)_{j_1 i_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_1 i_2} \bigg(\big( \mathbf{Z}_k\big)_{mj_1}^2 - \mathbb{E} \big( \mathbf{Z}_k\big)_{mj_1}^2 \bigg) \bigg\|_{\psi_1}^2 \\
    &\leq \sum_{j_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big)_{j_1 i_1}^2 \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_1 i_2}^2 \|  \big( \mathbf{Z}_k\big)_{mj_1}^2 - \mathbb{E} \big( \mathbf{Z}_k\big)_{mj_1}^2 \|_{\psi_1}^2 \\
    &\lesssim\sigma^4 \max_{j_1} \| e_{j_1}^{\top}\mathbf{V}_k \mathbf{\Lambda}_k^{-1} \|^2 \sum_{j_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_1 i_2}^2  \\
    &\lesssim \frac{\sigma^4}{\lambda^4} \| \mathbf{V}_k \|_{2,\infty}^2 \sum_{j_1} (\mathbf{V}_k)_{j_1 i_2}^2 \\
    &\leq C\frac{\sigma^4}{\lambda^4} \mu_0^2 \frac{r}{p^2}
\end{align*}
In addition,
\begin{align*}
    \max_{j_1} \bigg\| \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1} \big)_{j_1 i_1} \big( \mathbf{V}_k \mathbf{\Lambda}_k^{-1}\big)_{j_1 i_2} \bigg(\big( \mathbf{Z}_k\big)_{mj_1}^2 - \mathbb{E} \big( \mathbf{Z}_k\big)_{mj_1}^2 \bigg) \bigg\|_{\psi_1} &\leq C \frac{\sigma^2}{\lambda^2} \mu_0^2 \frac{r}{p^2}.
\end{align*}
By Bernstein's inequality, it holds that
\begin{align*}
    \mathbb{P}\bigg\{ |\eta_{i_1i_2} | \geq t \bigg\} &\leq 2 \exp\bigg( -c \min\bigg\{ \frac{t^2}{ \frac{\sigma^4}{\lambda^4} \mu_0^2 \frac{r}{p^2}}, \frac{t}{\frac{\sigma^2}{\lambda^2} \mu_0^2 \frac{r}{p^2}} \bigg\} \bigg).
\end{align*}
