\end{align*}
since $\sigma/\sigma_{\min} = O(1)$. This implies that
\begin{align*}
  \frac{  \left\|\widehat{\mathbf{W}}_{1} \big(\widehat{\Gamma}^{(m)}\big)^{1/2} \widehat{\mathbf{W}}_{1}^{\top}-\big(\mathbf{\Gamma}^{(m)}_k\big)^{1/2}\right\|}{\lambda_{\min}^{1/2}(\mathbf{\Gamma}^{(m)}_k)} \to 0 
\end{align*}
almost surely, where we implicitly use the fact that $\lambda_{\min}(\mathbf{\Gamma}^{(m)}_k) \gtrsim \frac{\sigma_{\min}^2}{\lambda^2}$.  Consequently, we have the almost sure convergence
\begin{align}
    \| \widehat{\mathbf{W}}_{1}\big(\mathbf{\widehat \Gamma}^{(m)}_k\big)^{1/2}\widehat{\mathbf{W}}_{1}^{\top} \big(\mathbf{\Gamma}^{(m)}_k\big)^{-1/2} - \mathbf{I}_{r_1}\| \to 0. \label{gammaconv1}
\end{align}
Next, by \cref{thm:eigenvectornormality2}, it holds that
\begin{align}
   \mathbf{\widehat W}_{1}^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1/2}  \mathbf{\widehat W}_{1} \big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot} -  \big({\mathbf{U}} \mathbf{\widehat W}_{1}\big)_{i\cdot} + \big( {\mathbf{U}}  \mathbf{\widehat W}_{1}\big)_{j\cdot} \big) \to N(0, \mathbf{I}_{r_1}), \label{normalconv2}
\end{align}
where we note that the proof of \cref{thm:eigenvectornormality2} reveals that rows $i$ and $j$ of $\mathbf{\widehat{U}}$ are asymptotically independent.  
Therefore, \eqref{normalconv2}, \eqref{gammaconv1}, and the continuous mapping theorem imply
\begin{align*}
    \big(\widehat \Gamma^{(i)} + \widehat \Gamma^{(j)} \big)^{-1/2}\big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot} -  \big({\mathbf{U}}\mathbf{\widehat W}_{1}\big)_{i\cdot} + \big( {\mathbf{U}} \mathbf{\widehat W}_{1}\big)_{j\cdot} \big) \to N(0, \mathbf{I}_{r_1} ).
\end{align*}
Under $H_0$, by Proposition 2 of \cite{agterberg_estimating_2022} it holds that $({\mathbf{U}} \mathbf{\widehat W}_{1})_{i\cdot} = ({\mathbf{U}} \mathbf{\widehat W}_{1})_{j\cdot}$.  Therefore, under the null it holds that
\begin{align*}
    \big(\widehat \Gamma^{(i)} + \widehat \Gamma^{(j)} \big)^{-1/2}\big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot} \big) \to N(0, \mathbf{I}_{r_1}),
\end{align*}
and hence that
\begin{align*}
    \widehat T_{ij} &= \|  \big(\widehat \Gamma^{(i)} + \widehat \Gamma^{(j)} \big)^{-1/2}\big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot} \big) \|^2 \to \chi^2_{r_1}.
\end{align*}
Next, under any alternative, Slutsky's Theorem and \cref{gammaconv1} imply
\begin{align*}
    \big(\widehat \Gamma^{(i)} &+ \widehat \Gamma^{(j)} \big)^{-1/2}\big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot}-  \big(\widehat \Gamma^{(i)} + \widehat \Gamma^{(j)} \big)^{1/2} \mathbf{\widehat W}_{1}^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1/2}  \mathbf{\widehat W}_{1}  \big({\mathbf{U}}\mathbf{\widehat W}_{1}\big)_{i\cdot} + \big( {\mathbf{U}} \mathbf{\widehat W}_{1}\big)_{j\cdot} \big)\\
    &\qquad \qquad \to N(0,\mathbf{I}_{r_1}),
\end{align*}
which further implies that
\begin{align*}
     \big(\widehat \Gamma^{(i)} &+ \widehat \Gamma^{(j)} \big)^{-1/2}\big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot} \big) -  \mathbf{\widehat W}_{1}^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1/2}  \mathbf{\widehat W}_{1}  \big({\mathbf{U}}\mathbf{W}_{1}\big)_{i\cdot} + \big( {\mathbf{U}} \mathbf{W}_{1}\big)_{j\cdot} \big) \\
     &\to N(0, \mathbf{I}_{r_1}).
\end{align*}
Therefore, the distribution of the random variable
\begin{align*}
   \big(\widehat \Gamma^{(i)} + \widehat \Gamma^{(j)} \big)^{-1/2}\big( \mathbf{\widehat{U}}_{i\cdot} - \mathbf{\widehat{U}}_{j\cdot} \big)
\end{align*}
is asymptotically equivalent to a Gaussian random variable with mean
\begin{align*}
    \mathbf{\widehat W}_{1}^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1/2}  \mathbf{\widehat W}_{1}  \big({\mathbf{U}}\mathbf{\widehat W}_{1}\big)_{i\cdot} + \big( {\mathbf{U}} \mathbf{\widehat W}_{1}\big)_{j\cdot} \big).
\end{align*}
Therefore, let $\eta_{ij}$ denote this Gaussian random variable. By the Delta method, we have that
\begin{align*}
    \widehat T_{ij} &= \| \eta_{ij}  \|^2,
\end{align*}
where the equality is in distribution.  It is straightforward to see that $\eta_{ij}^2$ is a noncentral $\chi^2$ distributed random variable with noncentrality parameter
\begin{align*}
    \|   \mathbf{\widehat W}_{1}^{\top} &\bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1/2}  \mathbf{\widehat W}_{1}  \big({\mathbf{U}}\mathbf{\widehat W}_{1}\big)_{i\cdot} + \big( {\mathbf{U}} \mathbf{\widehat W}_{1}\big)_{j\cdot} \big) \|^2\\
    &= \big( {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \big)^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1}  \big( {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \big).
\end{align*}
When this term converges to $\gamma < \infty$, we immediately obtain the result under the alternative.  Therefore, it suffices to show that
\begin{align}
     \big( {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \big)^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1}  \big( {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \big) \to \infty \label{snronditiontoverify2}
\end{align}
whenever
\begin{align}
    \frac{\lambda_{\min}(\mathcal{S})}{\sigma} p \| \mathbf{\Pi}_{i\cdot} - \mathbf{\Pi}_{j\cdot} \| \to \infty. \label{snrsnr}
\end{align}
We now verify this condition, as well the condition \eqref{snrconditiontoverify}. To examine the SNR condition, we note that Lemma 1 of \cite{agterberg_estimating_2022} shows that
\begin{align*}
    \lambda \asymp \lambda_{\min}(\mathcal{S}) p^{3/2}
\end{align*}
as long as  $r$ is bounded.  Therefore, the signal-strength condition 
\begin{align*}
    \frac{\lambda_{\min}(\mathcal{S})^2}{\sigma^2} \gg \frac{1}{p^{3/2}} \log(p)
\end{align*}
is equivalent to the condition
\begin{align*}
    \frac{\lambda^2}{\sigma^2} \gg p^{3/2} \log(p),
\end{align*}
which is guaranteed whenever
\begin{align*}
    \lambda/\sigma \gg p^{3/4} \sqrt{\log(p)},
\end{align*}
which is what is needed for \cref{thm:civalidity2}.  In addition, we note that the incoherence condition $\mu_0 = O(1)$ is guaranteed by Lemma 1 of \cite{agterberg_estimating_2022}, as well as the fact that $\kappa = O(1)$.  This verifies \eqref{snrconditiontoverify}.

 For the condition \eqref{snronditiontoverify2}, we note that
 \begin{align*}
    \big( {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \big)^{\top} \bigg( \Gamma^{(i)} + \Gamma^{(j)} \bigg)^{-1}  \big( {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \big) &\gtrsim \| {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \|^2 \frac{\lambda^2}{\sigma^2}
 \end{align*}
 Therefore, this term diverges as long as 
 \begin{align}
      \| {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \| \gg \frac{\sigma}{\lambda} \asymp \frac{\sigma}{\lambda_{\min}(\mathcal{S}) p^{3/2}} \label{snrconditiontoverify3}
 \end{align}





















By Proposition 2 of \cite{agterberg_estimating_2022}, one has that ${\mathbf{U}}_k = \mathbf{\Pi}_k {\mathbf{U}}^{(\mathrm{pure})}$ and that ${\mathbf{U}}^{(\mathrm{pure})}$ has entries of order $\frac{1}{\sqrt{p}}$.  Hence,
\begin{align*}
    \| {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \| &= \| \big( \mathbf{\Pi }{\mathbf{U}}^{(\mathrm{pure})} \big)_{i\cdot} - \big( \mathbf{\Pi } {\mathbf{U}}^{(\mathrm{pure})} \big)_{j\cdot} \| \\
    &\asymp \frac{1}{\sqrt{p}} \| \mathbf{\Pi}_{i\cdot} - \mathbf{\Pi}_{j\cdot} \|.
\end{align*}
Consequently, 
\begin{align*}
    \frac{\lambda_{\min}(\mathcal{S})}{\sigma} p  \| \mathbf{\Pi}_{i\cdot} - \mathbf{\Pi}_{j\cdot} \| &\asymp   \frac{\lambda_{\min}(\mathcal{S})}{\sigma}p^{3/2}  \| {\mathbf{U}}_{i\cdot} - {\mathbf{U}}_{j\cdot} \|
\end{align*}
and therefore \eqref{snrconditiontoverify3} holds whenever \eqref{snrsnr} holds, which completes the proof.

 \label{thm:simultaneousinference}
Instate the conditions in \cref{thm:eigenvectornormality}, and suppose that
\begin{align*}
    \mu_0^2 \kappa^2 r^{3/2} \sqrt{\log(p)} \lesssim p^{1/4}.
\end{align*}
