where we set $\xi_J$ as the random variable with entries $\xi_{ijk}$ from \cref{lem:xiijkgaussian}.  We will show that $\xi_J$ is asymptotically Gaussian with covariance $S_J$, and we will demonstrate that $\widehat S_J$ approximates $S_J$, which will yield the result.  
\begin{itemize}
\item \textbf{Step 1: Limiting Covariance Structure and First-Order Approximation}: 
Recall we define $s^2_{\min}$ via
\begin{align*}
    s^2_{\min} \coloneqq \lambda_{\min}(S_J),
\end{align*}



































If it holds that
\begin{align}
    s_{\min} &\gg |J| \sigma\max\bigg\{ \frac{ \kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}}, \frac{\sigma \mu_0^4 \kappa^3 r^2 \log(p)}{\lambda \sqrt{p}}\bigg\}, \label{smin0}
\end{align}
then 
\begin{align*}
    S_J^{-1/2} \mathrm{Vec}(\mathcal{T}_J) &= S_{J}^{-1/2} \xi_J + o(1).
\end{align*}
with probability at least $1 - O(|J|p^{-9})$.  It now remains to show that $\mathrm{Cov}(\xi_J) \approx S_J$.  By the proof of \cref{lem:xiijkgaussian}, it holds that
\begin{align*}
    \mathrm{Var}(\xi_{ijk}) &= s^2_{ijk} \bigg( 1 + O\big( \frac{\mu_0^2 r}{p} \big) \bigg).
\end{align*}
Therefore, it suffices to consider the covariance terms.  Observe that
\begin{align*}
    &\mathrm{Cov}\bigg( \xi_{ijk} \xi_{i'j'k'}\bigg) \\&= \mathbb{E}\bigg( {e}_{i}^{\top} \mathbf{Z}_{1} \mathbf{V}_{1} \mathbf{V}_{1}^{\top} e_{(j-1) p_{3}+k}+e_{j}^{\top} \mathbf{Z}_{2} \mathbf{V}_{2} \mathbf{V}_{2}^{\top} e_{(k-1) p_{1}+i}+e_{k}^{\top} \mathbf{Z}_{3} \mathbf{V}_{3} \mathbf{V}_{3}^{\top} e_{(i-1) p_{2}+j} \bigg)\\
    &\times \bigg( {e}_{i'}^{\top} \mathbf{Z}_{1} \mathbf{V}_{1} \mathbf{V}_{1}^{\top} e_{(j'-1) p_{3}+k'}+e_{j'}^{\top} \mathbf{Z}_{2} \mathbf{V}_{2} \mathbf{V}_{2}^{\top} e_{(k'-1) p_{1}+i'}+e_{k'}^{\top} \mathbf{Z}_{3} \mathbf{V}_{3} \mathbf{V}_{3}^{\top} e_{(i'-1) p_{2}+j'} \bigg).
\end{align*}
By a similar argument to Step 1 of the proof of \cref{lem:xiijkgaussian}, it holds that the cross term satisfies
\begin{align*}
    \mathbb{E}&\bigg( e_i^{\top} \mathbf{Z}_1 \mathbf{V}_1 \mathbf{V}_1^{\top} e_{(j-1)p_3 + k}\bigg) \bigg( e_{j'}^{\top} \mathbf{Z}_2 \mathbf{V}_2 \mathbf{V}_2^{\top} e_{(k'-1)p_1 + i'} \bigg) \\
    &= O\bigg( \sigma^2 \mu_0^2 \frac{r}{p} \bigg( \| e_{(j-1)p_3 + k} \mathbf{V}_1 \|^2 + \| e_{(k'-1)p_1 + i'} \mathbf{V}_2 \|^2 \bigg) \bigg) \\
    &= O\bigg(  \sigma^2 \mu_0^4 \frac{r^2}{p^2}  \bigg).
\end{align*}
The other cross terms can be handled similarly.  Hence, the only remaining terms are those such that $i = i'$, $j = j'$, or $k = k'$.  If $i= i'$, we have
\begin{align*}
    \mathbb{E}\bigg( &e_i^{\top} \mathbf{Z}_1 \mathbf{V}_1^{\top} e_{(j-1)p_3 + k} \bigg)\bigg( e_i^{\top} \mathbf{Z}_1 \mathbf{V}_1^{\top} e_{(j'-1)p_3 + k'} \bigg) \mathbb{I}_{\{i=i'\}}\\
    &=  e_{(j-1)p_2 + k}^{\top} \mathbf{V}_1 \mathbf{V}_1^{\top} \big( \Sigma^{(i)} \big)  \mathbf{V}_1 \mathbf{V}_1^{\top} e_{(j'-1)p_3 + k'},
\end{align*}
with similar values if $j = j'$ or $k = k'$; in particular, these are the entries of $S_J$ by definition.  Hence








\begin{align}
    \mathrm{Cov}(\xi_J) &= S_J + O\bigg( \frac{|J|^2\mu_0^2 r}{p} s_{\min}^2 \bigg),\label{Sjapprox}
\end{align}
provided that $s_{\min}^2 \gg \sigma^2 \mu_0^2 r/p$.  
\item \textbf{Step 2: Gaussian Approximation}: We now study the Gaussian approximation of the vector $S_{J}^{-1/2} \mathrm{Vec}(\mathcal{T}_J - \mathcal{\widehat T}_J)$.    We will apply Corollary 2.2 of \cite{shao_berryesseen_2022}.  Define, for some sufficiently large constant $C$,
\begin{align*}
    \Delta = \Delta^{(i)} &= C  \left(|J| \frac{\sigma \kappa^2 \mu_{0}^{3} r^{3 / 2} \sqrt{\log (p)}}{p^{3 / 2}}+|J| \frac{\sigma^{2} \mu_{0}^{4} \kappa^{3} r^{2} \log (p)}{\lambda \sqrt{p}}\right).
\end{align*}
Note that $\mathrm{Cov}(\xi_J)$ is invertible with smallest eigenvalue at least $s^2_{\min}(1- o(1))$ since $S_J$ is invertible provided that $|J|^2  \ll p /(\mu_0^2 r)$.  Consequently, we have that
\begin{align*}
    \lambda_{\min}\big( \mathrm{Cov}^{1/2}(\xi_J)\big) &\gtrsim s_{\min} \gg \Delta
\end{align*}
as long as
\begin{align}
    s_{\min} &\gg |J| \max \bigg\{   \frac{\sigma \kappa^2 \mu_{0}^{3} r^{3 / 2} \sqrt{\log (p)}}{p^{3 / 2}}, \frac{\sigma^{2} \mu_{0}^{4} \kappa^{3} r^{2} \log (p)}{\lambda \sqrt{p}}\bigg\}. \label{smin1}
\end{align}
Hence, it holds that
\begin{align*}
    \mathrm{Cov}(\xi_J)^{-1/2}
    \mathrm{Vec}(\mathcal{T}_J) &= \mathrm{Cov}(\xi_J)^{-1/2} \xi_J + \frac{\Delta}{s_{\min}}
\end{align*}
with probability at least $1 - O(|J|p^{-9})$.  Let this event be denoted $\mathcal{A}$.  By Corollary 2.2 of \cite{shao_berryesseen_2022}, it holds that
\begin{align*}
    \sup_{A \in \mathcal{A} } \bigg| &\mathbb{P}\bigg\{ \mathrm{Cov}^{-1/2} \mathrm{Vec}(\mathcal{T}_J - \mathcal{\widehat T}_J) \in A \bigg\} - \mathbb{P}\bigg\{ Z \in A \bigg\} \bigg| \\
    &\lesssim |J|^{1/2}\gamma + \frac{\Delta}{s_{\min}} \mathbb{E} \| \mathrm{Cov}^{-1/2}\xi_J \|+ |J|p^{-9}, 
\end{align*}
where $\gamma$ is the sum of the third moments of the independent random variables in $\xi_J$ (see step 2 of the proof of \cref{lem:xiijkgaussian} for the explicit definition in terms of the indices of $\xi_J$).  A straightforward modification of the proof of \cref{lem:xiijkgaussian} shows that
\begin{align*}
    \gamma &\lesssim  \frac{|J|}{\sqrt{p\log(p)}}
\end{align*}
as long as $s_{\min} \gg \Delta$, which is true by assumption.  In addition, by subgaussianity, it holds that
\begin{align*}
    \mathbb{E} \| \mathrm{Cov}^{-1/2}( \xi_J) \xi_J \| &\lesssim | J |^{1/2}.
\end{align*}
Consequently, we have that
\begin{align*}
      \sup_{A \in \mathcal{A} } &\bigg| \mathbb{P}\bigg\{ \mathrm{Cov}(\xi_J)^{-1/2} \mathrm{Vec}(\mathcal{T}_J - \mathcal{\widehat T}_J) \in A \bigg\} - \mathbb{P}\bigg\{ Z \in A \bigg\} \bigg| \\
