\end{align*}
which holds as long as
\begin{align}
    s_{\min} \gg |J| \frac{\sigma \kappa^2 \mu_{0}^{3} r^{3 / 2} \sqrt{\log (p)}}{p^{3 / 2}}+|J| \frac{\sigma^{2} \mu_{0}^{4} \kappa^{3} r^{2} \log (p)}{\lambda \sqrt{p}}. \label{smin2}
\end{align}
Therefore, for any $A \in \mathcal{A}$,
\begin{align*}
  \bigg| &\mathbb{P}\bigg\{ S_J^{-1/2} \mathrm{Vec}(\mathcal{T}_J - \mathcal{\widehat T}_J) \in A \bigg\} - 
    \mathbb{P} \bigg\{ Z \in A \bigg\} \bigg| \\
    &\leq \bigg| \mathbb{P}\bigg\{ \mathrm{Cov}(\xi_J)^{-1/2}(\mathrm{Vec}(\mathcal{T}_J - \mathcal{\widehat T}_J) \in {\rm Cov}(\xi_J)^{-1/2} S_J^{1/2} A \bigg\} - \mathbb{P}\bigg\{ Z' \in {\rm Cov}(\xi_J)^{-1/2} S_J^{1/2} A \bigg\} \bigg| \\
    &\quad + \bigg| \mathbb{P}\bigg\{ Z' \in {\rm Cov}(\xi_J)^{-1/2} S_J^{1/2} A \bigg\} - \mathbb{P}\bigg\{ Z \in A \bigg\} \bigg| \\
    &\lesssim \frac{|J|^{3/2}}{\sqrt{p\log(p)}} + \frac{ |J|^{3/2}}{s_{\min}}\bigg( \frac{\sigma \kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}} + \frac{\sigma^2 \mu_0^4 \kappa^3 r^2 \log(p)}{\lambda \sqrt{p}} \bigg) \\
    &\quad + \bigg| \mathbb{P}\bigg\{ Z' \in {\rm Cov}(\xi_J)^{-1/2} S_J^{1/2} A \bigg\} - \mathbb{P}\bigg\{ Z \in A \bigg\} \bigg|
\end{align*}
where $Z'$ is an independent $|J|$-dimensional standard Gaussian random variable.  To bound the remaining term, by Theorem 1.3 of \cite{devroye_total_2022}, it holds that
\begin{align*}
    \sup_{A \in \mathcal{A}} \bigg| \mathbb{P}\bigg\{ S_J^{-1/2} {\rm Cov}(\xi_J)^{1/2}Z \in A \bigg\} - \mathbb{P}\bigg\{ Z' \in  A \bigg\} \bigg| &\leq d_{TV} (  S_J^{-1/2} {\rm Cov}(\xi_J)^{1/2}Z, Z' ) \\
    &\lesssim \| I - S_J^{-1} {\rm Cov}(\xi_J) \| \\
    &\lesssim |J|^2 \mu_0^2 \frac{r}{p},
\end{align*}
where the final inequality holds by \eqref{Sjapprox}.  Putting it all together, it holds that
\begin{align}
    \sup_{A \in \mathcal{A}} \bigg| &\mathbb{P}\bigg\{ S_J^{-1/2} \mathrm{Vec}(\mathcal{T}_J - \mathcal{\widehat T}_J) \in A \bigg\} - \mathbb{P}\bigg\{ Z \in A \bigg\} \bigg| \nonumber \\&\lesssim \frac{|J|^{3/2}}{\sqrt{p\log(p)}} + \frac{|J|^2\mu_0^2 r}{p}  +\frac{ |J|^{3/2}}{s_{\min}}\bigg( \frac{\sigma \kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}} + \frac{\sigma^2 \mu_0^4 \kappa^3 r^2 \log(p)}{\lambda \sqrt{p}} \bigg). \label{tjapprox}
\end{align}
We note that this bound is only non-vacuous if these terms are smaller than one, which requires that
\begin{align}
   s_{\min} &\gg |J|^{3/2} \max\bigg\{ \frac{\sigma \kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}} , \frac{\sigma^2 \mu_0^4 \kappa^3 r^2 \log(p)}{\lambda \sqrt{p}} \bigg\}, \label{smin4}
\end{align}
which is the stronger than the requirements \eqref{smin0},\eqref{smin1}, and \eqref{smin2} by factors of $|J|$. 
\item 
\textbf{Step 3: Covariance Estimation}: We now consider the plug-in estimation of the covariance $S_J$.  The proof of \cref{thm:civalidity} shows that with probability at least $1 - O(p^{-6})$
\begin{align*}
    |(s^{(i)})^2 - (\widehat s^{(i)})^2 |  &\lesssim \sigma^2 \mu_0 \frac{\sqrt{r \log(p)}}{p}  \| e_{(j-1)p_3 + k}^{\top} \mathbf{V}_1 \|^2 + \frac{\sigma^2 \kappa \mu_0^2 r^{3/2} \log(p)}{p^3} \\
    &\quad + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}},
\end{align*}
with similar bounds for $s^{(j)}$ and $s^{(k)}$, where the notation is defined in the proof of \cref{thm:civalidity} (see \cref{sec:civalidityproofs}). 
A straightfoward modification of the same proof for the cross-terms reveals that with probability at least $1 - O(|J|^2 p^{-6})$
\begin{align*}
    \| &S_J - \widehat S_J \| \\
    &\leq |J|^2 \| S_J - \widehat S_J \|_{\max} \\

    &\lesssim 
    |J|^2 \sigma^2 \mu_0^3 \frac{ r^{3/2} \sqrt{\log(p)}}{p^3}  + |J|^2\bigg( \frac{\sigma^2 \kappa \mu_0^2 r^{3/2} \log(p)}{p^3} + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}} \bigg) \\

    &\ll s^2_{\min}, 

\end{align*}
where the penultimate inequality holds as long as 
\begin{align}
    s_{\min}^2 &\gg |J|^2 \max\bigg\{ \frac{\sigma^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^3}, \frac{\sigma^2 \kappa \mu_0^2 r^{3/2} \log(p)}{p^3}, \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}} \bigg\}. \label{sminsecond}
\end{align}
Denote
\begin{align}
    M &\coloneqq 
    |J|^2 \sigma^2 \mu_0^3 \frac{ r^{3/2} \sqrt{\log(p)}}{p^3} 
    + |J|^2\bigg( \frac{\sigma^2 \kappa \mu_0^2 r^{3/2} \log(p)}{p^3} 
     + \frac{\sigma^3 \mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{\lambda p^{3/2}} \bigg), \label{Mdef}
\end{align}
so that it holds that
\begin{align*}
    \| S_J - \widehat S_J \| \lesssim M
\end{align*}
with probability at least $1 - O(|J|^2 p^{-6})$.  By Theorem 6.2 of \cite{higham_functions_2008}, it holds that
\begin{align*}
    \| \widehat S_J^{1/2} - S_J^{1/2} \| &\leq \frac{1}{ \lambda_{\min}^{1/2}(\widehat S_J) + \lambda_{\min}^{1/2}(S_J)} \| \widehat S_J - S_J \| \\
    &\lesssim \frac{1}{s_{\min}} M \\
    &\ll s_{\min}
\end{align*}
provided $M \ll s^2_{\min}$. Therefore, by Weyl's inequality, $\widehat S_J$ is invertible and
\begin{align*}
    \| \bigg( S_{J}^{-1/2} - \widehat S_{J}^{-1/2} \bigg) (\mathcal{\widehat T}_J - \mathcal{T}_J ) \| &\leq |J | \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} \| S_{J}^{-1/2} - \widehat S_{J}^{-1/2} \| \\
    &\leq |J| \| S_{J}^{-1/2} ( \widehat S_{J}^{1/2} - S_{J}^{1/2}) \widehat S_{J}^{-1/2} \| \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} \\
    &\lesssim |J| \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} \frac{1}{s_{\min}^2} \| \widehat S_J^{1/2} - S_J^{1/2} \| \\
    &\lesssim |J| \| \mathcal{\widehat T} - \mathcal{T} \|_{\max} \frac{1}{s_{\min}^3} M \\
    &\lesssim  \frac{|J| M }{s_{\min}^3} \bigg( \frac{\sigma \kappa \mu_{0} \sqrt{r \log (p)}}{p}+\frac{\sigma^{2} \mu_{0}^{4} \kappa^{3} r^{3} \log (p)}{\lambda \sqrt{p}} \bigg) \\
    &=: \varepsilon,
\end{align*}
where we note that the final inequality holds with probability at least $1 - O(p^{-6})$ by \cref{cor:maxnormbound}.  
\item 
\textbf{Step 4: Completing the Proof}: Just as in the proof of \cref{thm:civalidity2}, for a convex set $A$ denote $A^{\varepsilon}$ as the $\varepsilon$-enlargment via
\begin{align*}
    A^{\varepsilon} &\coloneqq \{x : d(x,A) \leq \varepsilon \}.
\end{align*}
By Theorem 1.2 of \cite{raicv_multivariate_2019}, if $A$ is an isotropic $\mathbb{R}^{|J|}$-dimensional random gaussian vector, it holds that
\begin{align*}
    \mathbb{P}\bigg( Z \in A^{\varepsilon}\setminus A\bigg) &\lesssim |J|^{1/4} \varepsilon \lesssim |J|^{1/2} \varepsilon.
\end{align*}
We are now prepared to complete the proof.  Let $A_{\alpha}$ denote the confidence region such that $\mathbb{P}(Z \in A_{\alpha}) = 1 - \alpha$, where $Z \sim N(0, \mathbf{I}_{|J|})$.  Then
\begin{align*}
    \bigg|\mathbb{P}&\bigg\{  \mathrm{Vec}(\mathcal{T}_J) \in \mathrm{C.I.}_{\alpha}(\mathcal{\widehat T}_J) \bigg\} - (1 - \alpha) \bigg| \\
    &= \bigg| \mathbb{P}\bigg\{ \widehat S_{J}^{-1/2}\bigg( \mathrm{Vec}\big( \mathcal{\widehat T}_J - \mathcal{T}_J \big) \bigg) \in \mathcal{A}_{\alpha} \bigg\} - (1 - \alpha) \bigg| \\
    &\leq \bigg| \mathbb{P}\bigg\{ S_{J}^{-1/2} \bigg( \mathrm{Vec}\big( \mathcal{\widehat T}_J - \mathcal{T}_J \big) \bigg) \in \mathcal{A}_{\alpha}^{\varepsilon} \bigg\} \cap \bigg\{\bigg|\big( S_{J}^{-1/2} - \widehat S_{J}^{-1/2}\big) \bigg( \mathrm{Vec}\big( \mathcal{\widehat T}_J - \mathcal{T}_J \big) \bigg)\bigg| \leq \varepsilon \bigg\} \\
    &\qquad\qquad- (1 - \alpha) \bigg| \\
    &\quad + \mathbb{P}\bigg\{ \bigg|\big( S_{J}^{-1/2} - \widehat S_{J}^{-1/2}\big) \bigg( \mathrm{Vec}\big( \mathcal{\widehat T}_J - \mathcal{T}_J \big) \bigg) \big| > \varepsilon \bigg\} \\
    &\leq \bigg| \mathbb{P}\bigg\{  S_{J}^{-1/2} \bigg( \mathrm{Vec}\big( \mathcal{\widehat T}_J - \mathcal{T}_J \big) \bigg) \in \mathcal{A}_{\alpha}^{\varepsilon} \bigg\} - (1- \alpha) \bigg|+ O(|J|^2p^{-6}) \\
    &\leq \bigg| \mathbb{P}\bigg\{  S_{J}^{-1/2} \bigg( \mathrm{Vec}\big( \mathcal{\widehat T}_J - \mathcal{T}_J \big) \bigg) \in \mathcal{A}_{\alpha}^{\varepsilon} \bigg\} - \mathbb{P}\bigg\{ Z \in A_\alpha^{\varepsilon} \bigg\} \bigg| + \bigg| \mathbb{P}\bigg\{ Z \in A_{\alpha}^{\varepsilon} \bigg\} - (1 - \alpha) \bigg| \\
    &\quad + O(|J|^2p^{-6}) \\
    &\lesssim \frac{|J|^{3/2}}{\sqrt{p\log(p)}} + \frac{|J|^2\mu_0^2 r}{p}  +\frac{ |J|^{3/2}}{s_{\min}}\bigg( \frac{\sigma \kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}} + \frac{\sigma^2 \mu_0^4 \kappa^3 r^2 \log(p)}{\lambda \sqrt{p}} \bigg) \\
    &\quad + \bigg| \mathbb{P}\bigg\{ Z \in A_{\alpha}^{\varepsilon} \bigg\} - \mathbb{P}\bigg\{ Z \in A_{\alpha} \bigg\} \bigg| + O(|J|^2p^{-6}) \\
