 \sigma_{\min}^2 \times   \bigg\{ &\| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \| e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2,\\
 &\quad \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\}.
\end{align*}
Therefore, as long as 
\begin{align*}
    \min\bigg\{ &\| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \|e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2, \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \\
    &\quad \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\} \\
    &\gg \max\bigg\{ \frac{\kappa \mu_0^2 r^{3/2} \log(p)}{p^3} , \frac{\mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{(\lambda/\sigma)p^{3/2}}, \frac{\kappa^4 \mu_0^6 r^3 \log(p)}{p^3}, \frac{\mu_0^8 \kappa^6 r^3 \log^2(p)}{(\lambda/\sigma)^2 p} \bigg\}.
    \end{align*}
    we see all our results continue to hold. In particular, when $\kappa,\mu_0 = O(1)$, it is sufficient to have that
    \begin{align*}
         \min\bigg\{ &\| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \| e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2, \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \\
         &\quad \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\} \\
    &\gg \max\bigg\{ \frac{r^{3} \log(p)}{p^3} , \frac{r^{3} \log^{3/2}(p)}{(\lambda/\sigma)p^{3/2}}\bigg\},
    \end{align*}
    which is precisely the condition in \cref{thm:entrytesting_v1}. 
    \end{itemize}

\begin{align*}
    \mathcal{\widehat T}_{ijk} - \mathcal{\widehat T}_{i'j'k'} - (\mathcal{T}_{ijk} - \mathcal{\widehat T}_{i'j'k'}) &= \xi_{ijk} - \mathcal{\xi}_{i'j'k'} + O\bigg( \frac{\sigma \kappa^2 \mu_0^3 r^{3/2} \sqrt{\log(p)}}{p^{3/2}} + \frac{\sigma^2 \mu_0^4 \kappa^3 r^2 \log(p)}{\lambda \sqrt{p}} \bigg).
\end{align*}

\begin{align*}
    \mathrm{Cov}\bigg( \xi_{ijk} \xi_{i'j'k'} \bigg) &= \mathbb{I}_{\{i= i'\}} e_{(j-1)p_3 + k}^{\top}  \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} \widehat \Sigma^{(i)} \mathbf{\widehat V}_1 \mathbf{\widehat V}_1^{\top} e_{(j'-1)p_3 + k'} \\
    &\quad + \mathbb{I}_{\{j= j'\}} e_{(k-1)p_1 + i}^{\top}  \mathbf{\widehat V}_2 \mathbf{\widehat V}_2^{\top}\widehat \Sigma^{(j)} \mathbf{\widehat V}_2 \mathbf{\widehat V}_2^{\top} e_{(k'-1)p_3 + i'}  \\
    &\quad + \mathbb{I}_{\{k= k'\}} e_{(i-1)p_2 + j}^{\top}  \mathbf{\widehat V}_3 \mathbf{\widehat V}_3^{\top} \widehat \Sigma^{(k)} \mathbf{\widehat V}_3 \mathbf{\widehat V}_3^{\top} e_{(i'-1)p_2 +j'} \\
    &\qquad + O\bigg(  \mu_0^2 \frac{r}{p} \bigg[ s^2_{ijk} + s^2_{i'j'k'}\bigg] \bigg).
\end{align*}

\begin{align*}
      \mathbb{P}\bigg\{  \frac{ \mathcal{\widehat T}_{ijk} - \mathcal{\widehat T}_{i'j'k'} - (\mathcal{T}_{ijk} - \mathcal{\widehat T}_{i'j'k'})}{s_{\{ijk\}\{i'j'k'\}}} \leq t \bigg\} &\leq \mathbb{P}\bigg\{ \frac{\xi_{ijk} - \xi_{i'j'k'}}{s_{\{ijk\}\{i'j'k'\}}} \leq t + \frac{\Delta}{s_{\{ijk\}\{i'j'k'\}}} \bigg\} + C_3 p^{-9} \\
      &\leq \Phi\bigg\{ t +   \frac{\Delta}{s_{\{ijk\}\{i'j'k'\}}} \bigg\} + C_3 p^{-9} + \eta \\
      &\leq \Phi(t) + \frac{\Delta}{s_{\{ijk\}\{i'j'k'\}}}+ C_3 p^{-9} + \eta \\
      &= \Phi(t) + o(1),
\end{align*}

\begin{align*}
    \mathcal{R}_{\alpha} &\coloneqq \bigg(\frac{ \mathcal{\widehat T}_{ijk} - \mathcal{\widehat T}_{i'j'k'}}{\widehat s_{\{ijk\}\{i'j'k'\}}} - z_{\alpha/2} , \frac{ \mathcal{\widehat T}_{ijk} - \mathcal{\widehat T}_{i'j'k'}}{\widehat s_{\{ijk\}\{i'j'k'\}}} + z_{\alpha/2}\bigg).
\end{align*}

\begin{align*}
    &s^2_{\{ijk\}\{i'j'k'\}} \\
    &\gtrsim \sigma^2 \min\bigg\{ \| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|, \| e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|,\\
    &\quad \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|, \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \| \bigg\}.
\end{align*}

\begin{align*}

 \sigma_{\min}^2 \times   \bigg\{ &\| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \| e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2,\\
 &\quad \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\}.
\end{align*}

\begin{align*}
    \min\bigg\{ &\| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \|e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2, \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \\
    &\quad \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\} \\
    &\gg \max\bigg\{ \frac{\kappa \mu_0^2 r^{3/2} \log(p)}{p^3} , \frac{\mu_0^5 r^3 \kappa^2 \log^{3/2}(p)}{(\lambda/\sigma)p^{3/2}}, \frac{\kappa^4 \mu_0^6 r^3 \log(p)}{p^3}, \frac{\mu_0^8 \kappa^6 r^3 \log^2(p)}{(\lambda/\sigma)^2 p} \bigg\}.
    \end{align*}

\begin{align*}
         \min\bigg\{ &\| e_{(j-1)p_3 + k }^{\top} \mathbf{V}_1\|^2, \| e_{(j'-1)p_3 + k'}^{\top} \mathbf{V}_1\|^2, \| e_{(k-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \\
         &\quad \| e_{(k'-1)p_1 + i}^{\top} \mathbf{V}_2 \|^2, \| e_{(i-1)p_2 + j}^{\top} \mathbf{V}_3 \|^2, \| e_{(i'-1)p_2 + j'}^{\top} \mathbf{V}_3 \|^2 \bigg\} \\
    &\gg \max\bigg\{ \frac{r^{3} \log(p)}{p^3} , \frac{r^{3} \log^{3/2}(p)}{(\lambda/\sigma)p^{3/2}}\bigg\},
    \end{align*}

Without loss of generality we assume that $\sigma^2 \equiv \sigma^2_{\min}$, since otherwise  we only increase the variance.  In addition, we assume that the core tensor $\mathcal{C} \in \mathbb{R}^{r_1 \times r_2 \times r_3}$ is known, since not knowing it will also only increase the variance. 

Next, by the Cramer-Rao lower bound, for any unbiased estimator $(\widetilde {\mathbf{U}}_1, \widetilde {\mathbf{U}}_2, \widetilde {\mathbf{U}}_3)$ of the parameter $({\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3)$, it holds that
\begin{align*}
    \mathrm{Var} (\widetilde {\mathbf{U}}_1, \widetilde {\mathbf{U}}_2, \widetilde {\mathbf{U}}_3) &\succcurlyeq \mathcal{I}^{-1},
\end{align*}
where $\mathcal{I}$ is defined via
\begin{align*}
    \mathcal{I} &\coloneqq \mathbb{E} \bigg[\nabla_{{\mathbf{U}}_1, {\mathbf{U}}_2,{\mathbf{U}}_3} \log \mathcal{L}(\mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3)\bigg] \bigg[ \nabla_{{\mathbf{U}}_1, {\mathbf{U}}_2,{\mathbf{U}}_3} \log \mathcal{L}(\mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3)\bigg]^{\top},
\end{align*}

By the delta method, for any unbiased estimator $\mathcal{\check T}_{ijk}$ of $\mathcal{T}_{ijk}$ it holds that
\begin{align*}
    \mathrm{Var}(\mathcal{\check T}_{ijk}) \geq \nabla_{{\mathbf{U}}_1,{\mathbf{U}}_2,{\mathbf{U}}_3} \mathcal{T}_{ijk}^{\top}  \mathcal{I}^{-1}\nabla_{{\mathbf{U}}_1,{\mathbf{U}}_2,{\mathbf{U}}_3} \mathcal{T}_{ijk}, 
\end{align*}
where $\nabla_{{\mathbf{U}}_1,{\mathbf{U}}_2,{\mathbf{U}}_3} \mathcal{T}_{ijk}$ is the gradient of $\mathcal{T}_{ijk}$ with respect to the (vectorized) parameter $({\mathbf{U}}_1, {\mathbf{U}}_2,{\mathbf{U}}_3)$.  
We now proceed in several steps. 
\begin{itemize}
    \item \textbf{Step 1: Calculating the Relevant Quantities}: 
 First, we note that
\begin{align}
    \frac{\partial \mathcal{T}_{ijk}}{\partial ({\mathbf{U}}_1)_{l_1,s}} &= \frac{\partial}{\partial ({\mathbf{U}}_1)_{l_1,s}} \sum_{a,b,c} \mathcal{C}_{abc} ({\mathbf{U}}_1)_{ia} ({\mathbf{U}}_2)_{jb} ({\mathbf{U}}_3)_{kc} \nonumber \\
    &= \mathbb{I}_{i = l_1} \sum_{b,c} \mathcal{C}_{sbc} ({\mathbf{U}}_2)_{jb} ({\mathbf{U}}_3)_{kc}. \label{eq:tijkpartial}
\end{align}
A similar calculation can be made for the other modes, with appropriate replacements.

We now calculate the Fisher information matrix.  To do so, we will use the convention that the vectorized matrices ${\mathbf{U}}_1, {\mathbf{U}}_2,$ and ${\mathbf{U}}_3$ are in the order such that they are first indexed by row then by column, which will be a useful convention later on. We note that
\begin{align*}
\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) &=\frac{-1}{2\sigma^2} \sum_{i_1,i_2,i_3} \bigg( \mathcal{\widehat T}_{i_1 i_2 i_3} - \sum_{a,b,c} \mathcal{C}_{abc} ({\mathbf{U}}_1)_{i_1 a} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c} \bigg)^2; 
\end{align*}
and hence that
\begin{align*}
    &\frac{\partial }{\partial ({\mathbf{U}}_1)_{l a'}}\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} )  \\
&= \frac{\partial }{\partial ({\mathbf{U}}_1)_{l a'}}\frac{-1}{2\sigma^2} \sum_{i_1,i_2,i_3} \bigg( \mathcal{\widehat T}_{i_1 i_2 i_3} - \sum_{a,b,c} \mathcal{C}_{abc} ({\mathbf{U}}_1)_{i_1 a} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c} \bigg)^2 \\

&= \frac{-1}{\sigma^2} \sum_{i_2,i_3} \bigg( \mathcal{\widehat T}_{l i_2 i_3} - \sum_{a,b,c} \mathcal{C}_{abc} ({\mathbf{U}}_1)_{l a} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg)\\
&\quad \times \frac{\partial}{\partial({\mathbf{U}}_1)_{la'}} \bigg( \mathcal{\widehat T}_{l i_2 i_3} - \sum_{a,b,c} \mathcal{C}_{abc} ({\mathbf{U}}_1)_{l a} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg)  \\
&= \frac{1}{\sigma^2} \sum_{i_2,i_3} \bigg( \mathcal{\widehat T}_{l i_2 i_3} - \sum_{a,b,c} \mathcal{C}_{abc} ({\mathbf{U}}_1)_{l a} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg)  \bigg( \sum_{b,c} \mathcal{C}_{a' bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg)  \\
&= \frac{1}{\sigma^2} \sum_{i_2, i_3} \mathcal{Z}_{l i_2 i_3}   \bigg( \sum_{b,c} \mathcal{C}_{a' bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg).
\end{align*}
Therefore,\begin{align}
\mathbb{E} &\Bigg[  \frac{\partial }{\partial ({\mathbf{U}}_1)_{l_1 a_1}}\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) \frac{\partial }{\partial ({\mathbf{U}}_1)_{l_2 a_2}}\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) \Bigg] \nonumber \\
&= \frac{1}{\sigma^4} \mathbb{E} \Bigg[ \sum_{i_2, i_3} \mathcal{Z}_{l_1 i_2 i_3}   \bigg( \sum_{b,c} \mathcal{C}_{a_1 bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg) \Bigg] \Bigg[  \sum_{i_2, i_3} \mathcal{Z}_{l_2 i_2 i_3}   \bigg( \sum_{b,c} \mathcal{C}_{a_2 bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c} \Bigg] \nonumber \\
&= \frac{1}{\sigma^2} \mathbb{I}_{l_1 = l_2}\sum_{i_2, i_3} \bigg( \sum_{b,c} \mathcal{C}_{a_1 bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg) \bigg(  \sum_{b,c} \mathcal{C}_{a_2 bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c} \bigg) \nonumber \\
&= \frac{1}{\sigma^2} \mathbb{I}_{l_1 = l_2}\sum_{b,c} \mathcal{C}_{a_1 bc} \mathcal{C}_{a_2 bc}\label{grammatrixidentity}
\end{align}
where the second inequality uses the independence of $\mathcal{Z}_{i_1i_2i_3}$, and the final inequality is by orthonormality.  Similarly,
\begin{align}
&\mathbb{E} \Bigg[  \frac{\partial }{\partial ({\mathbf{U}}_1)_{l_1 a_1}}\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) \frac{\partial }{\partial ({\mathbf{U}}_2)_{l_2 b_1}}\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) \Bigg] \nonumber \\
&=  \frac{1}{\sigma^4} \mathbb{E} \Bigg[ \sum_{i_2, i_3} \mathcal{Z}_{l_1 i_2 i_3}   \bigg( \sum_{b,c} \mathcal{C}_{a_1 bc} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3 )_{i_3 c}  \bigg) \Bigg]  \Bigg[  \sum_{i_1, i_3} \mathcal{Z}_{i_1 l_2 i_3}   \bigg( \sum_{a,c} \mathcal{C}_{a b_1 c} ({\mathbf{U}}_1)_{i_1 a} ({\mathbf{U}}_3 )_{i_3 c} \Bigg] \nonumber\\
&= \frac{1}{\sigma^2} \sum_{i_3} \bigg(\sum_{b,c} \mathcal{C}_{a_1 bc} ({\mathbf{U}}_2)_{l_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg) \bigg( \sum_{a,c} \mathcal{C}_{a b_1 c} ({\mathbf{U}}_1)_{l_1 a} ({\mathbf{U}}_3 )_{i_3 c} \bigg) \label{eq:Hidentity}
\end{align}
Similar derivations can be obtained for ${\mathbf{U}}_2$ and ${\mathbf{U}}_3$. 

Define the $r_1$ vectors $\{\mathbf{c}_{a_i}\}_{i=1}^{r_1} \in \mathbb{R}^{r_2 r_3}$ by setting its $(b,c)$ entry equal to $\mathcal{C}_{a_i bc}$, and define the $r_2$ and $r_3$ vectors $\{\mathbf{c}_{b_j}\}_{j=1}^{r_2}$ and $\{ \mathbf{c}_{c_k}\}_{k=1}^{r_3}$ similarly.  With this definition, we note that \eqref{grammatrixidentity} is simply the equation for the sample gram matrix for the $r_1$ vectors $\{\mathbf{c}_{a_i}\}_{i=1}^{r_1} \in \mathbb{R}^{r_2 r_3}$ (with similar observations for the other two modes).  Therefore, abusing notation slightly, let $\mathbf{I}_1 \in \mathbb{R}^{p_1 r_1 \times p_1 r_1}$ be the block-diagonal matrix with $r_1 \times r_1$ blocks   given by this sample gram matrix, and let $\mathbf{I}_2$ and $\mathbf{I}_3$ be defined similarly.  With these notations in place, we see that $\mathcal{I}$ can be written in the following form:
\begin{align*}
   \sigma^2 \mathcal{I} &= \begin{pmatrix}
    \mathbf{I}_1 & 0 &0 \\ 0 & \mathbf{I}_2 & 0 \\
    0 & 0 &\mathbf{I}_3
    \end{pmatrix} + \begin{pmatrix} 0 & \mathbf{H}_{12} & \mathbf{H}_{13} \\ \mathbf{H}_{12}^{\top} & 0 & \mathbf{H}_{23} \\ \mathbf{H}_{13}^{\top} & \mathbf{H}_{23}^{\top} & 0
    \end{pmatrix},
\end{align*}
where $\mathbf{H}_{12}, \mathbf{H}_{13}$ and $\mathbf{H}_{23}$ are of appropriate dimension with entries given by the identity in \eqref{eq:Hidentity}.  
\item 
\textbf{Step 2: Three Tensor Algebra Identities}: 
We now simplify the expressions in \eqref{eq:tijkpartial},
\eqref{grammatrixidentity} and \eqref{eq:Hidentity}.  
We recall from \eqref{eq:tijkpartial} that
\begin{align}
     \frac{\partial \mathcal{T}_{ijk}}{\partial ({\mathbf{U}}_1)_{i,s}} &= \sum_{b,c} \mathcal{C}_{sbc} ({\mathbf{U}}_2)_{jb} ({\mathbf{U}}_3)_{kc} \nonumber\\
     &= \sum_{b,c} \bigg( \sum_{i_1i_2i_3} \mathcal{T}_{i_1 i_2 i_3} ({\mathbf{U}}_1)_{i_1 s} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg) ({\mathbf{U}}_2)_{jb} ({\mathbf{U}}_3)_{kc} \nonumber\\
     &= \sum_{b,c} ({\mathbf{U}}_2)_{jb} ({\mathbf{U}}_3)_{kc} \bigg( \sum_{i_1} ({\mathbf{U}}_1)_{i_1 s} \sum_{i_2 i_3} \mathcal{T}_{i_1 i_2 i_3} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg)\nonumber \\
     &= \sum_{b,c} ({\mathbf{U}}_2)_{jb} ({\mathbf{U}}_3)_{kc} \bigg( {\mathbf{U}}_1^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3) \bigg)_{s, (b,c)} \nonumber\\
     &= \Bigg[ {\mathbf{U}}_1^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3) ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)^{\top}\Bigg]_{s,(j-1)p_3 + k} \nonumber\\
     &= \Bigg[ {\mathbf{U}}_1^{\top} {\mathbf{U}}_1 \mathbf{\Lambda}_1 \mathbf{V}_1 \mathcal{P}_{{\mathbf{U}}_1 \otimes {\mathbf{U}}_2} \Bigg]_{s,(j-1)p_3 +k} \nonumber \\
     &= \bigg( \mathbf{\Lambda}_1 \mathbf{V}_1^{\top} \bigg)_{s,(j-1)p_3 +k}. \label{tijkpartial2}
\end{align}
Here we have denoted the index $(b,c)$ to be the matricization index corresponding to the $s,b,c$ element of the underlying tensor.

We now consider the form of the blocks in the definition of $\mathbf{I}_1$.  Recall that each block is given by the matrix whose $(a_1, a_2)$ entry is equal to
\begin{align*}
    \sum_{b,c} \mathcal{C}_{a_1 bc} \mathcal{C}_{a_2bc}.
\end{align*}
We have that
\begin{align*}
     &\sum_{b,c} \mathcal{C}_{a_1 bc} \mathcal{C}_{a_2bc} \\
     &= \sum_{b,c} \bigg(  \sum_{i_1,i_2,i_3}  \mathcal{T}_{i_1 i_2 i_3} ({\mathbf{U}}_1)_{i_1 a_1} ({\mathbf{U}}_2)_{i_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg)\bigg(  \sum_{j_1,j_2,j_3}  \mathcal{T}_{j_1 j_2 j_3} ({\mathbf{U}}_1)_{j_1 a_2} ({\mathbf{U}}_2)_{j_2 b} ({\mathbf{U}}_3)_{j_3 c} \bigg) \\
     &= \sum_{b,c}\sum_{i_1, i_2,i_3} \mathcal{T}_{i_1i_2i_3} ({\mathbf{U}}_1)_{i_1 a_1} ({\mathbf{U}}_2 )_{i_2 b} ({\mathbf{U}}_3 )_{i_3}\bigg[ \sum_{j_1} ({\mathbf{U}}_1)_{j_1 a_2} \sum_{j_2 j_3} \mathcal{T}_{j_1 j_2 j_3} ({\mathbf{U}}_2)_{j_2b} ({\mathbf{U}}_3)_{j_3 c} \bigg] \\
     &= \sum_{b,c}\sum_{i_1, i_2,i_3} \mathcal{T}_{i_1i_2i_3} ({\mathbf{U}}_1)_{i_1 a_1} ({\mathbf{U}}_2 )_{i_2 b} ({\mathbf{U}}_3 )_{i_3} \bigg[ \sum_{j_1} ({\mathbf{U}}_1)_{j_1 a_2} \bigg( \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3 ) \bigg)_{j_1,(b,c)} \bigg] \\
     &= \sum_{b,c}\sum_{i_1, i_2,i_3} \mathcal{T}_{i_1i_2i_3} ({\mathbf{U}}_1)_{i_1 a_1} ({\mathbf{U}}_2 )_{i_2 b} ({\mathbf{U}}_3 )_{i_3} \bigg( {\mathbf{U}}_1 ^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)\bigg)_{a_2, (b,c)} \\
     &=\sum_{b,c} \bigg( {\mathbf{U}}_1 ^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)\bigg)_{a_2, (b,c)} \sum_{i_1, i_2,i_3} \mathcal{T}_{i_1i_2i_3} ({\mathbf{U}}_1)_{i_1 a_1} ({\mathbf{U}}_2 )_{i_2 b} ({\mathbf{U}}_3 )_{i_3} \\
    &=\sum_{b,c} \bigg( {\mathbf{U}}_1 ^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)\bigg)_{a_2, (b,c)} \bigg( {\mathbf{U}}_1^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3) \bigg)_{a_1, (b,c)} \\
    &= \bigg({\mathbf{U}}_1^{\top} \mathbf{T}_1 ( {\mathbf{U}}_2 \otimes {\mathbf{U}}_3 ) ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)^{\top} \mathbf{T}_1^{\top} {\mathbf{U}}_1 \bigg)_{a_1a_2} \\
    &= \bigg( {\mathbf{U}}_1^{\top} {\mathbf{U}}_1 \mathbf{\Lambda}_1 \mathbf{V}_1 \mathcal{P}_{{\mathbf{U}}_2 \otimes {\mathbf{U}}_3} \mathbf{V}_1^{\top} \mathbf{\Lambda}_1 {\mathbf{U}}_1^{\top} {\mathbf{U}}_1 \bigg)_{a_1 a_2} \\
    &= (\mathbf{\Lambda}_1^2)_{a_1 a_2},
\end{align*}
where we have used the fact that $\mathbf{T}_1 \mathcal{P}_{{\mathbf{U}}_2 \otimes {\mathbf{U}}_3} = \mathbf{T}_1$ and the fact that $\mathcal{P}_{{\mathbf{U}}_2 \otimes {\mathbf{U}}_3} = ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3) ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)^{\top}$.  This calculation reveals that $\mathbf{I}_1$ is simply a diagonal matrix with repeated diagonal blocks of $\mathbf{\Lambda}_1^2$, with a similar observation holding for $\mathbf{I}_2$ and $\mathbf{I}_3$, with diagonal blocks equal to $\mathbf{\Lambda}_2^2$ and $\mathbf{\Lambda}_3^2$ respectively.

Finally, we note that from \eqref{eq:Hidentity} that
\begin{align*}
\sigma^2 \mathbb{E} \Bigg[  \frac{\partial }{\partial ({\mathbf{U}}_1)_{l_1 a_1}}&\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) \frac{\partial }{\partial ({\mathbf{U}}_1)_{l_2 a_2}}\log f( \mathcal{\widehat T}; {\mathbf{U}}_1, {\mathbf{U}}_2, {\mathbf{U}}_3, \mathcal{C} ) \Bigg] \\
&=  \sum_{i_3} \bigg(\sum_{b,c} \mathcal{C}_{a_1 bc} ({\mathbf{U}}_2)_{l_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg) \bigg( \sum_{a,c} \mathcal{C}_{a b_1 c} ({\mathbf{U}}_1)_{l_1 a} ({\mathbf{U}}_3 )_{i_3 c} \bigg).
\end{align*}
Note that
\begin{align*}
    \sum_{b,c} \mathcal{C}_{a_1bc} ({\mathbf{U}}_2)_{l_2 b} ({\mathbf{U}}_3)_{i_3 c} 
    &= \sum_{b,c} ({\mathbf{U}}_2)_{l_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg( \sum_{j_1j_2j_3} \mathcal{T}_{j_1j_2j_3} ({\mathbf{U}}_1)_{j_1a_1} ({\mathbf{U}}_2)_{j_2 b} ({\mathbf{U}}_3)_{j_3c} \bigg) \\
    &= \sum_{b,c} ({\mathbf{U}}_2)_{l_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg( {\mathbf{U}}_1^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)\bigg)_{a_1,(b,c)} \\
    &= \bigg( {\mathbf{U}}_1^{\top} \mathbf{T}_1 ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3) ({\mathbf{U}}_2 \otimes {\mathbf{U}}_3)^{\top} \bigg)_{a_1,(l_2,i_3)} \\
    &= \bigg( \mathbf{\Lambda}_1 \mathbf{V}_1^{\top} \bigg)_{a_1,(l_2,i_3)} \\
    &= (\mathbf{\Lambda}_1)_{a_1} \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, a_1}.
\end{align*}
By a similar argument,
\begin{align*}
    \bigg( \sum_{a,c} \mathcal{C}_{a b_1 c} ({\mathbf{U}}_1)_{l_1 a} ({\mathbf{U}}_3 )_{i_3 c} \bigg) &= (\mathbf{\Lambda}_2)_{b_1} \big( \mathbf{V}_2 \big)_{(l_1 - 1)p_2 + i_3}.
\end{align*}
Therefore,
\begin{align}
    \sum_{i_3} &\bigg(\sum_{b,c} \mathcal{C}_{a_1 bc} ({\mathbf{U}}_2)_{l_2 b} ({\mathbf{U}}_3)_{i_3 c} \bigg) \bigg( \sum_{a,c} \mathcal{C}_{a b_1 c} ({\mathbf{U}}_1)_{l_1 a} ({\mathbf{U}}_3 )_{i_3 c} \bigg) \nonumber \\
    &= \sum_{i_3}(\mathbf{\Lambda}_2)_{b_1} \big( \mathbf{V}_2 \big)_{(l_1 - 1)p_2 + i_3}(\mathbf{\Lambda}_1)_{a_1} \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, a_1}, \label{hdef}
\end{align}
with appropriate replacements for different modes. 
\item \textbf{Step 3: Inverting the Fisher Information Matrix}:
Recall that we have that
\begin{align*}
    \sigma^2 \mathcal{I} &= \begin{pmatrix} \mathbf{I}_1 & 0 & 0 \\ 0 &\mathbf{I}_2 & 0 \\ 0 & 0 &\mathbf{I}_3 \end{pmatrix} + \begin{pmatrix} 0 & \mathbf{H}_{12} & \mathbf{H}_{13} \\ \mathbf{H}_{12}^{\top} & 0 & \mathbf{H}_{23} \\ \mathbf{H}_{13}^{\top} & \mathbf{H}_{23}^{\top} & 0
    \end{pmatrix} \\
    &\coloneqq \mathcal{\widetilde I} + \mathcal{H}.
\end{align*}
It is straightforward to observe that the matrix $ \mathcal{\widetilde I}$ is invertible since it is a diagonal matrix with positive elements.  We note also that
\begin{align*}
\| \mathcal{H} \|&= \Bigg\| \begin{pmatrix} 0 & \mathbf{H}_{12} & \mathbf{H}_{13} \\ \mathbf{H}_{12}^{\top} & 0 & \mathbf{H}_{23} \\ \mathbf{H}_{13}^{\top} & \mathbf{H}_{23}^{\top} & 0
    \end{pmatrix}\Bigg\| \\
    &\leq 3 \max_{jk} \| \mathbf{H}_{jk} \|
\end{align*}
We calculate the maximum spectral norm of each block.  Note that by \eqref{hdef},
\begin{align*}
\|    \mathbf{H}_{12}  \| &\leq \| \mathbf{H}_{12} \|_F \\
&\leq \Bigg[ \sum_{l_1,l_2,a_1,b_1} \bigg( \sum_{i_3}(\mathbf{\Lambda}_2)_{b_1} \big( \mathbf{V}_2 \big)_{(l_1 - 1)p_2 + i_3}(\mathbf{\Lambda}_1)_{a_1} \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, a_1} \bigg)^2 \Bigg]^{1/2} \\
&\leq \Bigg[ \sum_{l_1,l_2,a_1,b_1,i_3} \bigg( (\mathbf{\Lambda}_2)_{b_1} \big( \mathbf{V}_2 \big)_{(l_1 - 1)p_2 + i_3} \bigg)^2 \bigg( (\mathbf{\Lambda}_1)_{a_1} \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, a_1}  \bigg)^2 \Bigg]^{1/2} \\
&\leq \kappa^2 \lambda^2 \Bigg[ \sum_{l_1,l_2,i_3} \| \big( \mathbf{V}_2 \big)_{(l_1 - 1)p_2 + i_3,\cdot} \|^2 \| \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, \cdot} \|^2 \Bigg]^{1/2} \\
&\leq \kappa^2 \lambda^2 \Bigg[ \frac{\mu_0^2 r}{p_2p_3} \sum_{l_1,l_2,i_3}  \| \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, \cdot} \|^2 \Bigg]^{1/2} \\
&\leq \kappa^2 \lambda^2 \Bigg[ \frac{C \mu_0^2 r}{p} \sum_{l_2,i_3}\| \big( \mathbf{V}_1\big)_{(l_2-1)p_3 + i_3, \cdot} \|^2  \Bigg]^{1/2} \\
&\leq \kappa^2 \lambda^2 \big( \frac{C \mu_0^2 r}{p} \big) \\
&\lesssim \kappa^2 \lambda^2 \mu_0 \sqrt{\frac{r}{p}}.
\end{align*}
Therefore, applying this argument to each block, we obtain
\begin{align*}
    \| \mathcal{H} \| &\lesssim \kappa^2 \lambda^2 \mu_0 \sqrt{\frac{r}{p}}.
\end{align*}
Therefore,
\begin{align*}
    \| \mathcal{\widetilde I}^{-1} \mathcal{H} \| &\leq \| \mathcal{\widetilde I}^{-1} \| \|\mathcal{H} \| \\
    &\leq \frac{1}{\lambda^2} \|\mathcal{H} \| \\
    &\lesssim \kappa^2 \mu_0 \sqrt{\frac{r}{p}} \\
    &\ll 1,
\end{align*}
provided that $\kappa^2  \mu_0 \sqrt{\frac{r}{p}} \ll 1$.

Therefore, the following series expansion is justified:
\begin{align*}
    (\sigma^2\mathcal{I})^{-1} &= \bigg( \mathcal{I} + \mathcal{H}\bigg)^{-1} \\
    &= \Bigg[ \mathcal{\widetilde I} \bigg( \mathbf{I}_{p_1p_2p_3r_1r_2r_3} + \mathcal{\widetilde I}^{-1} \mathcal{H} \bigg) \Bigg]^{-1} \\
    &= \bigg(  \mathbf{I}_{p_1p_2p_3r_1r_2r_3} + \mathcal{\widetilde I}^{-1} \mathcal{H} \bigg)^{-1} \mathcal{\widetilde I}^{-1} \\
    &= \sum_{k=0}^{\infty} \big(  \mathcal{\widetilde I}^{-1} \mathcal{H} \big)^k,
\end{align*}
and hence that
\begin{align*}
    \mathcal{I}^{-1} &= \sigma^2 \sum_{k=0}^{\infty} \big(  \mathcal{\widetilde I}^{-1} \mathcal{H} \big)^k \mathcal{\widetilde I}^{-1} \\
    &= \sigma^2  \mathcal{\widetilde I}^{-1} + \sigma^2 \sum_{k=1}^{\infty} \big(  \mathcal{\widetilde I}^{-1} \mathcal{H} \big)^k \mathcal{\widetilde I}^{-1} \\
    &= \sigma^2 (1 - o(1)) \mathcal{\widetilde I}^{-1},
\end{align*}
where the $o(1)$ is taken to be with respect to the positive semidefinite ordering. 
\item 
\textbf{Step 4: Putting It All Together}: First we prove \cref{thm:efficiencyloadings}.   It is immediate that the $m$'th row of any estimator $\mathbf{\widetilde U}_k$ of ${\mathbf{U}}_k$ has covariance lower bounded by the $r_k \times r_k$ submatrix of $\mathcal{I}^{-1}$.  Therefore,
\begin{align*}
    \mathrm{Var}( e_m^{\top} \mathbf{\widetilde{U}}_k ) &\succcurlyeq \big(\mathcal{I}^{-1}\big)_{r_k: r_k} \\
    &\succcurlyeq \sigma^2 (1 - o(1)) \big(\mathcal{\widetilde I}^{-1}\big)_{r_k: r_k} \\
    &\succcurlyeq \sigma^2 (1- o(1)) \mathbf{\Lambda}_k^{-2},
\end{align*}
since the $r_k \times r_k$ submatrix of $\mathcal{\widetilde I}^{-1}$ corresponding to the $m$'th row of ${\mathbf{U}}_k$ is simply $\mathbf{\Lambda}_k^{-2}$.  This completes the proof of \cref{thm:efficiencyloadings}.

