 \end{align*}
 is only nonzero in indices corresponding to rows $i$ $j$ or $k$.  Each of these is then scaled by the diagonal matrix $\mathbf{\Lambda}_1^{-2}$, $\mathbf{\Lambda}_2^{-2}$, or $\mathbf{\Lambda}_3^{-3}$ respectively. 
 Therefore, 
\begin{align*}
   & \big(  \nabla_{{\mathbf{U}}_1,{\mathbf{U}}_2,{\mathbf{U}}_3} \mathcal{T}_{ijk} \big)^{\top} \mathcal{ I}^{-1} \big(  \nabla_{{\mathbf{U}}_1,{\mathbf{U}}_2,{\mathbf{U}}_3} \mathcal{T}_{ijk} \big) \\
    &= (1- o(1))\sigma^2 \sum_{s_1,s_2} (\mathbf{\Lambda}_1 \mathbf{V}_1^{\top} )_{s_1,(j-1)p_3 + k} (\mathbf{\Lambda}_1)^{-2}_{s_1 s_2} (\mathbf{\Lambda}_1 \mathbf{V}_1^{\top} )_{s_2,(j-1)p_3 + k} \\
