    &\quad + (1- o(1))\sigma^2\sum_{s_1, s_2} (\mathbf{\Lambda}_3 \mathbf{V}_3^{\top} )_{s_1,(i-1)p_2 + j} (\mathbf{\Lambda}_3)^{-2}_{s_1 s_2} (\mathbf{\Lambda}_3 \mathbf{V}_3^{\top} )_{s_2,(i-1)p_2 + j} \\ 
    &= (1- o(1))\sigma^2\sum_{s_1} (\mathbf{\Lambda}_1 \mathbf{V}_1^{\top} )_{s_1,(j-1)p_3 + k} (\mathbf{\Lambda}_1)^{-2}_{s_1 s_1} (\mathbf{\Lambda}_1 \mathbf{V}_1^{\top} )_{s_2,(j-1)p_3 + k} \\
    &\quad +(1- o(1))\sigma^2 \sum_{s_1} (\mathbf{\Lambda}_2 \mathbf{V}_2^{\top} )_{s_1,(k-1)p_1 + i} (\mathbf{\Lambda}_2)^{-2}_{s_1 s_1} (\mathbf{\Lambda}_2 \mathbf{V}_2^{\top} )_{s_1,(k-1)p_1 + i} \\
    &\quad + (1- o(1))\sigma^2\sum_{s_1} (\mathbf{\Lambda}_3 \mathbf{V}_3^{\top} )_{s_1,(i-1)p_2 + j} (\mathbf{\Lambda}_3)^{-2}_{s_1 s_1} (\mathbf{\Lambda}_3 \mathbf{V}_3^{\top} )_{s_2,(i-1)p_2 + j} \\ 
    &= (1- o(1))\sigma^2\sum_{s_1} ( \mathbf{V}_1^{\top} )_{s_1,(j-1)p_3 + k}^2 \\
    &\quad + (1- o(1))\sigma^2\sum_{s_1} ( \mathbf{V}_2^{\top} )_{s_1,(k-1)p_1 + i}^2 \\
    &\quad + (1- o(1))\sigma^2\sum_{s_1} ( \mathbf{V}_3^{\top} )_{s_1,(i-1)p_2 + j}^2 \\ 
    &=(1- o(1))\sigma^2 \bigg( \| e_{(j-1)p_3 + k} \mathbf{V}_1 \|^2 + \| e_{(k-1)p_2 + j} \mathbf{V}_2 \|^2 + \| e_{(i-1)p_2 + j} \mathbf{V}_3 \|^2\bigg).
\end{align*}
This completes the proof of \cref{thm:efficiency}.
\end{itemize}

