\begin{align*}
&\inf_{\mathrm{C.I.}_{k,m}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) \in \mathcal{I}_{\alpha}(\Theta,\xi)} \sup_{\mathcal{T} \in \Theta} \mathbb{E}_{\mathcal{T}} L\big( \mathrm{C.I.}_{k,m}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) \big) \\ &\geq \inf_{\mathrm{C.I.}_{k,m}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) \in \mathcal{I}_{\alpha}(\Theta,\xi)} \sup_{\mathcal{T} \in \Theta_0 \cup \Theta_1} \mathbb{E}_{\mathcal{T}} L\big( \mathrm{C.I.}_{k,m}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) \big) \\
