\end{align*}
where $\mathrm{TV}(\cdot)$ denotes the total variation distance, and $f_{\pi_{\mathcal{H}_i}}$ denotes the density function with the prior $\pi_{\mathcal{H}_i}$ on $\mathcal{H}_i$. We note that
\begin{align*}
    \mathrm{TV}(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}} ) &\leq \sqrt{\chi^2(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}})}, 
\end{align*}
where
\begin{align*}
    \chi^2(f_1,f_0) &= \int \frac{f_1^2(z)}{f_0(z)} dz- 1.
\end{align*}
We will upper bound $\chi^2(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}})$ and lower bound  $\big| \xi^{\top} \big( \mathbf{U}_1 - \mathbf{\bar U}_1 \big)_{1\cdot} \big|$.  


First we describe our construction.  For a given $\mathbf{U}_1$, let $\mathbf{U'}_1$ be defined as follows. Let $\mathbf{v}$ denote the vector
\begin{align*}
    \mathbf{v} := \frac{1}{\| ({\mathbf{U}}_1)_{\cdot r_1} + \delta (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1\| } \bigg( ({\mathbf{U}}_1)_{\cdot r_1} + \delta (\mathbf{I} - {\mathbf{U}}_{1} {\mathbf{U}}_{1}^{\top} ) e_1 \bigg),
\end{align*}
where we will choose $\delta$ later. We set $\mathbf{\bar U}_1$ to have the first $r_1 - 1$ columns equal to ${\mathbf{U}}_1$, and we let its $r_1$'th column equal $\mathbf{v}$.  The proof proceeds in steps: first we demonstrate that $\mathcal{\bar T} \in \Theta(\lambda,\kappa,\mu_0,\sigma,\sigma_{\min})$, after which we upper bound the $\chi^2$ distance, and finally we lower bound the difference $\big|\xi^{\top}\big( {\mathbf{U}}_1 - \mathbf{\bar U}_1\big)_{1\cdot} \big|$.

\begin{itemize}
    \item \textbf{Step 1: Showing $\mathcal{\bar T} \in \Theta(\lambda,\kappa,\mu_0,\sigma,\sigma_{\min}).$} It is clear that the singular values and the singular vectors ${\mathbf{U}}_2$ and ${\mathbf{U}}_3$ of $\mathcal{\bar T}$ remain unchanged; consequently, we need only demonstrate that $ \|\mathbf{\bar U}_1\|_{2,\infty} \leq \mu_0 \sqrt{\frac{r_1}{p_1}}$. Therefore, it suffices to demonstrate that $\|\mathbf{v} \|_{\infty} \leq \mu_0 \sqrt{\frac{1}{p_1}}$. First, note that \begin{align*}
    \|  ({\mathbf{U}}_1)_{\cdot r_1} + \delta ((\mathbf{I} - {\mathbf{U}}_{1} {\mathbf{U}}_{1}^{\top} )) e_1 \| = \sqrt{1 + \delta^2 \| ((\mathbf{I} - {\mathbf{U}}_{1} {\mathbf{U}}_{1}^{\top} ) ) e_1 \|^2}.
\end{align*}
Consequently,
\begin{align*}
    \| \mathbf{v} \|_{\infty} &\leq \| ({\mathbf{U}}_1)_{\cdot r_1} - \mathbf{v} \|_{\infty} + \|({\mathbf{U}}_1)_{\cdot r_1} \|_{\infty} \\
    &\leq \bigg\| \big(\mathbf{U}_1\big)_{\cdot r_1} - \frac{({\mathbf{U}}_1)_{\cdot r_1} + \delta (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1 \|^2}} \bigg\| + \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} \\
    &\leq \bigg\| \big( {\mathbf{U}}_1 \big)_{\cdot r_1} + \delta \big( \mathbf{I} - {\mathbf{U}}_1  {\mathbf{U}}_1^{\top} \big) e_1 \bigg\|_{\infty} \bigg| 1 - \frac{1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1{\mathbf{U}}_1^{\top}) e_1\|^2}} \bigg| + \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} \\
    &\leq \bigg( \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} + \delta \bigg) \bigg| 1 - \frac{1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1{\mathbf{U}}_1^{\top}) e_1\|^2}} \bigg|+ \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} \\
    &\leq \delta \bigg( \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} + \delta \bigg) +  \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}}.
\end{align*}
Therefore, $\|\mathbf{v} \|_{\infty} \leq \mu_0 \sqrt{\frac{1}{p_1}}$ as long as 
\begin{align*}
    \delta \bigg( \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} + \delta \bigg) \leq \frac{\mu_0}{2}  \sqrt{\frac{1}{p_1}}. \addtocounter{equation}{1}\tag{\theequation} \label{eq:choosedelta}
\end{align*}
We will check this upon choosing $\delta$.
    \item \textbf{Step 2: Upper bounding $\chi^2(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}})$}. Under Gaussian noise, we have that
\begin{align*}
    \chi^2(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}}) + 1 &= \exp\bigg( \sum_{i,j,k} \frac{(\mathcal{\bar T}_{ijk} - \mathcal{T}_{ijk})^2}{\sigma^2_{ijk}} \bigg) \\
    &\leq \exp\bigg(  \| \mathcal{\bar T} - \mathcal{T} \|_F^2 \bigg) \\
    &\leq \exp\bigg( \|(\mathbf{\bar U}_1 - {\mathbf{U}}_1) \mathbf{\Lambda}_1 \mathbf{V}_1^{\top} \|_F^2 \bigg) \\
    &\leq \exp\bigg( \|(\mathbf{\bar U}_1 - {\mathbf{U}}_1) \mathbf{\Lambda}_1  \|_F^2 \bigg) \\
    &\leq \exp\bigg( \lambda_{r_1}^2 \|({\mathbf{U}}_1)_{\cdot r_1} - \mathbf{v} \|^2 \bigg),
\end{align*}
where we have used the assumption $\sigma_{\min} = 1$. 
We now bound the quantity inside the exponential. Observe that
\begin{align*}
    \| \big(\mathbf{U}_1\big)_{\cdot r_1} - \mathbf{v} \| &= \bigg\| \big(\mathbf{U}_1\big)_{\cdot r_1} - \frac{({\mathbf{U}}_1)_{\cdot r_1} + \delta (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1 \|^2}} \bigg\| \\
    &\leq \delta \bigg\|\bigg( \mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \bigg) e_1 \bigg\| \\
    &\quad + \bigg( 1 - \frac{1}{\sqrt{1 + \delta^2 \|(\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1\|}} \bigg) \| ({\mathbf{U}}_{1})_{\cdot r_1} + \delta (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1 \| \\
    &\leq \delta  + \frac{\sqrt{1 + \delta^2\|(\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )e_i\|} - 1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top})e_1 \|^2}} (1 + \delta)  \\
    &\leq 3\delta ,
\end{align*}
where the final inequality holds as long as $\delta \leq \frac{1}{12}$.  Therefore,
\begin{align*}
\chi^2(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}}) &\leq \exp\bigg( 9\lambda_{r_1}^2 \delta^2 \bigg) - 1.
\end{align*}
\item \textbf{Step 3: Lower bounding $\xi^{\top} (\mathbf{\bar U}_1 - {\mathbf{U}}_1 \big)_{1\cdot}$. } 
Without loss of generality assume that $({\mathbf{U}}_1)_{1 r_1}$ is nonnegative.  Observe that
\begin{align*}
    |\xi^{\top}& (\mathbf{\bar U}_1 - {\mathbf{U}}_1 \big)_{1\cdot}|\\ &= |\xi_{r_1}| \bigg| (\mathbf{\bar U}_1 - {\mathbf{U}}_1)_{1r_1} \bigg| \\
    &\geq C \| \xi\|_{\infty} \bigg| (\mathbf{\bar U}_1 - {\mathbf{U}}_1)_{1r_1} \bigg| \\
    &\geq C\|\xi\|_{\infty} \bigg| \mathbf{v}_{11} - \big({\mathbf{U}}_1)_{1r_1} \bigg| \\
    &= C \bigg|\frac{1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1 \|^2}}\bigg( ({\mathbf{U}}_1)_{1 r_1} + \delta (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )_{11} \bigg) - \big({\mathbf{U}}_1)_{1r_1} \bigg| \\
    &\geq C\Bigg( \frac{\delta \| |(\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )_{11} \|}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) e_1 \|^2}} - ({\mathbf{U}}_1)_{11} \bigg( 1 - \frac{1}{\sqrt{1 + \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} ) _{11} \|^2}} \bigg) \Bigg) \\
    &\geq C \bigg( \frac{1}{2} \delta \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )_{11} \| - |({\mathbf{U}}_1)_{11}| \delta^2 \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )_{11} \|  \bigg) ^{\top} \\
    &\geq \frac{C \delta}{4 } \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )_{11} \|.
\end{align*}
The incoherence assumption implies that
\begin{align*}
    \| {\mathbf{U}}_1 \|_{2,\infty} \leq \frac{\mu_0}{2} \sqrt{\frac{r_1}{p_1}} \leq \frac{1}{2}
\end{align*}
and hence
\begin{align*}
    \| (\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )_{11} \| \geq \frac{1}{2}.
\end{align*}
Therefore,
\begin{align*}
     |\xi^{\top} (\mathbf{\bar U}_1 - {\mathbf{U}}_1 \big)_{1\cdot}| &\geq \frac{C \delta}{8 }.
     \end{align*}
\item   \textbf{Completing the proof}.     Combining all of our bounds, we obtain that
    \begin{align*}
    \inf \sup    \mathbb{E}  L\big( \mathrm{C.I.}_{1,1}^{\alpha}(\xi,\mathcal{Z},\mathcal{T}) &\geq \big| \xi^{\top} \big( \mathbf{U}_1 - \mathbf{\bar U}_1 \big)_{1\cdot} \big| \big( 1 - 2\alpha - \mathrm{TV}(f_{\pi_{\mathcal{H}_1}}, f_{\pi_{\mathcal{H}_0}} ) \big) \\
        &\geq \frac{C\delta}{9 } \bigg( 1 - 2\alpha - \sqrt{\exp\bigg(9 \lambda_{r_1}^2\delta^2\bigg) - 1} \bigg).
    \end{align*}
    By taking $\delta = \frac{\varepsilon}{\lambda_{r_1}}$ for some sufficiently small constant $\varepsilon$, we complete the proof, provided we can justify \eqref{eq:choosedelta}.  However, with this choice of $\delta$, it holds that
    \begin{align*}
       \delta \bigg( \frac{\mu_0}{2}\sqrt{\frac{1}{p_1}} + \delta \bigg) &= \frac{\varepsilon}{\lambda_{r_k}} \bigg( \frac{\mu_0}{2}\sqrt{\frac{1}{p_1}} +  \frac{\varepsilon}{\lambda_{r_k}}\bigg) \\
       &\leq  \frac{\varepsilon}{\lambda} \bigg( \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} + \frac{\varepsilon}{\lambda} \bigg) \\
       &\leq \frac{\varepsilon}{\lambda/\sigma}  \bigg( \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} + \frac{\varepsilon}{\lambda/\sigma} \bigg) \\
       &\leq \frac{\varepsilon}{C_0 \sqrt{p_1}} \bigg( \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}} + \frac{\varepsilon}{C_0 \sqrt{p_1}} \bigg) \\
       &\leq \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}}  \frac{\varepsilon}{C_0 \sqrt{p_1}} \bigg( 1 + \frac{2 \varepsilon}{\mu_0 C_0} \bigg) \\
       &\leq \frac{\mu_0}{2} \sqrt{\frac{1}{p_1}},
    \end{align*}
    where we have used the assumption that $\lambda/\sigma \geq C_0 \sqrt{p_{\max}}$ together with the fact that $\sigma \geq 1$ from the fact that $\sigma_{\min} = 1$.  

\end{itemize}
This completes the proof.

The proof is similar to the previous proof, only we generalize our construction slightly.  Without loss of generality we consider $i = j = k = 1$.  First let $\mathcal{T} = \mathcal{C} \times_1 {\mathbf{U}}_1 \times_2 {\mathbf{U}}_2 \times_3 {\mathbf{U}}_3$ be such that $\| {\mathbf{U}}_k \|_{\infty} \leq \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}}$ for each $k$ which is permitted since $\mu_0 > 2$.  Let $\mathcal{T}$ also satisfy 
\begin{align*}
    \sqrt{\| e_1^{\top} \mathbf{V}_1 \|^2 + \|e_1^{\top} \mathbf{V}_2 \|^2 + \| e_1^{\top} \mathbf{V}_3 \|^2} \geq C \mu_0 \frac{r_{\max}^{3/2}\kappa}{\lambda \sqrt{p_{\min}}},
\end{align*}
which is possible whenever $\lambda \geq C_0 \sqrt{p} r \kappa$, which holds under our assumptions on the class $\Theta(\lambda,\kappa,\mu_0,\sigma,\sigma_{\min})$. Define
\begin{align*}
    \mathbf{\bar U}_k = \bigg( {\mathbf{U}}_k + ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k \bigg) \Bigg[\bigg( {\mathbf{U}}_k + ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k \bigg)^{\top} \bigg( {\mathbf{U}}_k + ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k \bigg)  \Bigg]^{-1/2},
\end{align*}
where $\Delta_k$ is the $p_k \times r_k$ matrix whose first row has $l$'th entry equal to $\pm\frac{\varepsilon}{\lambda_l}$ for some constant $\varepsilon$ to be determined later, and whose sign will be chosen later. Define
\begin{align*}
    \mathcal{\bar T} := \mathcal{C} \times_1 \mathbf{\bar U}_1 \times_2 \mathbf{\bar U}_2 \times_3 \mathbf{\bar U}_3.
\end{align*}
 By Lemma 1 of \cite{cai_confidence_2017}, we have that
\begin{align*}
 & \inf_{\mathrm{C.I.}^{\alpha}_{111}(\mathcal{Z},\mathcal{T}) \in \mathcal{I}_{\alpha}(\Theta,\{1,1,1\}} \sup_{\mathcal{T} \in \Theta(\lambda,\kappa,\mu_0)} \mathbb{E}_{\mathcal{T}} L\big( \mathrm{C.I.}_{111}^{\alpha}(\mathcal{Z},\mathcal{T}) \big) \\&\geq | \mathcal{T}_{ijk} - \mathcal{\bar T}_{ijk}| \big( 1 - 2 \alpha - \sqrt{\chi^2(f_{\pi_{\mathcal{H}_1}},f_{\pi_{{\mathcal{H}_0}}}) } \big).
\end{align*}
Similar to the previous proof, we proceed in steps.
\begin{itemize}
    \item \textbf{Step 1: Checking that $\mathcal{\bar T} \in \Theta(\lambda,\kappa,\mu_0)$}. It is evident that $\lambda \leq \lambda_{\min}(\mathcal{\bar T}) \leq \lambda_{\max}(\mathcal{\bar T}) \leq \kappa \lambda$.  Therefore, it suffices to demonstrate that $\|\mathbf{\bar U}_k \|_{2,\infty} \leq \mu_0 \sqrt{\frac{r_k}{p_k}}$.  Observe that
    \begin{align*}
        \mathbf{\bar U}_k &= {\mathbf{U}}_k + \big( {\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}\big) \Delta_k + \bigg( {\mathbf{U}}_k + \big( {\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}\big) \Delta_k \bigg) \bigg( \mathbf{C}_{\Delta_k}^{-1/2} - \mathbf{I} \bigg), \addtocounter{equation}{1}\tag{\theequation} \label{ukbarexpression}
    \end{align*}
    where we have defined $\mathbf{C}_{\Delta_k}$ via
    \begin{align*}
        \mathbf{C}_{\Delta_k} &:= \bigg( {\mathbf{U}}_k + \big( {\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} \big) \Delta_k \bigg)^{\top} \bigg( {\mathbf{U}}_k + \big( {\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} \big) \Delta_k \bigg)\\
        &\equiv \mathbf{I} + \Delta_k^{\top}  \big( {\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} \big) \Delta_k,
    \end{align*}
    which is positive definite as long as $\|\Delta_k^{\top} ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k\| < 1,$ which we will demonstrate momentarily.      Therefore,
    \begin{align*}
        \| \mathbf{\bar U}_k \|_{2,\infty} &\leq \| {\mathbf{U}}_k \|_{2,\infty} + \| ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k \|_{2,\infty} \\
        &\quad + \bigg( \| {\mathbf{U}}_k \|_{2,\infty} + \| ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k \|_{2,\infty} \bigg) \bigg\| \mathbf{C}_{\Delta_k}^{-1/2} - \mathbf{I} \bigg\|. \addtocounter{equation}{1}\tag{\theequation} \label{incoherence}
    \end{align*}
    Therefore, it suffices to bound the quantities $\|({\mathbf{I}} - {\mathbf{U}}_k{\mathbf{U}}_k^{\top})\Delta_k \|_{2,\infty}$ and $\|\mathbf{C}_{\Delta_k}^{-1/2} - {\mathbf{I}} \|$. 
    \begin{itemize}
        \item \textbf{Bounding $\|({\mathbf{I}} - {\mathbf{U}}_k{\mathbf{U}}_k^{\top})\Delta_k \|_{2,\infty}$}.  First, observe that we can write $\Delta_k$ via $\Delta_k = \varepsilon \begin{pmatrix} \mathbf{v}^{\top} \\ \mathbf{0} \end{pmatrix} \mathbf{\Lambda}_k^{-1}$, where $\mathbf{v} \in \{-1,1\}^{r_k}$ is a vector of signs.  Therefore,
        \begin{align*}
            \| (\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top}) \Delta_k \|_{2,\infty} &\leq \frac{\varepsilon}{\lambda} \| (\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top})\begin{pmatrix} \mathbf{v}^{\top} \\ \mathbf{0} \end{pmatrix} \|_{2,\infty}.
        \end{align*}
Since $\mathbf{v}$ is a vector of signs, the matrix $ (\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top})\begin{pmatrix} \mathbf{v}^{\top} \\ \mathbf{0} \end{pmatrix}$ is simply the rank one matrix whose columns are the entries of the first row of the matrix $(\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top})$.  Consequently, $\| (\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top})\begin{pmatrix} \mathbf{v}^{\top} \\ \mathbf{0} \end{pmatrix}\|_{2,\infty} \leq \| (\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top})\begin{pmatrix} \mathbf{v}^{\top} \\ \mathbf{0} \end{pmatrix}\| \leq \sqrt{r_k}$.  Combining these bounds yields that
\begin{align*}
    \| ({\mathbf{I}} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} ) \Delta_k \|_{2,\infty} &\leq \frac{\varepsilon \sqrt{r_k}}{\lambda}.
\end{align*}
        \item \textbf{Bounding $\|\mathbf{C}_{\Delta_k}^{-1/2} - {\mathbf{I}} \|$}. 
        Observe that
        \begin{align*}
            \| \mathbf{C}_{\Delta_k}^{-1/2} - {\mathbf{I}} \| &\leq \| \mathbf{C}_{\Delta_k}^{-1/2} ( {\mathbf{I}} - \mathbf{C}_{\Delta_k}^{1/2}) \| \leq \| \mathbf{C}_{\Delta_k}^{-1/2} \| \| {\mathbf{I}} - \mathbf{C}_{\Delta_k}^{1/2} \|.
        \end{align*}
        By Theorem 6.2 of \cite{higham_functions_2008}, it holds that
        \begin{align*}
            \| {\mathbf{I}} - \mathbf{C}_{\Delta_k}^{1/2} \| &\leq \frac{1}{\lambda_{\min}^{1/2}(\mathbf{C}_{\Delta_k}) + 1} \| {\mathbf{I}} - \mathbf{C}_{\Delta_k} \| \\
            &\leq \| \Delta_k^{\top} (\mathbf{I} - {\mathbf{U}}_k {\mathbf{U}}_k^{\top})^2 \Delta_k \| \\
            &\leq \frac{\varepsilon^2 r_k}{\lambda^2},
        \end{align*}
        where we have implicitly implied a similar argument to the previous bound.  As a result, we see that as long as $1 - \frac{\varepsilon^2}{\lambda^2} \geq \frac{1}{2}$, we have that $\lambda_{\min}(\mathbf{C}_{\Delta_k}) \geq \frac{1}{2}$ by Weyl's inequality.  Therefore,
        \begin{align*}
            \| \mathbf{C}_{\Delta_k}^{1/2} - {\mathbf{I}} \| \leq 2 \frac{\varepsilon^2 r_k}{\lambda^2}.
        \end{align*}
    \end{itemize}
    Combining our bounds and plugging this inequality into \eqref{incoherence}, we have that
    \begin{align*}
        \| \mathbf{\bar U}_k \|_{2,\infty} &\leq \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}} + \frac{\varepsilon\sqrt{r_k}}{\lambda} + \bigg( \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}} + \frac{\varepsilon\sqrt{r_k}}{\lambda} \bigg) \frac{2\varepsilon^2 r_k}{\lambda^2} \\
        &\leq  \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}} + \frac{\varepsilon\sqrt{r_k} }{\lambda/\sigma} +  \bigg( \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}} + \frac{\varepsilon \sqrt{r_k}}{\lambda/\sigma} \bigg) \frac{2\varepsilon^2 r_k}{(\lambda/\sigma)^2} \\
        &\leq \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}} + \frac{\varepsilon\sqrt{r_k} }{C_0 \sqrt{p_k}} +  \bigg( \frac{\mu_0}{2} \sqrt{\frac{r_k}{p_k}} + \frac{\varepsilon\sqrt{r_k}}{C_0 \sqrt{p_k}} \bigg) \frac{2\varepsilon^2 r_k}{C_0^2 p_k} \\
&\leq\mu_0\sqrt{\frac{r_k}{p_k}},
    \end{align*}
    where the final inequality holds for $\varepsilon$ sufficiently small, the second inequality holds from the fact that $\sigma \geq \sigma_{\min} = 1$, and the penultimate inequality holds from the assumption $\lambda/\sigma \geq C_0 \kappa r_{\max} \sqrt{p_{\max}}$.  
    \item \textbf{Step 2: Upper bounding $\chi^2(f_{{\pi_{\mathcal{H}_1}}},f_{{\pi_{\mathcal{H}_0}}})$} Similar to the proof of \cref{thm:efficiency_order}, it holds that
\begin{align*}
    \chi^2 ( f_{{\pi_{\mathcal{H}_1}}}, f_{\pi_{\mathcal{H}_0}}) &\leq \exp\bigg( \| \mathcal{\bar T} - \mathcal{T} \|_F^2 \bigg) - 1.
\end{align*}
Therefore,
\begin{align*}
    \| \mathcal{\bar T - \mathcal{T}} \|_F &= \| \mathcal{C} \times_1 \mathbf{\bar U}_1 \times_2 \mathbf{\bar U}_2 \times_3 \mathbf{\bar U}_3 - \mathcal{C} \times_1 {\mathbf{U}}_1 \times_2 {\mathbf{U}}_2 \times_3 {\mathbf{U}}_3 \|_F \\
    &\leq \| \mathcal{C} \times_1 (\mathbf{\bar U}_1 - {\mathbf{U}}_1) \times_2 \mathbf{\bar U}_2 \times_3 \mathbf{\bar U}_3 \|_F \\
    &\quad + \| \mathcal{C} \times_1 {\mathbf{U}}_1 \times_2 (\mathbf{\bar U}_2 - {\mathbf{U}}_2) \times_3 \mathbf{\bar U}_3 \|_F \\
    &\quad + \| \mathcal{C} \times_1 {\mathbf{U}}_1 \times_2 {\mathbf{U}}_2 \times_3 ( \mathbf{\bar U}_3 - {\mathbf{U}}_3) \|_F \\
    &= \| (\mathbf{\bar U}_1 - {\mathbf{U}}_1) \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \|_F \\
    &\quad + \| (\mathbf{\bar U}_2 - {\mathbf{U}}_2) \mathcal{M}_2(\mathcal{C}) (\mathbf{ U}_1 \otimes \mathbf{\bar U}_3)^{\top} \|_F \\
     &\quad +  \| (\mathbf{\bar U}_3 - {\mathbf{U}}_3) \mathcal{M}_3(\mathcal{C}) (\mathbf{ U}_1 \otimes \mathbf{ U}_2)^{\top} \|_F.
\end{align*}
We now consider an upper bound for the first term; the remaining two terms are similar.  From \eqref{ukbarexpression} we have that
\begin{align*}
    \| (\mathbf{\bar U}_1 &- {\mathbf{U}}_1) \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \|_F \\
    &\leq  \| ({\mathbf{I}} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )\Delta_1 \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \|_F \\
    &\quad + \bigg\|\bigg({\mathbf{U}}_1+  ({\mathbf{I}} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )\Delta_1 \bigg) \bigg( \mathbf{C}_{\Delta_1}^{-1/2}- {\mathbf{I}}\bigg) \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \bigg\|_F \\
    &\leq \underbrace{\| ({\mathbf{I}} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )\Delta_1 \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \|}_{\alpha_1} \\
    &\quad + \underbrace{\bigg\|  ({\mathbf{I}} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} )\Delta_1 \bigg( \mathbf{C}_{\Delta_1}^{-1/2}- {\mathbf{I}}\bigg) \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \bigg\|}_{\alpha_2} \\
    &\quad + \underbrace{\bigg\|  {\mathbf{U}}_1  \bigg( \mathbf{C}_{\Delta_1}^{-1/2}- {\mathbf{I}}\bigg) \mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3)^{\top} \bigg\|_F}_{\alpha_3},
\end{align*}
where we have passed from the Frobenius norm to the operator norm in the first two terms since the matrix $(\mathbf{I} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top})\Delta_k$ is rank one.  We now bound $\alpha_1$ through $\alpha_3$.
\begin{itemize}
    \item \textbf{Bounding $\alpha_1$.} Recall that $\Delta_1 = \varepsilon \begin{pmatrix} \mathbf{v}^{\top} \\ 0 \end{pmatrix} \mathbf{\Lambda}_k^{-1}$, where $\mathbf{v}$ is a matrix of signs.  Therefore,
    \begin{align*}
        \alpha_1 &\leq \varepsilon \| \big( {\mathbf{I}} - {\mathbf{U}}_1 {\mathbf{U}}_1^{\top} \big) \begin{pmatrix} \mathbf{v}^{\top} \\ 0 \end{pmatrix} \mathbf{\Lambda}_k^{-1} \mathcal{M}_1(\mathcal{C}) \big( \mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3\big)^{\top} \|.
    \end{align*}
    Next, note that $\mathcal{M}_1(\mathcal{C}) (\mathbf{\bar U}_2\otimes \mathbf{\bar U}_3)^{\top}$ has the same nonzero singular values as $\mathcal{M}_1(\mathcal{C})$ and hence also $\mathcal{T}$.  Therefore, $\| \mathbf{\Lambda}_k^{-1} \mathcal{M}_1(\mathcal{C}) \big( \mathbf{\bar U}_2 \otimes \mathbf{\bar U}_3\big)^{\top} \| =  1$.  As a consequence,
    \begin{align*}
        \alpha_1 \leq \varepsilon.
    \end{align*}
    \item \textbf{Bounding $\alpha_2$.}  We observe that
    \begin{align*}
        \alpha_2 &\leq \frac{\varepsilon \sqrt{r_1}}{\lambda} \lambda_1 \| \mathbf{C}_{\Delta_1}^{-1/2} - {\mathbf{I}} \| \leq \varepsilon \frac{\varepsilon^2 \kappa r^{3/2}}{\lambda^2}\leq \varepsilon \frac{\varepsilon^2 \kappa r^{3/2}}{(\lambda/\sigma)^2}\leq \varepsilon,
    \end{align*}
    where we have used the assumption that $\lambda/\sigma \geq C_0 r \kappa \sqrt{p}$, together with the previous bounds.
    \item \textbf{Bounding $\alpha_3$.} We have that
    \begin{align*}
        \alpha_3 &\leq \| \mathbf{C}_{\Delta_1}^{-1/2} - {\mathbf{I}} \| \lambda_1 \sqrt{r_1}\\
        &\leq \varepsilon \frac{\varepsilon r_1^{3/2} \kappa }{\lambda} \\
        &\leq \varepsilon\frac{\varepsilon r_1^{3/2} \kappa }{\lambda/\sigma} \\
        &\leq \varepsilon,
    \end{align*}
    where we have used the assumptions $\lambda/\sigma \geq C_0 \kappa r \sqrt{p}$ and $r_k \leq p_{\max}^{1/2}$.  
\end{itemize}
As a consequence, we have that
\begin{align*}
    \| \mathcal{\bar T} - \mathcal{T} \|_F &\leq 9 \varepsilon.
\end{align*}Therefore,
\begin{align*}
    \chi^2(f_{{\pi_{\mathcal{H}_1}}}, f_{\pi_{\mathcal{H}_0}}) \leq \exp\bigg( 81 \varepsilon^2 \bigg) - 1.
