\end{align*}
where now we choose the sign of $\mathbf{v}_k \in \{-1,1\}^{r_k}$ by taking the sign of the entries of $e_{1}^{\top} \mathbf{V}_k$. For these choices of $\mathbf{v}_k$, \eqref{eq:desiredbound} implies
\begin{align*}
    |  \mathcal{\bar T}_{111} - \mathcal{T}_{111} | &\geq c \varepsilon \bigg( \big\| e_{1}^{\top} \mathbf{V}_1 \big\|_1 + \big\| e_{1}^{\top} \mathbf{V}_2 \big\|_1 + \big\| e_{1}^{\top} \mathbf{V}_3 \big\|_1 \bigg) \\
    &\geq c \varepsilon \bigg( \big\| e_{1}^{\top} \mathbf{V}_1 \big\|_2 + \big\| e_{1}^{\top} \mathbf{V}_2 \big\|_2 + \big\| e_{1}^{\top} \mathbf{V}_3 \big\|_2 \bigg) \\
    &\geq c \varepsilon \sqrt{ \big\|e_{1}^{\top} \mathbf{V}_1 \big\|_2^2 + \big\| e_{1}^{\top} \mathbf{V}_2 \big\|_2^2 + \big\| e_{1}^{\top} \mathbf{V}_3 \big\|_2^2} . \addtocounter{equation}{1}\tag{\theequation} \label{lowerboundtoprovetoday}
\end{align*}
We therefore prove \eqref{eq:desiredbound}.  Observe that
\begin{align*}
    \mathcal{\bar T}_{ijk} - \mathcal{T}_{ijk} &= \sum_{l_1=1}^{r_1} \sum_{l_2=1}^{r_2} \sum_{l_3=1}^{r_3} \mathcal{C}_{l_1l_2l_3} \bigg(\big(\mathbf{\bar U}_1\big)_{il_1} \big(\mathbf{\bar U}_2\big)_{jl_2} \big(\mathbf{\bar U}_3\big)_{kl_3} -  \big({\mathbf{U}}_1\big)_{il_1} \big({\mathbf{U}}_2\big)_{jl_2} \big({\mathbf{U}}_3\big)_{kl_3} \bigg).
    \end{align*}
According to \eqref{ukbarexpression} we have that
\begin{align*}
    \mathbf{\bar U}_k - {\mathbf{U}}_k 
    &= \Delta_k  +  \underbrace{\bigg( {\mathbf{U}}_k + ({\mathbf{I}} -{\mathbf{U}}_k{\mathbf{U}}_k^{\top})\Delta_k \bigg) \bigg( \mathbf{C}_{\Delta_k}^{-1/2} - {\mathbf{I}} \bigg) - {\mathbf{U}}_k {\mathbf{U}}_k^{\top} \Delta_k }_{\Gamma_k},
\end{align*}
allowing us to write
\begin{align*}
    \mathbf{\bar U}_k = {\mathbf{U}}_k +\Delta_k  + \Gamma_k.
\end{align*}
From this expression, we have that
\begin{align*}
  \big(\mathbf{\bar U}_1\big)_{il_1} &\big(\mathbf{\bar U}_2\big)_{jl_2} \big(\mathbf{\bar U}_3\big)_{kl_3} -  \big({\mathbf{U}}_1\big)_{il_1} \big({\mathbf{U}}_2\big)_{jl_2} \big({\mathbf{U}}_3\big)_{kl_3} \\
  &=  \big(\mathbf{ U}_1 + \Delta_1 + \Gamma_1\big)_{il_1} \big(\mathbf{ U}_2 + \Delta_2 + \Gamma_2\big)_{jl_2} \big(\mathbf{ U}_3 + \Delta_3 + \Gamma_3\big)_{kl_3} \\
  &\quad -  \big({\mathbf{U}}_1\big)_{il_1} \big({\mathbf{U}}_2\big)_{jl_2} \big({\mathbf{U}}_3\big)_{kl_3} \\


  &= (\Delta_1)_{1l_1} ({\mathbf{U}}_2)_{2l_2} ({\mathbf{U}}_3)_{3l_3} + ({\mathbf{U}}_1)_{1l_1}  \Delta_2  {\mathbf{U}}_3 + ({\mathbf{U}}_1)_{1l_1} {\mathbf{U}}_2 \Delta_3 + \mathcal{R}_{l_1l_2l_3},
\end{align*}
where $\mathcal{R}_{l_1l_2l_3}$ contains all of the cross terms with at least two appearances of $\Delta$ or at least one appearance of $\Gamma$.  

We will demonstrate that $\mathcal{R}$ is a lower-order term. First, note that $\Delta_k$ and $\Gamma_k$ satisfy
\begin{align*}
    \| e_1^{\top} \Delta_k \| &\leq \frac{\varepsilon \sqrt{r_k}}{\lambda}; \\
    \|e_1^{\top} \Gamma_k \| &\leq \bigg( \| {\mathbf{U}}_k \|_{2,\infty} + \frac{\varepsilon \sqrt{r_k}}{\lambda} \bigg) \frac{2 \varepsilon^2 r_k}{\lambda^2} + \| {\mathbf{U}}_k \|_{2,\infty} \frac{\varepsilon \sqrt{r_k}}{\lambda} \\
    &\leq \frac{4 \varepsilon \mu_0 r_k}{\lambda \sqrt{p_k}}. 
\end{align*}
We now bound $\mathcal{R}$ directly.  There are 8 possible subcases over the possible times $\Delta,\Gamma$, and ${\mathbf{U}}$ appear, subject to the fact that $\Delta$ must appear with either another $\Delta$ or with $\Gamma$, and ${\mathbf{U}}$ does not appear three times. Consider, for example the case that $\Delta$ appears twice and ${\mathbf{U}}$ appears once.  In this case we have
    \begin{align*}
        \bigg| \sum_{l_1l_2l_3} \mathcal{C}_{l_1l_2l_3} \big( \Delta_{1} \big)_{1l_1} \big( \Delta_2 \big)_{1l_2} \big( {\mathbf{U}}_3 \big)_{1l_3} \bigg| &= \bigg| e_1 ^{\top} {\mathbf{U}}_3 \mathcal{M}_3(\mathcal{C}) \big( \Delta_1 \otimes \Delta_2 \big) e_1 \bigg| \\
        &\leq \| e_1^{\top} {\mathbf{U}}_3 \| \lambda_1 \| e_1^{\top} \Delta_1 \| \| e_1^{\top} \Delta_2 \| \\
        &\leq \mu_0 \sqrt{\frac{r_k}{p_k}} \frac{\varepsilon^2 r_k \kappa }{\lambda}.
    \end{align*}
The other possible subcases are all extremely similar, and all satisfy the same upper bound up to some constant by virtue of the bounds on $\|\Gamma_k\|_{2,\infty}$ and $\|\Delta_k\|_{2,\infty}$.  As a result, there exists some universal constant $C$ such that
\begin{align*}
    \bigg| \sum_{l_1l_2l_3} \mathcal{C}_{l_1l_2l_3} \mathcal{R}_{l_1l_2l_3} \bigg| &\leq C \mu_0 \sqrt{\frac{r_k}{p_k}} \frac{\varepsilon^2 r_k \kappa }{\lambda}.
\end{align*}




















